window.HS_LOAD(2,{"intro":[[["نبی کریم ",""],["ﷺ","a"],[" اور آپؐ کے صحابہ کرامؓ کس طرح مسجدوں میں نمازوں کے لیے جمع ہوتے تھے، خود انہیں نمازوں کا کتنا شوق تھا اور دوسروں کو نماز کی کتنی ترغیب دیتے تھے، اور نمازوں کے اوقات کے بدلنے سے وہ یہ سمجھتے تھے کہ ہمارا اصل کام ایک حکم خداوندی سے دوسرے حکم میں اور ایک عمل صالح سے دوسرے عمل میں لگنا ہے، اور انہیں ان اعمال کا حکم دیا جاتا تھا کہ وہ ایمان اور ایمانی صفات کو پکا کریں، علم اور علم والے اعمال کو پھیلائیں اور ",""],["ٱللَّٰه","a"],[" کے ذکر کو زندہ کریں اور دعا کو اور اس کی قبولیت کی شرائط کو قائم کریں۔ چنانچہ وہ کس طرح سے ان اعمال کی وجہ سے اپنے دنیاوی مشاغل کو چھوڑ دیا کرتے تھے، ایسا معلوم ہوتا تھا کہ انہیں ظاہری شکلوں کی طرف کوئی توجہ نہیں ہے بلکہ وہ تو اس ذات سے براہ راست فائدہ حاصل کرتے ہیں جو تمام چیزوں اور شکلوں کو پیدا کرنے والی اور ان میں تصرف کرنے والی ہے۔",""]]],"topics":{"19":{"lead":[],"stories":[{"b":[["n",[["حضرت عثمانؓ کے آزاد کردہ غلام حضرت حارثؒ","b"],[" کہتے ہیں کہ ایک دن حضرت عثمانؓ بیٹھے ہوئے تھے، ہم بھی ان کے ساتھ بیٹھے ہوئے تھے، اتنے میں مؤذن آیا تو حضرت عثمانؓ نے ایک برتن میں پانی منگوایا، میرا خیال ہے کہ اس میں ایک مد (تقریباً چودہ چھٹانک) پانی آتا ہوگا، اس سے وضو کیا، پھر فرمایا کہ میں نے اب وضو کیا ہے جیسا کہ حضورؐ کو میں نے ایسا ہی وضو کرتے ہوئے دیکھا۔ پھر حضورؐ نے فرمایا:",""]]],["c",[["جو میرے اس وضو جیسا وضو کرے گا پھر کھڑے ہو کر ظہر کی نماز پڑھے گا تو اس کے ظہر اور فجر کے درمیان کے گناہ معاف کر دیے جائیں گے۔ پھر وہ عصر کی نماز پڑھے گا تو اس کے ظہر اور عصر کے درمیان کے گناہ معاف کر دیے جائیں گے۔ پھر وہ مغرب کی نماز پڑھے گا تو مغرب اور عصر کے درمیان کے گناہ معاف کر دیے جائیں گے۔ پھر وہ عشاء کی نماز پڑھے گا تو عشاء اور مغرب کے درمیان کے گناہ معاف کر دیے جائیں گے۔ پھر وہ ساری رات کروٹیں بدلتے ہوئے گزار دے گا۔ پھر وہ اٹھ کر وضو کر کے فجر کی نماز پڑھے گا تو اس کے فجر اور عشاء کے درمیان کے گناہ معاف کر دیے جائیں گے۔ یہی وہ نیکیاں ہیں جو گناہوں کو دور کر دیتی ہیں۔",""]]],["p",[["مجلس کے ساتھیوں نے پوچھا اے عثمان! یہ تو حسنات ہو گئیں تو باقیات صالحات کیا ہوں گی؟ حضرت عثمانؓ نے کہا باقیات صالحات یہ کلمات ہیں: ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["، سبحان ",""],["ٱللَّٰه","a"],["، الحمد للہ، ",""],["ٱللَّٰه","a"],[" اکبر، ولا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوعثمانؒ","b"],[" کہتے ہیں کہ میں حضرت سلمانؓ کے ساتھ ایک درخت کے نیچے تھا، انہوں نے اس درخت کی ایک خشک ٹہنی پکڑ کر اسے حرکت دی جس سے اس کے پتے گر گئے۔ مجھ سے کہنے لگے کہ ابو عثمان! تم نے مجھ سے یہ نہ پوچھا کہ میں نے اس طرح کیوں کیا؟ میں نے کہا بتا دیجیے کیوں کیا؟ انہوں نے کہا کہ میں ایک دفعہ نبی اکرم ",""],["ﷺ","a"],[" کے ساتھ ایک درخت کے نیچے تھا، آپؐ نے بھی درخت کی ایک خشک ٹہنی پکڑ کر اسی طرح حرکت دی جس سے اس ٹہنی کے پتے جھڑ گئے تھے۔ پھر حضورؐ نے ارشاد فرمایا تھا کہ سلمان! پوچھتے نہیں کہ میں نے اس طرح کیوں کیا؟ میں نے عرض کیا کہ بتا دیجیے کیوں کیا؟ آپؐ نے ارشاد فرمایا تھا کہ ",""],["جب مسلمان اچھی طرح سے وضو کرتا ہے پھر پانچوں نمازیں پڑھتا ہے تو اس کی خطائیں اس سے ایسے ہی گر جاتی ہیں جیسے یہ پتے گرتے ہیں۔","h"],[" پھر آپؐ نے یہ آیت پڑھی:",""]]],["q",[["وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ ۚ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ۚ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ  (سورۃ ہود: ۱۱۴)","a"]]],["p",[["ترجمہ: \"اور آپ نماز کی پابندی رکھیے دن کے دونوں سروں پر اور رات کے کچھ حصوں میں، بیشک نیک کام مٹا دیتے ہیں برے کاموں کو، یہ بات ایک نصیحت ہے نصیحت ماننے والوں کے لیے۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت عامر بن سعد بن ابی وقاصؓ","b"],[" کہتے ہیں کہ میں نے حضرت سعدؓ اور نبی کریم ",""],["ﷺ","a"],[" کے چند صحابہؓ کو یہ واقعہ بیان کرتے ہوئے سنا کہ حضورؐ کے زمانے میں دو بھائی تھے، ان میں سے ایک دوسرے سے افضل اور زیادہ نیک تھا۔ تو جو افضل تھا اس کا تو انتقال ہو گیا اور دوسرا ایک عرصہ تک زندہ رہا پھر اس کا بھی انتقال ہو گیا۔ پھر کسی نے حضورؐ کے سامنے یہ کہا کہ پہلا بھائی دوسرے سے فضیلت اور نیکی میں زیادہ تھا۔ حضورؐ نے فرمایا کیا دوسرا نماز نہیں پڑھتا تھا؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! پڑھتا تھا۔ حضورؐ نے فرمایا تمہیں کیا معلوم اسے اس کی نمازوں نے کہاں تک پہنچا دیا؟ پھر حضورؐ نے اس موقعہ پر فرمایا:",""]]],["c",[["نماز کی مثال ایسی ہے کہ کسی کے دروازے پر ایک نہر ہو جس کا پانی جاری ہو، گہرا اور میٹھا ہو اور وہ روزانہ اس میں پانچ مرتبہ غسل کرے تو تمہارا کیا خیال ہے کیا اس کی میل میں سے کچھ باقی رہے گا؟",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.297). Maalik, Nasa'ee and Ibn Khuzaymah have reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.206)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ قبیلہ قضاعہ کی شاخ بنو بلی کے دو آدمی ایک ساتھ مسلمان ہوئے۔ ان میں سے ایک صاحب جہاد میں شہید ہو گئے اور دوسرے صاحب کا ایک سال بعد انتقال ہوا۔ حضرت طلحہ بن عبید",""],["ٱللَّٰه","a"],["ؓ کہتے ہیں کہ میں نے خواب میں دیکھا کہ وہ صاحب جن کا ایک سال بعد انتقال ہوا تھا ان شہید سے بھی پہلے جنت میں داخل ہوتے ہیں۔ میں نے حضورؐ سے خود عرض کیا یا کسی اور نے عرض کیا تو حضورؐ اقدس نے فرمایا کہ جن صاحب کا بعد میں انتقال ہوا ان کی نیکیاں نہیں دیکھتے کتنی زیادہ ہو گئیں؟ ایک رمضان المبارک کے پورے روزے بھی ان کے زیادہ ہو گئے اور چھ ہزار اور اتنی رکعتیں نماز ایک سال میں ان کی بڑھ گئیں۔",""],["(2)","s"],[" ابن ماجہ اور ابن حبان کی روایت کے آخر میں یہ بھی ہے کہ ان دونوں کے درجوں میں اتنا فرق ہے جتنا زمین اور آسمان کے درمیان۔",""],[" (3)","s"]]]],"f":[["(2)","Ahmad, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.208)."],["(3)","Ibn Maajah and Ibn Hibbaan."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ ہم لوگ مسجد میں حضورؐ کے ساتھ نماز کا انتظار کر رہے تھے کہ ایک آدمی نے کھڑے ہو کر حضورؐ سے عرض کیا کہ مجھ سے گناہ ہو گیا ہے۔ حضورؐ نے اس سے منہ پھیر لیا۔ جب آپؐ نماز سے فارغ ہوئے تو اس آدمی نے کھڑے ہو کر دوبارہ وہی بات کہی۔ حضورؐ نے فرمایا کیا تم نے ہمارے ساتھ یہ نماز نہیں پڑھی اور کیا تم نے اس نماز کے لیے اچھی طرح وضو نہیں کیا؟ اس نے کہا کیوں نہیں۔ حضورؐ نے فرمایا:",""]]],["c",[["یہ نماز تیرے اس گناہ کا کفارہ ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani. Haythami (Vol.1 Pg.301) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر پوچھا کہ سب سے افضل عمل کونسا ہے؟ حضورؐ نے فرمایا نماز۔ اس نے پوچھا پھر کیا؟ حضورؐ نے فرمایا نماز۔ تین دفعہ حضورؐ نے یہی جواب دیا۔ جب اس نے حضورؐ سے بار بار یہی سوال کیا تو حضورؐ نے فرمایا نماز کے بعد افضل عمل جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" ہے۔ اس آدمی نے کہا میرے والدین حیات ہیں۔ حضورؐ نے فرمایا میں تمہیں والدین کے ساتھ حسن سلوک کا حکم دیتا ہوں۔ اس آدمی نے کہا اس ذات کی قسم جس نے آپؐ کو حق دے کر اور نبی بنا کر بھیجا ہے! میں جہاد ضرور کروں گا اور دونوں کو چھوڑ جاؤں گا۔ حضورؐ نے فرمایا اسے تم مجھ سے زیادہ جانتے ہو (کہ تمہارے والدین محتاج خدمت ہیں یا نہیں اور تمہارے علاوہ کوئی اور خدمت کرنے والا ہے یا نہیں)۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad. Haythami (Vol.1 Pg.301) has commented on the chain of narrators. Ibn Hibbaan has reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت عمرو بن مرہ جہنیؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ذرا مجھے یہ بتائیں کہ اگر میں اس بات کی گواہی دوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور آپؐ ",""],["ٱللَّٰه","a"],[" کے رسول ہیں اور پانچوں نمازیں پڑھوں اور زکوٰۃ ادا کروں اور رمضان شریف کے روزے رکھوں اور اس میں رات کو نفل نماز بھی پڑھوں تو میں کن لوگوں میں شمار ہوں گا؟ حضورؐ نے فرمایا:",""]]],["c",[["صدیقین اور شہداء میں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Khuzaymah and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.200)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ وفات کے وقت حضورؐ بار بار یہی وصیت فرماتے رہے کہ نماز کا اور اپنے غلاموں کا خیال رکھنا۔ آپؐ یہ وصیت فرماتے رہے یہاں تک کہ غرغرہ کی حالت شروع ہو گئی اور زبان سے یہ کلمات ادا نہیں ہو رہے تھے۔",""],["(7)","s"],[" امام احمد نے یہی حدیث حضرت انسؓ سے اس طرح نقل کی ہے کہ انتقال کے وقت حضورؐ بار بار یہی وصیت فرماتے رہے کہ نماز کا اور اپنے غلاموں کا خیال رکھنا۔ آپؐ یہ وصیت فرماتے رہے یہاں تک کہ سینے میں سانس اکھڑ گیا اور آپؐ کی زبان سے یہ الفاظ پورے طور سے ادا نہیں ہو رہے تھے۔",""],[" (8)","s"]]]],"f":[["(7)","Bayhaqi, Nasa'ee and Ibn Maajah."],["(8)","Ahmad."]]},{"b":[["n",[["اور ",""],["حضرت علیؓ","b"],[" کی روایت میں یوں ہے کہ حضورؐ نے مجھے اس بات کا حکم دیا کہ میں ان کے پاس بڑی طشتری جیسی پھیلی ہوئی کوئی چیز لاؤں جس پر حضورؐ وہ بات لکھوا دیں جس کے بعد حضورؐ کی امت گمراہ نہ ہو سکے۔ حضرت علیؓ فرماتے ہیں کہ مجھے یہ خطرہ ہوا کہ کہیں میرے جانے کے بعد حضورؐ کا انتقال نہ ہو جائے، اس لیے میں نے عرض کیا میں آپؐ کی بات زبانی سمجھ لوں گا اور یاد رکھ لوں گا۔ حضورؐ نے فرمایا میں نماز، زکوٰۃ اور غلاموں کے خیال رکھنے کی وصیت کرتا ہوں۔",""],["(9)","s"],[" ابن سعد نے حضرت علیؓ سے بھی اسی جیسی حدیث روایت کی ہے اور اس میں یہ بھی ہے کہ پھر حضورؐ نماز، زکوٰۃ اور غلاموں کے خیال رکھنے کی مسلسل وصیت فرماتے رہے یہاں تک کہ آپؐ کی روح پرواز کر گئی اور اس طرح روح پرواز کرنے تک آپؐ کلمہ شہادت اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" واشھد ان محمدا عبدہ و رسولہ پڑھنے کی وصیت فرماتے رہے اور یہ بھی فرمایا جو بھی (شہادت کی) ان دونوں باتوں کی گواہی دے گا اسے آگ پر ضرور حرام کر دیا جائے گا۔",""],[" (10)","s"]]],["p",[["حضرت علیؓ کی دوسری حدیث میں یہ ہے کہ حضورؐ نے آخری بات یہ فرمائی: نماز اور غلاموں کے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو۔",""],[" (11)","s"]]]],"f":[["(9)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.238)."],["(10)","Ibn Sa'd (Vol.2 Pg.243)."],["(11)","Ahmad, Bukhaari in his Adab, Abu Dawood, Ibn Maajah, Ibn Jareer, Abu Ya'la and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.180)."]]}]},"20":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوبکرؓ","b"],[" فرماتے ہیں کہ نماز پڑھنے سے انسان زمین پر ",""],["ٱللَّٰه","a"],[" کی حفظ و امان میں آ جاتا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Hakeem."]]},{"b":[["n",[["حضرت ابوالملیحؒ","b"],[" کہتے ہیں کہ میں نے حضرت عمر بن خطابؓ کو منبر پر یہ فرماتے ہوئے سنا کہ جو نماز نہ پڑھے اس کا کوئی اسلام نہیں ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd, as quoted in Kanzul Ummaal (Vol.4 Pg.180)."]]},{"b":[["n",[["حضرت زید بن ثابتؓ","b"],[" فرماتے ہیں کہ آدمی کا اپنے گھر میں (نفل) نماز پڑھنا نور ہے اور جب آدمی نماز کے لیے کھڑا ہوتا ہے تو اس کے گناہ اس کے اوپر لٹکا دیے جاتے ہیں اور جب وہ سجدہ کرتا ہے تو اس سجدے کی وجہ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی خطائیں مٹا دیتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abdur Razzaaq."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں کہ بندہ جب وضو کرتا ہے اور اچھی طرح وضو کرتا ہے پھر نماز کے لیے کھڑا ہو جاتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی طرف متوجہ ہو کر اس سے سرگوشی کرتے ہیں اور جب تک بندہ دوسری طرف متوجہ نہ ہو اور دائیں بائیں نہ دیکھے اس وقت تک ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی طرف متوجہ رہتے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Abdur Razzaaq."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ نماز بہت بڑی نیکی ہے اور مجھے اس کی کوئی پرواہ نہیں کہ میرے ساتھ نماز میں کون شریک ہوا۔",""],[" (5)","s"]]]],"f":[["(5)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ جو بھی مسلمان کسی اونچی زمین میں جا کر یا پتھروں سے بنی ہوئی مسجد میں جا کر نماز پڑھتا ہے تو زمین یہ کہتی ہے کہ اس مسلمان نے ",""],["ٱللَّٰه","a"],[" کی زمین پر ",""],["ٱللَّٰه","a"],[" کے لیے نماز پڑھی، (اے بندے!) جس دن تو ",""],["ٱللَّٰه","a"],[" سے ملاقات کرے گا اس دن میں تیرے حق میں گواہی دوں گی۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Asaakir."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضرت آدمؑ کی گردن میں پھوڑا نکل آیا۔ انہوں نے نماز پڑھی تو وہ پھوڑا نیچے اتر کر سینے پر آ گیا۔ حضرت آدمؑ نے پھر نماز پڑھی تو وہ کوکھ میں آ گیا۔ انہوں نے پھر نماز پڑھی تو وہ گھٹنے میں آ گیا۔ انہوں نے پھر نماز پڑھی تو انگوٹھے میں آ گیا۔ انہوں نے پھر نماز پڑھی تو وہ چلا گیا۔",""],[" (7)","s"]]]],"f":[["(7)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ جب تک تم نماز میں ہوتے ہو بادشاہ کا دروازہ کھٹکھٹاتے ہو اور جو بادشاہ کا دروازہ کھٹکھٹاتا ہے اس کے لیے دروازہ ضرور کھلتا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilya (Vol.1 Pg.130)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ اپنی ضرورتیں فرض نمازوں پر ایثار کرو، یعنی فرض نمازوں کے بعد اپنی ضرورتیں ",""],["ٱللَّٰه","a"],[" سے مانگو۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ جب تک آدمی کبیرہ گناہوں سے بچتا رہے گا اس وقت تک ایک نماز سے لے کر دوسری نماز تک کے درمیان جتنے گناہ کیے ہوں گے وہ سارے گناہ اگلی نماز سے معاف ہو جائیں گے۔",""],[" (9)","s"]]]],"f":[["(9)","Abdur Razzaaq."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ نمازیں بعد والے گناہوں کے لیے کفارہ ہوتی ہیں۔ حضرت آدمؑ کے پاؤں کے انگوٹھے میں ایک پھوڑا نکل آیا تھا، پھر وہ پھوڑا اچھڑ کر پاؤں کی جڑ یعنی ایڑی میں آ گیا، پھر چڑھ کر گھٹنوں میں آ گیا، پھر کوکھ میں آ گیا، پھر چڑھ کر گردن کی جڑ میں آ گیا۔ پھر حضرت آدمؑ نے کھڑے ہو کر نماز پڑھی تو وہ پھوڑا کندھوں سے نیچے آ گیا۔ انہوں نے پھر نماز پڑھی تو اتر کر ان کی کوکھ میں آ گیا، پھر نماز پڑھی تو اتر کر گھٹنوں میں آ گیا، پھر نماز پڑھی تو اتر کر قدموں میں آ گیا، پھر نماز پڑھی تو وہ پھوڑا ختم ہو گیا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت سلمان فارسیؓ","b"],[" فرماتے ہیں کہ بندہ جب نماز کے لیے کھڑا ہوتا ہے تو اس کی خطائیں اس کے سر پر رکھ دی جاتی ہیں اور جب نماز سے فارغ ہوتا ہے تو اس کی خطائیں اس سے ایسے جدا ہو چکی ہوتی ہیں جیسے کھجور کی ٹہنیاں دائیں بائیں گر کر درخت سے جدا ہو جاتی ہیں۔",""],[" (11)","s"]]]],"f":[["(11)","Abdur Razzaaq."]]},{"b":[["n",[["حضرت سلمانؓ","b"],[" فرماتے ہیں کہ جب بندہ نماز پڑھنے لگتا ہے تو اس کے گناہ اس کے سر کے اوپر جمع ہو جاتے ہیں، پھر جب وہ سجدہ کرتا ہے تو وہ گناہ درخت کے پتوں کی طرح گرنے لگ جاتے ہیں۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Zanjway."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" نے حضرت سلمانؓ کی عبادت میں محنت کو دیکھنے کے لیے ان کے پاس ایک رات گزاری تو انہوں نے یہ دیکھا کہ (حضرت سلمانؓ رات بھر سوتے رہے اور) رات کے آخری حصے میں انھوں نے کھڑے ہو کر تہجد کی نماز پڑھی۔ حضرت سلمانؓ کی کثرت عبادت کا جیسا خیال حضرت طارقؒ کا تھا ویسا انھوں نے نہ دیکھا تو انھوں نے حضرت سلمانؓ سے اس کا تذکرہ کیا۔ حضرت سلمانؓ نے فرمایا پانچ نمازوں کی پابندی کرو کیونکہ جب تک آدمی قتل کر دینے والے گناہ یعنی کبیرہ گناہ نہیں کرتا اس وقت تک یہ نمازیں تمام گناہوں کے لیے کفارہ ہوتی ہیں۔ جب رات ہوتی ہے تو لوگ تین جماعتوں میں تقسیم ہو جاتے ہیں۔ ایک جماعت تو وہ ہے جس کے لیے یہ رات رحمت ہے وبال نہیں ہے، دوسری جماعت وہ ہے جس کے لیے یہ رات وبال ہے رحمت نہیں ہے، تیسری جماعت وہ ہے جس کے لیے یہ رات نہ رحمت ہے اور نہ وبال۔ جس آدمی نے رات کے اندھیرے اور لوگوں کی غفلت کو غنیمت سمجھا اور کھڑے ہو کر ساری رات نماز پڑھتا رہا اس کے لیے تو یہ رات رحمت ہے وبال نہیں ہے اور جس آدمی نے لوگوں کی غفلت اور رات کے اندھیرے کو غنیمت سمجھا اور بے سوچے سمجھے گناہوں میں مشغول رہا اس کے لیے یہ رات وبال ہے رحمت نہیں ہے اور جو آدمی عشاء پڑھ کر سو گیا اس کے لیے یہ رات نہ رحمت ہے اور نہ وبال۔ عبادت میں ایسی رفتار سے بچو جو تمہیں تھکا دے اور پھر تم اسے نباہ نہ سکو۔ اعتدال اور میانہ روی اختیار کرو اور نیک عمل پابندی سے کرو۔",""],[" (13)","s"]]]],"f":[["(13)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.181). Tabraani has reported a similar narration in his Kabeer from reliable sources, as confirmed by Haythami (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابوموسیٰ اشعریؓ","b"],[" فرماتے ہیں کہ ہم (گناہوں کی بدولت) اپنی جانوں پر آگ جلا لیتے ہیں پھر جب ہم فرض نماز پڑھ لیتے ہیں تو وہ نماز پہلے کے تمام گناہوں کے لیے کفارہ بن جاتی ہے پھر ہم اپنی جانوں پر آگ جلا لیتے ہیں پھر جب ہم نماز پڑھ لیتے ہیں تو وہ نماز پہلے کے تمام گناہوں کے لیے کفارہ بن جاتی ہے۔",""],[" (14)","s"]]]],"f":[["(14)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.182)."]]}]},"21":{"lead":[],"stories":[{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا خوشبو اور عورتیں میرے لیے محبوب بنا دی گئی ہیں اور میری آنکھوں کی ٹھنڈک نماز میں رکھی گئی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Nasa'ee."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضرت جبرائیل علیہ السلام نے حضورؐ کی خدمت میں عرض کیا نماز آپؐ کے لیے محبوب بنا دی گئی ہے۔ لہٰذا آپؐ اس میں جتنا چاہیں اپنا حصہ لے لیں۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.58). Tabraani has reported a similar narration in his Kabeer but Haythami (Vol.2 Pg.270) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ ایک دن تشریف فرما تھے اور لوگ بھی آپؐ کے اردگرد بیٹھے ہوئے تھے۔ آپؐ نے فرمایا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہر نبی کو کسی نہ کسی عمل کا زیادہ شوق عطا فرمایا تھا، مجھے رات کو نماز پڑھنے کا بہت زیادہ شوق ہے۔ اس لیے میں جب نماز میں کھڑا ہو جاؤں تو کوئی بھی میرے پیچھے ہرگز نماز نہ پڑھے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہر نبی کے لیے آمدنی کا کوئی نہ کوئی ذریعہ بنایا تھا اور میری آمدنی کا ذریعہ مال غنیمت کا پانچواں حصہ ہے۔ جب میرا انتقال ہو جائے تو پھر یہ پانچواں حصہ میرے بعد کے خلفاء کے لیے ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.2 Pg.271) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے کھڑے ہو کر ",""],["ٱللَّٰه","a"],[" کی اتنی عبادت کی کہ آپؐ کے دونوں قدم سوج گئے۔ اس پر آپؐ کی خدمت میں عرض کیا گیا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپؐ کے اگلے پچھلے گناہ معاف نہیں کر دیے؟ آپؐ نے فرمایا تو کیا میں شکر گزار بندہ نہ بنوں؟",""],[" (4)","s"]]]],"f":[["(4)","Abu Dawood, as quoted in Kanzul Ummaal (Vol.4 Pg.36). Abu Ya'la, Bazzaar and Tabraani have all reported a similar narration from reliable sources as confirmed by Haythami (Vol.2 Pg.271)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" سے روایت ہے کہ حضورؐ نماز پڑھا کرتے یہاں تک کہ آپؐ کے دونوں قدم سوج جاتے۔",""],[" (5)","s"]]]],"f":[["(5)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.271). Tabraani has reported a similar narration from Hadhrat Abu Juhayfah."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ حضورؐ رات کو اتنی نماز پڑھا کرتے کہ آپؐ کے دونوں قدم سوج جاتے پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Sagheer and Awsat."]]},{"b":[["n",[["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں کہ حضورؐ رات کو عبادت میں اتنا زیادہ کھڑے رہتے کہ آپؐ کے دونوں قدم پھٹ جاتے پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Awsat, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.271)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضورؐ رات کو عبادت میں اتنا زیادہ کھڑے رہتے کہ آپؐ کے قدم ورم کی وجہ سے پھٹ جاتے۔ میں نے حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب آپؐ کی مغفرت ہو چکی ہے تو پھر آپؐ یہ کیوں کرتے ہیں؟ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (8)","s"]]]],"f":[["(8)","Bukhaari and Muslim. The same has been reported from Hadhrat Mughiera, as quoted in Riyaadhus Saaliheen (Pg.429)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ حضورؐ عبادت میں اتنا زیادہ کھڑے رہا کرتے کہ آپؐ کے دونوں قدم پھٹ جاتے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Najjaar."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے ",""],["ٱللَّٰه","a"],[" کی اتنی زیادہ عبادت کی کہ آپؐ پرانی مشک کی طرح ہو گئے۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ ایسا کیوں کرتے ہیں؟ کیا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپؐ کے اگلے پچھلے تمام گناہ معاف نہیں کر دیے؟ حضورؐ نے فرمایا ہاں کر دیے ہیں لیکن کیا میں شکر گزار بندہ نہ بنوں؟",""],[" (10)","s"]]]],"f":[["(10)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.4 Pg.36)."]]},{"b":[["n",[["حضرت حمیدؒ","b"],[" کہتے ہیں کہ حضرت انس بن مالکؓ سے حضورؐ کی رات کی نماز کے بارے میں پوچھا گیا تو انھوں نے فرمایا کہ ہم حضورؐ کو رات کے جس حصہ میں بھی نماز پڑھتا ہوا دیکھنا چاہتے دیکھ لیتے تھے اور رات کے جس حصہ میں بھی سوتا ہوا دیکھنا چاہتے تھے دیکھ لیتے تھے یعنی کبھی آپؐ رات کے شروع میں نماز پڑھتے کبھی درمیان میں اور کبھی آخری حصے میں اور آپؐ کسی مہینہ میں اتنے زیادہ روزے رکھا کرتے کہ ہم کہتے کہ اس مہینہ میں آپؐ ایک دن بھی روزہ نہیں چھوڑیں گے اور کسی مہینہ میں آپؐ بالکل نہ رکھتے یہاں تک کہ ہم کہتے کہ آپؐ ایک دن بھی روزہ نہ رکھیں گے۔",""],[" (11)","s"]]]],"f":[["(11)","Bukhaari and Muslim."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ ایک رات میں نے حضورؐ کے ساتھ نماز پڑھنی شروع کی لیکن آپؐ نے اتنا لمبا قیام فرمایا کہ میں نے برے کام کا ارادہ کر لیا۔ ہم نے پوچھا آپ نے کس کام کا ارادہ کر لیا تھا؟ انھوں نے فرمایا میں نے حضورؐ کو چھوڑ کر بیٹھنے کا ارادہ کر لیا تھا۔",""],[" (12)","s"]]]],"f":[["(12)","Bukhaari and Muslim, as quoted in Safwatus Safwah (Vol.6 Pg.58)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں کہ ایک دفعہ حضورؐ ساری رات نماز میں کھڑے رہے اور فجر تک یہی آیت پڑھتے رہے:",""]]],["q",[["إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ  (سورۃ مائدہ: ۱۱۸)","a"]]],["p",[["ترجمہ: \"اگر آپ ان کو سزا دیں تو وہ آپ کے بندے ہیں اور اگر آپ ان کو معاف فرما دیں تو آپ زبردست ہیں، حکمت والے ہیں۔\"",""],[" (13)","s"]]]],"f":[["(13)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.58)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ کو کچھ تکلیف ہو گئی۔ جب صبح ہوئی تو کسی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! تکلیف کا اثر آپؐ پر بالکل واضح ہے۔ حضورؐ نے فرمایا تم جو مجھ پر تکلیف کا اثر دیکھ رہے ہو میں نے اس کے باوجود آج رات سات لمبی سورتیں پڑھی ہیں۔",""],[" (14)","s"]]]],"f":[["(14)","Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.274)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں کہ میں نے ایک رات نبی کریمؐ کے ساتھ نماز پڑھنی شروع کی۔ حضورؐ نے سورت بقرہ شروع فرمائی میں نے کہا سو آیتوں پر رکوع کر دیں گے لیکن آپؐ پڑھتے رہے پھر میں نے کہا آپؐ اس سورت کو دو رکعتوں میں پڑھیں گے لیکن آپؐ پڑھتے رہے پھر میں نے کہا آپؐ اسے ختم کر کے رکوع کر دیں گے لیکن آپؐ نے سورت نساء شروع کر دی اسے ختم کر کے سورت آل عمران شروع کر دی اور اسے بھی پورا پڑھ لیا۔ آپؐ ٹھہر ٹھہر کر پڑھا کرتے تھے۔ آپؐ جب کسی ایسی آیت کے پاس سے گزرتے جس میں تسبیح کا ذکر ہوتا تو آپؐ سبحان ",""],["ٱللَّٰه","a"],[" کہنے لگتے اور جب ایسی آیت کے پاس سے گزرتے جس میں (",""],["ٱللَّٰه","a"],[" سے) مانگنے کا ذکر ہوتا تو آپؐ ",""],["ٱللَّٰه","a"],[" سے مانگتے اور جب ایسی آیت کے پاس سے گزرتے جس میں پناہ مانگنے کا ذکر ہوتا تو آپؐ پناہ مانگتے۔ پھر آپؐ نے رکوع کیا اور سبحان ربی العظیم کہنے لگے اور آپؐ کا رکوع قیام جیسا لمبا تھا پھر سمع ",""],["ٱللَّٰه","a"],[" لمن حمدہ فرما کر کھڑے ہو گئے اور تقریباً رکوع جتنی دیر کھڑے رہے پھر سجدہ کیا اور سبحان ربی الاعلیٰ کہنے لگے اور آپؐ کا سجدہ بھی قیام جیسا لمبا تھا۔",""],[" (15)","s"]]]],"f":[["(15)","Muslim, as quoted in Safwatus Safwah (Vol.1 Pg.75)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں کہ میں ایک مرتبہ حضورؐ کی خدمت میں حاضر ہوا۔ آپؐ نماز پڑھ رہے تھے۔ میں نے بھی پیچھے کھڑے ہو کر نماز شروع کر دی۔ آپؐ کو معلوم نہیں تھا (کہ میں بھی آپؐ کی نماز میں شامل ہو گیا ہوں) آپؐ نے سورت بقرہ شروع فرما رکھی تھی میرا خیال تھا کہ یہ سورت ختم کر کے آپؐ رکوع کر لیں گے لیکن آپؐ پڑھتے ہی رہے۔ حضرت سنانؒ راوی کہتے ہیں کہ میرے علم کے مطابق حضرت حذیفہؓ نے یہی فرمایا کہ حضورؐ نے چار رکعت نماز پڑھی۔ حضورؐ کا رکوع قیام کی طرح لمبا ہوتا تھا۔ حضرت حذیفہؓ فرماتے ہیں کہ میں نے (نماز کے بعد) حضورؐ کو بتایا کہ میں بھی آپؐ کے پیچھے نماز پڑھ رہا تھا۔ حضورؐ نے فرمایا تم نے مجھے کیوں نہیں بتایا؟ میں نے عرض کیا اس ذات کی قسم جس نے آپؐ کو حق دے کر بھیجا ہے اب تک میری کمر میں درد ہو رہا ہے۔ حضورؐ نے فرمایا اگر مجھے پتہ چل جاتا کہ تم میرے پیچھے ہو تو میں نماز مختصر کر دیتا۔",""],[" (16)","s"]]]],"f":[["(16)","Tabraani. Haythami (Vol.2 Pg.275) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" کو بتایا گیا کہ کچھ لوگ ایک رات میں سارا قرآن ایک مرتبہ یا دو مرتبہ پڑھ لیتے ہیں۔ انھوں نے فرمایا ان لوگوں کا پڑھنا نہ پڑھنا برابر ہے۔ میں حضورؐ کے ساتھ ساری رات کھڑی رہتی تھی۔ آپؐ سورت بقرہ، سورت آل عمران اور سورت نساء پڑھا کرتے تھے۔ خوف والی آیت پر گزرتے تو دعا مانگتے اور ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتے اور بشارت والی آیت پر گزرتے تو دعا مانگتے اور اس کا شوق ظاہر کرتے۔",""],[" (17)","s"]]]],"f":[["(17)","Ahmad. Haythami (Vol.2 Pg.272) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت اسودؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت عائشہؓ کے پاس تھے۔ ہم نے نماز کی اہمیت، عظمت اور پابندی کا تذکرہ کیا تو حضرت عائشہؓ نے فرمایا حضورؐ کا مرض الوفات شروع ہوا، نماز کا وقت آیا۔ حضرت بلالؓ نے اذان دی تو حضورؐ نے فرمایا ابوبکرؓ سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔ حضورؐ کی ایک بیوی نے عرض کیا حضرت ابوبکرؓ تو بہت رقیق القلب آدمی ہیں، جلدی رو پڑتے ہیں۔ جب آپؐ کی جگہ کھڑے ہوں گے تو لوگوں کو نماز نہیں پڑھا سکیں گے۔ حضورؐ نے وہی بات دوبارہ فرمائی۔ اس نے اپنی بات دوبارہ عرض کی۔ حضورؐ نے تیسری مرتبہ فرمایا تم حضرت یوسفؑ کی ساتھن (زلیخا) کی طرح ہو (اوپر سے کچھ اور اندر سے کچھ۔ اوپر سے کہہ رہی ہو کہ ابوبکرؓ بہت روتے ہیں اور اندر دل میں یہ ہے کہ حضورؐ کی جگہ کھڑے ہونے سے لوگ بدفالی لیں گے جیسے کہ زلیخا نے اوپر سے تو عورتوں کا اکرام کیا اور اندر سے مقصود انہیں حضرت یوسفؑ کو دکھانا تھا)۔ ابوبکرؓ سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔ چنانچہ حضرت ابوبکرؓ نماز پڑھانے چلے گئے۔ پھر حضورؐ نے اپنی بیماری میں کچھ کمی محسوس کی تو کمزوری کی وجہ سے آپؐ دو آدمیوں کے سہارے مسجد گئے۔ گویا کہ میں اب بھی دیکھ رہی ہوں کہ آپؐ کے دونوں قدم زمین پر گھسٹتے ہوئے جا رہے ہیں۔ (حضورؐ کو تشریف لاتے ہوئے دیکھ کر) حضرت ابوبکرؓ نے پیچھے ہٹنے کا ارادہ کیا۔ حضورؐ نے انہیں اشارہ سے فرمایا، وہیں اپنی جگہ رہو۔ پھر حضورؐ جا کر ان کے پہلو میں بیٹھ گئے۔",""],["(18)","s"],[" حضرت عائشہؓ فرماتی ہیں میں نے حضورؐ سے بار بار کہا (کہ ابوبکرؓ نماز نہیں پڑھا سکتے) اور میں نے بار بار اس وجہ سے کہا کہ مجھے ڈر تھا کہ حضورؐ کی جگہ کھڑے ہونے سے لوگ ابوبکرؓ سے بدفالی لیں گے کیونکہ مجھے یقین تھا کہ جو بھی حضورؐ کی جگہ کھڑا ہو گا لوگ اس سے ضرور بدفالی لیں گے، اس لیے میں نے چاہا کہ حضورؐ حضرت ابوبکرؓ کے علاوہ کسی اور کو کھڑا کر دیں۔",""],["(19)","s"],[" مسلم کی روایت میں یہ ہے کہ حضرت عائشہؓ فرماتی ہیں کہ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! حضرت ابوبکرؓ بہت رقیق القلب آدمی ہیں، جب قرآن پڑھیں گے تو آنسو نہیں روک سکیں گے، اس لیے اگر آپؐ ان کے بجائے کسی اور کو فرما دیں تو اچھا ہے۔ حضرت عائشہؓ فرماتی ہیں کہ ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے یہ بات صرف اس وجہ سے کہی تھی کہ میں اسے اچھا نہیں سمجھتی تھی کہ حضورؐ کی جگہ سب سے پہلے کھڑے ہونے کی وجہ سے حضرت ابوبکرؓ سے لوگ بدفالی لیں، اس لیے میں نے یہ بات دو یا تین مرتبہ حضورؐ کی خدمت میں عرض کی لیکن حضورؐ نے آخر میں یہی فرمایا کہ ابوبکرؓ لوگوں کو نماز پڑھائیں، تم تو حضرت یوسفؑ کی ساتھن (زلیخا) کی طرح ہو۔",""],[" (20)","s"]]]],"f":[["(18)","Bukhaari."],["(19)","Bukhaari."],["(20)","Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.232)."]]},{"b":[["n",[["حضرت عبید","b"],["ٱللَّٰه","a"],[" بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں کہ میں نے حضرت عائشہؓ کی خدمت میں حاضر ہو کر عرض کیا کہ آپ ہمیں حضورؐ کی بیماری کے بارے میں کچھ نہیں بتاتیں؟ انھوں نے فرمایا کیوں نہیں، ضرور۔ جب حضورؐ کی بیماری بڑھ گئی تو آپؐ نے پوچھا کہ کیا لوگوں نے نماز پڑھ لی ہے؟ ہم نے کہا نہیں، یا رسول ",""],["ٱللَّٰه","a"],["! وہ آپؐ کا انتظار کر رہے ہیں۔ حضورؐ نے فرمایا میرے لیے لگن میں پانی ڈالو۔ ہم نے پانی ڈالا، حضورؐ نے غسل کیا پھر آپؐ کھڑے ہونے لگے تو بیہوش ہو گئے۔ پھر جب افاقہ ہوا تو آپؐ نے پوچھا کیا لوگوں نے نماز پڑھ لی ہے؟ ہم نے کہا نہیں، یا رسول ",""],["ٱللَّٰه","a"],["! وہ آپؐ کا انتظار کر رہے ہیں۔ آپؐ نے فرمایا میرے لیے لگن میں پانی رکھو۔ ہم نے پانی رکھا، حضورؐ نے غسل کیا پھر آپؐ کھڑے ہونے لگے تو بیہوش ہو گئے۔ پھر جب افاقہ ہوا تو آپؐ نے پوچھا کیا لوگوں نے نماز پڑھ لی ہے؟ ہم نے کہا نہیں، یا رسول ",""],["ٱللَّٰه","a"],["! وہ آپؐ کا انتظار کر رہے ہیں۔ آپؐ نے فرمایا میرے لیے لگن میں پانی رکھو۔ ہم نے پانی رکھا، حضورؐ نے غسل کیا پھر آپؐ کھڑے ہونے لگے تو بیہوش ہو گئے۔ پھر جب افاقہ ہوا تو آپؐ نے پوچھا کیا لوگوں نے نماز پڑھ لی ہے؟ ہم نے کہا نہیں، یا رسول ",""],["ٱللَّٰه","a"],["! وہ آپؐ کا انتظار کر رہے ہیں۔ اور واقعی لوگ مسجد میں بیٹھے ہوئے عشاء کی نماز کے لیے حضورؐ کا انتظار کر رہے تھے۔ اس کے بعد حضورؐ نے حضرت ابوبکرؓ کے پاس یہ پیغام بھیجا کہ وہ لوگوں کو نماز پڑھائیں۔ حضرت ابوبکرؓ بہت نرم دل آدمی تھے، اس لیے انھوں نے کہا اے عمرؓ! آپ لوگوں کو نماز پڑھائیں۔ حضرت عمرؓ نے کہا نہیں، اس کے آپ زیادہ حقدار ہیں۔ چنانچہ ان دنوں حضرت ابوبکرؓ نے نماز پڑھائی۔ اس کے بعد حضورؐ کے باہر آنے کا ذکر کیا جیسے پہلے گزر چکا ہے۔",""],[" (21)","s"]]]],"f":[["(21)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.233). Bayhaqi (Vol.8 Pg.151) and Ibn Abi Shaybah have reported a similar narration, as quoted in Kanzul Ummaal (Vol.4 Pg.59), as has Ibn Sa'd (Vol.2 Pg.218)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" سے بخاری میں منقول ہے کہ نبی کریمؐ کے مرض الوفات کے زمانے میں حضرت ابوبکرؓ لوگوں کو نماز پڑھا رہے تھے۔ جب پیر کا دن ہوا اور صحابہؓ صفیں بنا کر نماز میں کھڑے تھے، حضورؐ حجرہ کا پردہ ہٹا کر ہمیں دیکھنے لگے۔ آپؐ کھڑے ہوئے تھے اور آپؐ کا چہرہ قرآن کے صفحے کی طرح چمک رہا تھا اور آپؐ مسکرا رہے تھے (کہ امت اس اجتماعی کام میں مشغول ہے جس میں انھوں نے لگایا تھا)۔ حضورؐ کو دیکھ کر ہمیں اتنی زیادہ خوشی ہوئی کہ بس ہم لوگ نماز توڑنے ہی لگے تھے۔ حضرت ابوبکرؓ صف میں کھڑے ہونے کے لیے ایڑیوں کے بل پیچھے ہٹنے لگے۔ پھر حضورؐ نے ہمیں اشارہ سے فرمایا کہ اپنی نماز پوری کرو اور پردہ ڈال کر واپس اندر تشریف لے گئے اور اسی دن حضورؐ کا وصال ہو گیا۔",""],["(22)","s"],[" دوسری سند سے بخاری میں حضرت انسؓ سے منقول ہے کہ حضورؐ تین دن باہر تشریف نہیں لائے (پیر کا دن) نماز کی اقامت ہو رہی تھی، حضرت ابوبکرؓ آگے بڑھنے لگے کہ اتنے میں حضورؐ نے فرمایا پردہ اٹھاؤ۔ ساتھ والوں نے پردہ اٹھایا۔ جب حضورؐ کا چہرہ انور نظر آیا تو ایسا عجیب منظر ہم نے کبھی نہیں دیکھا تھا۔ حضرت ابوبکرؓ کو اشارہ سے آگے بڑھنے کو فرمایا اور پردہ ڈال دیا۔ پھر اس کے بعد حضورؐ کی (عام) زیارت نہ ہو سکی اور آپؐ کا انتقال ہو گیا۔",""],[" (23)","s"]]]],"f":[["(22)","Bukhaari."],["(23)","Bukhaari and Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.235). Abu Ya'la, Ibn Asaakir, Ibn Khuzaymah and Ahmad have reported similar narrations, as quoted in Kanzul Ummaal (Vol.4 Pg.57) and Majma'uz Zawaa'id (Vol.5 Pg.181). Bayhaqi (Vol.8 Pg.152) and Ibn Sa'd (Vol.2 Pg.216) have also reported similar narrations."]]}]},"22":{"lead":[],"stories":[{"b":[["n",[["حضرت مسور بن مخرمہؓ","b"],[" فرماتے ہیں کہ میں حضرت عمر بن خطابؓ کے پاس گیا (وہ بیہوش تھے اور) ان کے اوپر کپڑا ڈالا ہوا تھا۔ میں نے پوچھا آپ لوگوں کی ان کے بارے میں کیا رائے ہے؟ ان لوگوں نے کہا جیسے آپ مناسب سمجھیں۔ میں نے کہا آپ لوگ انہیں نماز کا نام لے کر پکاریں (نماز کا سنتے ہی ہوش میں آ جائیں گے) کیونکہ نماز ایک ایسی چیز ہے جس کی وجہ سے یہ سب سے زیادہ گھبرائیں گے۔ چنانچہ لوگوں نے کہا امیر المومنین! نماز (کا وقت ہو گیا ہے)۔ اس پر حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! جو آدمی نماز چھوڑ دے اس کا اسلام میں کوئی حصہ نہیں۔ پھر حضرت عمرؓ نے نماز پڑھی اور ان کے زخم میں سے خون بہہ رہا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.295)."]]},{"b":[["n",[["حضرت مسورؓ","b"],[" فرماتے ہیں کہ جب حضرت عمرؓ کو نیزہ مارا گیا تو ان پر غشی طاری ہو گئی۔ کسی نے کہا اگر یہ زندہ ہیں تو پھر یہ نماز کے نام سے جتنی جلدی گھبرا کر اٹھیں گے اتنی جلدی اور کسی چیز کے نام سے نہیں اٹھیں گے۔ کسی نے کہا امیر المومنین! نماز (کا وقت ہو گیا) ہے۔ اس پر حضرت عمرؓ فوراً ہوش میں آ گئے اور فرمایا نماز! ",""],["ٱللَّٰه","a"],[" کی قسم! جس نے نماز چھوڑ دی اس کا اسلام میں کوئی حصہ نہیں۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.350)."]]},{"b":[["n",[["حضرت محمد بن مسکینؒ","b"],[" کہتے ہیں کہ جب باغیوں نے حضرت عثمانؓ کو گھیر لیا تو ان کی بیوی نے ان (باغیوں) سے کہا اگر تم انہیں قتل کرنا چاہتے ہو تو انہیں قتل کر دو یا چھوڑ دو، یہ ساری رات نماز پڑھا کرتے تھے اور ایک رکعت میں سارا قرآن پڑھ لیا کرتے تھے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.94). Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.57)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ جب باغیوں نے حضرت عثمان بن عفانؓ کو شہید کر دیا تو ان کی بیوی نے کہا تم لوگوں نے ان کو قتل کر دیا ہے، حالانکہ یہ ساری رات عبادت کیا کرتے تھے اور ایک رکعت میں سارا قرآن پڑھ لیتے تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.57)."]]},{"b":[["n",[["حضرت عثمان بن عبدالرحمن تیمیؒ","b"],[" کہتے ہیں کہ میرے والد نے کہا میں نے (اپنے دل میں) کہا میں زور لگا کر مقام ابراہیم پر ہی آج رات عبادت کروں گا۔ وہ کہتے ہیں جب میں عشاء کی نماز پڑھ چکا تو مقام ابراہیم پر آ کر اکیلا کھڑا ہو گیا۔ میں کھڑا ہوا تھا کہ اتنے میں ایک آدمی آیا اور اس نے اپنا ہاتھ میرے دونوں کندھوں کے درمیان رکھ دیا۔ میں نے دیکھا تو حضرت عثمان بن عفانؓ تھے۔ پھر انھوں نے ام القرآن یعنی سورت فاتحہ سے پڑھنا شروع کیا اور قرآن ختم کیا اور پھر رکوع اور سجدہ کیا پھر (نماز پوری کر کے) اپنے جوتے اٹھائے (اور چلے گئے)۔ اب مجھے معلوم نہیں کہ انھوں نے اس سے پہلے کوئی نماز پڑھی تھی یا نہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.56)."]]},{"b":[["n",[["حضرت عثمان بن عبدالرحمن تیمیؒ","b"],[" کہتے ہیں کہ ایک رات میں نے مقام ابراہیم کے پاس حضرت عثمانؓ کو دیکھا کہ وہ آگے بڑھے اور ایک رکعت میں سارا قرآن ختم کر کے اپنی نماز پوری کی۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Mubaarak in his Zuhd, Ibn Sa'd, Ibn Abi Shaybah, Ibn Munee, Tahaawi, Daar Qutni and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.9)."]]},{"b":[["n",[["حضرت عطاء بن ابی رباحؒ","b"],[" کہتے ہیں کہ حضرت عثمانؓ نے ایک مرتبہ لوگوں کو نماز پڑھائی پھر وہ مقام ابراہیم کے پیچھے کھڑے ہوئے اور وتر کی ایک رکعت میں سارا قرآن پڑھ دیا۔ ",""],["حضرت محمد بن سیرینؒ","b"],[" کہتے ہیں کہ حضرت عثمانؓ ساری رات ",""],["ٱللَّٰه","a"],[" کی عبادت کرتے تھے اور ایک رکعت میں سارا قرآن ختم کر لیا کرتے تھے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.3 Pg.75), as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.9)."]]},{"b":[["n",[["حضرت مسیب بن رافعؒ","b"],[" کہتے ہیں کہ جب حضرت ابن عباسؓ کی نگاہ جاتی رہی تو ایک آدمی نے حاضر خدمت ہو کر عرض کیا کہ اگر آپ میرے کہنے پر سات دن اس طرح صبر سے گزاریں کہ ان میں آپ چت لیٹ کر اشارے سے نماز پڑھیں تو میں آپ کا علاج کروں گا، ان شاء ",""],["ٱللَّٰه","a"],[" آپ ٹھیک ہو جائیں گے۔ اس پر حضرت ابن عباسؓ نے حضرت عائشہؓ، حضرت ابوہریرہؓ اور دوسرے بہت سے صحابہ کرامؓ کے پاس آدمی بھیج کر اس بارے میں پوچھا۔ ہر ایک نے یہی جواب دیا کہ اگر آپ کا ان سات دنوں میں انتقال ہو گیا تو پھر آپ نماز کا کیا کریں گے؟ اس پر انہوں نے اپنی آنکھوں کو ایسے ہی رہنے دیا اور ان کا علاج نہ کروایا۔",""],[" (8)","s"]]]],"f":[["(8)","Haakim (Vol.3 Pg.546)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ جب میری بینائی چلی گئی تو کسی نے مجھ سے کہا ہم آپ (کی آنکھ) کا علاج کر دیتے ہیں لیکن آپ چند دن نماز پڑھنا چھوڑ دیں۔ میں نے کہا نہیں، کیونکہ حضورؐ نے ارشاد فرمایا ہے کہ جو آدمی نماز چھوڑے گا وہ ",""],["ٱللَّٰه","a"],[" تعالیٰ سے اس حال میں ملے گا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے ناراض ہوں گے۔",""],[" (9)","s"]]]],"f":[["(9)","Bazzaar and Tabraani. Haythami (Vol.1 Pg.295) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علی بن ابی حملہؒ","b"],[" اور ",""],["اوزاعیؒ","b"],[" کہتے ہیں کہ حضرت علی بن عبد",""],["ٱللَّٰه","a"],[" بن عباسؓ روزانہ ہزار رکعت پڑھا کرتے تھے۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani. Haythami (Vol.2 Pg.258) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" (نفلی) روزے نہیں رکھا کرتے تھے اور فرماتے تھے جب میں روزہ رکھتا ہوں تو کمزوری ہو جاتی ہے اور اس کی وجہ سے نماز میں کمی آ جاتی ہے اور مجھے روزے سے زیادہ نماز سے محبت ہے، وہ اگر روزہ رکھتے تو مہینے میں صرف تین دن رکھا کرتے تھے۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.257)."]]},{"b":[["n",[["حضرت عبدالرحمن بن یزیدؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ بہت کم (نفلی) روزے رکھتے تھے۔ اس بارے میں کسی نے ان سے وجہ دریافت کی تو انھوں نے جواب میں وہی بات کہی جو پچھلی حدیث میں گزر چکی ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت عبدالرحمن بن یزیدؒ","b"],[" کہتے ہیں کہ میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ سے کم روزہ رکھنے والا کوئی فقیہ",""],["(13)","s"],[" نہیں دیکھا تو کسی نے ان سے پوچھا کہ آپ روزے کیوں نہیں رکھتے؟ انھوں نے فرمایا مجھے نماز روزے سے زیادہ پسند ہے۔ روزے رکھتا ہوں تو کمزور ہو جاتا ہوں اور پھر نماز کی ہمت نہیں رہتی۔",""],[" (14)","s"]]]],"f":[["(13)","A jurist with a very deep and fully-fledged understanding of the injunctions of the Shari'ah."],["(14)","Ibn Sa'd (Vol.3 Pg.155)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ ایک رات عشاء کے بعد حضورؐ کے پاس آنے میں مجھے دیر ہو گئی۔ جب میں آپؐ کے پاس گئی تو آپؐ نے مجھ سے فرمایا تم کہاں تھیں؟ میں نے کہا آپؐ کے ایک صحابی مسجد میں قرآن پڑھ رہے تھے، میں اسے سن رہی تھی۔ میں نے اس جیسی آواز اور اس جیسی قراءت آپؐ کے کسی صحابی کی نہیں سنی۔ آپؐ اپنی جگہ سے اٹھے، آپؐ کے ساتھ میں بھی اٹھی اور جا کر آپؐ نے کچھ دیر وہ قراءت سنی۔ پھر میری طرف متوجہ ہو کر فرمایا یہ حضرت ابوحذیفہؓ کے غلام سالم ہیں۔ تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میری امت میں اس جیسے آدمی بنائے۔",""],[" (15)","s"]]]],"f":[["(15)","Haakim (Vol.3 Pg.225), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں کہ ہم لوگ ایک سفر میں حضرت ابوموسیٰ اشعریؓ کے ساتھ تھے، ہمیں ایک کھیتی والے باغ میں رات آ گئی۔ چنانچہ ہم نے اس باغ میں قیام کیا۔ حضرت ابوموسیٰؓ رات کو کھڑے ہو کر نماز پڑھنے لگے۔ حضرت مسروقؒ کہتے ہیں کہ ان کی آواز بہت دلکش اور قراءت بہت عمدہ تھی اور جیسی آیت پر گزرتے اسی طرح کی دعا وغیرہ کرتے۔ پھر یہ دعا پڑھی: اے ",""],["ٱللَّٰه","a"],["! تو تمام عیوب سے پاک ہے اور تیری طرف سے ہی سلامتی ملتی ہے اور تو ہی امن دینے والا ہے اور ایمان داروں کو تو پسند کرتا ہے اور تو ہی نگہبانی کرنے والا ہے اور تو نگہبانی کرنے والوں کو پسند کرتا ہے اور تو ہی سچا ہے اور تو سچوں کو پسند کرتا ہے۔",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Hilya (Vol.1 Pg.259)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں کہ میں حضرت ابوہریرہؓ کا سات رات مہمان بنا تو وہ اور ان کا خادم اور ان کی بیوی تینوں باری باری رات کو عبادت کرتے تھے اور اس کے لیے انھوں نے رات کے تین حصے کر رکھے تھے۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Nu'aym in his Hilya (Vol.1 Pg.383)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی بکرؒ","b"],[" فرماتے ہیں کہ حضرت ابوطلحہؓ اپنے ایک باغ میں (نفل) نماز پڑھ رہے تھے کہ اتنے میں ایک چڑیا اڑی اور وہ راستہ کی تلاش میں ادھر ادھر چکر لگانے لگی لیکن اسے راستہ نہیں مل رہا تھا (کیونکہ باغ بہت گھنا تھا)۔ یہ منظر انہیں پسند آیا اور وہ اسے کچھ دیر دیکھتے رہے۔ پھر انہیں اپنی نماز کا خیال آیا تو اب انہیں یہ یاد نہ رہا کہ وہ کتنی رکعت نماز پڑھ چکے ہیں تو کہنے لگے کہ اس باغ کی وجہ سے یہ مصیبت پیش آئی ہے اور وہ فوراً حضورؐ کی خدمت میں حاضر ہوئے اور اپنی نماز کا سارا قصہ سنا کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! (اس باغ کی وجہ سے یہ مصیبت پیش آئی اس لیے) یہ باغ ",""],["ٱللَّٰه","a"],[" کے نام پر صدقہ ہے، آپؐ اسے جہاں چاہیں خرچ فرما دیں۔",""],[" (18)","s"]]]],"f":[["(18)","Maalik, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.316)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی بکرؒ","b"],[" فرماتے ہیں کہ ایک انصاری مدینہ کی وادی قف میں اپنے ایک باغ میں نماز پڑھ رہے تھے۔ کھجوریں پکنے کا زمانہ اپنے شباب پر تھا اور خوشے کھجوروں کے بوجھ کی وجہ سے جھکے پڑے تھے۔ ان کی نگاہ ان خوشوں پر پڑی اور کھجوروں کی کثرت کی وجہ سے وہ اچھے معلوم ہوئے۔ پھر انہیں نماز کا خیال آیا تو یہ یاد نہ رہا کہ کتنی رکعت نماز پڑھ چکے ہیں تو وہ کہنے لگے کہ اس باغ کی وجہ سے یہ مصیبت پیش آئی ہے۔ حضرت عثمان بن عفانؓ کا زمانہ خلافت تھا، ان انصاری نے حضرت عثمانؓ کی خدمت میں حاضر ہو کر سارا قصہ سنایا اور عرض کیا یہ باغ ",""],["ٱللَّٰه","a"],[" کے لیے صدقہ ہے، اسے آپ کسی خیر کے کام میں خرچ کر دیں۔ چنانچہ اسے حضرت عثمانؓ نے پچاس ہزار میں بیچا۔ اس وجہ سے اس باغ کا نام خمسین یعنی پچاس ہزار پڑ گیا۔",""],[" (19)","s"]]]],"f":[["(19)","Maalik, as quoted in Awjaz (Vol.1 Pg.315)."]]},{"b":[["n",[["حضرت اسماءؓ","b"],[" فرماتی ہیں کہ ابن زبیرؓ رات بھر ",""],["ٱللَّٰه","a"],[" کی عبادت کرتے، دن بھر روزہ رکھتے اور (چونکہ وہ مسجد میں زیادہ رہتے تھے، اس لیے) ان کا نام مسجد کا کبوتر پڑ گیا تھا۔",""],[" (20)","s"]]]],"f":[["(20)","Abu Nu'aym in his Hilya (Vol.1 Pg.335)."]]},{"b":[["n",[["حضرت عدی بن حاتمؓ","b"],[" فرماتے ہیں کہ جب بھی کسی نماز کا وقت آتا ہے تو میں اس نماز کی تیاری کر چکا ہوتا ہوں اور میرے اندر اس نماز کا شوق پورے زور پر ہوتا ہے۔",""],[" (21)","s"]]]],"f":[["(21)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.80). Ibn Mubaarak has reported a similar narration, as quoted in Isaabah (Vol.2 Pg.468)."]]}]},"23":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ صحابہ کرامؓ مسجد بنانے کے لیے کچی اینٹیں اٹھا کر لا رہے تھے اور حضورؐ بھی ان کے ساتھ تھے (یہ غزوہ خیبر کے بعد کا واقعہ ہے جبکہ مسجد نبوی کی دوسری مرتبہ تعمیر ہوئی)۔ حضورؐ اپنے پیٹ پر ایک اینٹ چوڑائی میں رکھے ہوئے لا رہے تھے۔ سامنے سے میں آیا تو میں سمجھا کہ اس اینٹ کو آپؐ کو اٹھانے میں دشواری ہو رہی ہے، اس لیے میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ اینٹ مجھے دے دیں۔ حضورؐ نے فرمایا اے ابوہریرہ! تم کوئی اور اینٹ لے لو کیونکہ اصل زندگی تو آخرت کی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.9)."]]},{"b":[["n",[["حضرت طلق بن علیؓ","b"],[" (یمامی) فرماتے ہیں کہ میں نے حضورؐ کے ساتھ مسجد بنائی۔ حضورؐ (میرے بارے میں کسی صحابی سے) فرما رہے تھے کہ اس یمامی کو گارے کی طرف بڑھاؤ کیونکہ اسے تم سب سے زیادہ اچھی طرح گارا ملانا آتا ہے اور اس کے کندھے بھی تم سب سے زیادہ مضبوط ہیں، یعنی یہ تم سب سے زیادہ طاقتور بھی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.9)."]]},{"b":[["n",[["حضرت طلق بن علیؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کی خدمت میں حاضر ہوا، اس وقت صحابہؓ مسجد بنا رہے تھے، حضورؐ کو صحابہؓ کا یہ کام کچھ پسند نہیں آ رہا تھا۔ میں پھاوڑا لے کر اس سے گارا ملانے لگ گیا۔ حضورؐ کو میرا پھاوڑا لے کر اس سے گارا ملانا پسند آیا تو فرمایا اس حنفی (قبیلہ بنو حنیفہ کے آدمی) کو گارا بنانے میں لگا رہنے دو کیونکہ یہ تم سے زیادہ اچھا گارا بنانے والا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad. Haythami (Vol.2 Pg.9) has commented on the chain of narrators."]]},{"b":[["n",[["جب ",""],["حضرت ابن ابی اوفیؓ","b"],[" کی بیوی کا انتقال ہوا تو وہ فرمانے لگے کہ اس کا جنازہ اٹھاؤ اور خوب شوق سے اٹھاؤ کیونکہ یہ اور اس کی رشتہ دار عورتیں رات کو اس مسجد کے پتھر اٹھایا کرتی تھیں جس کی بنیاد تقویٰ پر رکھی گئی ہے اور ہم (مرد) دن میں دو دو پتھر اٹھاتے تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Bazzaar. Haythami (Vol.2 Pg.10) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبادہ بن صامتؓ","b"],[" فرماتے ہیں کہ انصار نے آپس میں کہا کہ کب تک حضورؐ کھجور کی ٹہنیوں (سے بنی ہوئی مسجد) میں نماز پڑھتے رہیں گے؟ اس پر انصار نے حضورؐ کے لیے بہت سے دینار جمع کیے اور وہ لے کر حضورؐ کی خدمت میں آئے اور عرض کیا کہ ہم اس مسجد کو ٹھیک کرنا چاہتے ہیں اور اسے مزین بنانا چاہتے ہیں۔ حضورؐ نے فرمایا میں اپنے بھائی موسیٰؑ کے طرز سے ہٹنا نہیں چاہتا، میری مسجد کا چھپر ایسا ہو جیسا حضرت موسیٰؑ کا تھا۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.2 Pg.16) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبادہ بن صامتؓ","b"],[" فرماتے ہیں کہ انصار نے بہت سا مال جمع کیا اور اسے لے کر حضورؐ کی خدمت میں حاضر ہوئے اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اس مال سے مسجد بنائیں اور اسے بہت زیب و زینت والی بنائیں، ہم کب تک کھجور کی ٹہنیوں کے نیچے نماز پڑھتے رہیں گے؟ حضورؐ نے فرمایا میں اپنے بھائی موسیٰ علیہ السلام کے طرز سے نہیں ہٹ سکتا۔ ایسا چھپر ہو جیسا موسیٰؑ کا تھا۔",""],["(6)","s"],[" ",""],["حضرت حسنؒ","b"],[" کہتے ہیں کہ حضرت موسیٰ علیہ السلام کا چھپر اتنا اونچا تھا کہ جب وہ اپنا ہاتھ اٹھاتے تو چھپر کو لگ جاتا تھا۔",""],[" (7)","s"]]]],"f":[["(6)","Bayhaqi in his Dalaa'il."],["(7)","Bayhaqi."]]},{"b":[["n",[["حضرت ابن شہابؒ","b"],[" کہتے ہیں کہ حضورؐ کے زمانے میں مسجد کے ستون کھجور کے تنے تھے اور اس کی چھت کھجور کی ٹہنیوں اور پتوں کی تھی اور چھت پر کوئی خاص مٹی بھی نہیں تھی۔ جب بارش ہوا کرتی تھی تو ساری مسجد کیچڑ سے بھر جاتی تھی اور آپؐ کی مسجد بس چھپر جیسی ہی تھی۔",""],[" (8)","s"]]]],"f":[["(8)","Bayhaqi."]]},{"b":[["n",[["بخاری میں لیلۃ القدر کی حدیث میں ہے کہ ",""],["حضورؐ","b"],[" فرماتے ہیں کہ مجھے خواب میں (لیلۃ القدر) کی یہ نشانی دکھائی گئی ہے کہ میں کیچڑ میں سجدہ کر رہا ہوں، لہٰذا جس نے ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے ساتھ اعتکاف کیا تھا وہ اب پھر اعتکاف کرے۔ چنانچہ ہم نے دوبارہ اعتکاف شروع کر دیا۔ اس وقت ہمیں آسمان میں بادل کا کوئی ٹکڑا نظر نہیں آ رہا تھا لیکن تھوڑی دیر کے بعد ایک بادل آیا اور بارش ہوئی اور اتنی ہوئی کہ مسجد کی چھت خوب ٹپکی۔ مسجد کی چھت کھجور کی ٹہنیوں کی تھی اور نماز کھڑی ہو گئی تو میں نے دیکھا کہ حضورؐ کیچڑ میں سجدہ کر رہے ہیں یہاں تک کہ میں نے آپؐ کی پیشانی پر کیچڑ کا اثر دیکھا۔",""],[" (9)","s"]]]],"f":[["(9)","Wafaa'ul Wafaa (Vol.1 Pg.242)."]]},{"b":[["n",[["حضرت خالد بن معدانؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ اور حضرت ابودرداءؓ کے پاس ایک بانس تھا جس سے وہ مسجد کی پیمائش کر رہے تھے کہ اتنے میں حضورؐ ان کے پاس باہر تشریف لائے اور ان سے فرمایا تم دونوں کیا کر رہے ہو؟ ان دونوں نے عرض کیا ہم رسول ",""],["ٱللَّٰه","a"],["ؐ کی مسجد ملک شام کے طرز پر بنانا چاہتے ہیں اور اس کا جتنا خرچہ ہوگا وہ انصار پر تقسیم کر دیا جائے گا۔ حضورؐ نے فرمایا یہ بانس مجھے دو۔ آپؐ نے ان دونوں سے وہ بانس لیا پھر چل پڑے اور دروازے پر پہنچ کر آپؐ نے وہ بانس پھینک دیا اور فرمایا ہرگز نہیں (ملک شام کی طرح مسجد کی شاندار عمارت نہیں بنانی)، بس گھاس پھوس اور چھوٹی چھوٹی لکڑیاں اور حضرت موسیٰؑ جیسا سائبان ہو اور (موت کا) معاملہ اس سے بھی زیادہ قریب ہے۔ کسی نے پوچھا حضرت موسیٰؑ کا سائبان کیسا تھا؟ آپؐ نے فرمایا وہ جب کھڑے ہوتے تو ان کا سر چھت کو لگ جاتا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Zabaalah, as quoted in Wafaa'ul Wafaa (Vol.1 Pg.241)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے ستون سے لے کر مقصورہ (امام کے لیے بنائے جانے والے کمرہ) تک مسجد میں اضافہ کیا اور فرمایا اگر میں نے حضورؐ کا یہ ارشاد نہ سنا ہوتا کہ ہمیں اپنی مسجد کو بڑھانا چاہیے تو میں ہرگز نہ بڑھاتا۔",""],[" (11)","s"]]]],"f":[["(11)","Ahmad."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ نے انہیں بتایا کہ مسجد حضورؐ کے زمانے میں کچی اینٹ سے بنی ہوئی تھی۔ اس کی چھت کھجور کی ٹہنیوں کی تھی اور اس کے ستون کھجور کے تنوں کے تھے۔ حضرت ابوبکرؓ نے مسجد میں کوئی اضافہ نہ کیا، البتہ حضرت عمرؓ نے اس میں اضافہ کیا اور حضورؐ کے زمانے میں جیسی کچی اینٹ اور کھجور کی ٹہنیوں سے بنی ہوئی تھی ویسی ہی بنائی اور اس کے ستون لکڑی کے ہی بنائے۔ پھر حضرت عثمانؓ نے اسے بدل دیا اور اس میں بہت زیادہ اضافہ کیا اور اس کی دیواریں منقش پتھروں اور چونے سے بنائیں اور اس کے ستون منقش پتھروں کے اور اس کی چھت ساکھو کی لکڑی کی بنائی۔",""],[" (12)","s"]]]],"f":[["(12)","Bukhaari and Abu Dawood."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضورؐ کے زمانے میں آپؐ کی مسجد کے ستون کھجور کے تنوں کے تھے اور مسجد پر کھجور کی ٹہنیوں سے سایہ کیا ہوا تھا۔ پھر حضرت ابوبکرؓ کے زمانہ خلافت میں یہ کھجور کے تنے اور ٹہنیاں بوسیدہ ہو کر ریزہ ریزہ ہونے لگیں تو انہیں ہٹا کر حضرت ابوبکرؓ نے نئے کھجور کے تنے اور نئی ٹہنیاں لگا دیں۔ پھر یہ ستون حضرت عثمانؓ کے زمانہ خلافت میں بوسیدہ ہو گئے تو انہیں ہٹا کر حضرت عثمانؓ نے ان کی جگہ کچی اینٹیں لگا دیں جو اب تک لگی ہوئی ہیں۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Dawood."]]},{"b":[["n",[["مسلم میں یہ روایت ہے کہ ",""],["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں کہ حضرت عثمان بن عفانؓ نے مسجد بنانے کا ارادہ کیا تو لوگوں نے اسے پسند نہ کیا کیونکہ وہ چاہتے تھے کہ مسجد کو اسی حالت پر رہنے دیں۔ تو حضرت عثمانؓ نے فرمایا کہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ جو ",""],["ٱللَّٰه","a"],[" کے لیے مسجد بنائے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے اسی جیسا محل جنت میں بنائیں گے۔",""],[" (14)","s"]]]],"f":[["(14)","Muslim."]]},{"b":[["n",[["حضرت مطلب بن عبد","b"],["ٱللَّٰه","a"],[" بن حنطبؒ","b"],[" کہتے ہیں کہ جب ۲۴ھ میں حضرت عثمان بن عفانؓ خلیفہ بنے تو لوگوں نے ان سے مسجد بڑھانے کی بات کی اور یہ شکایت کی کہ جمعہ کے دن جگہ بہت تنگ ہو جاتی ہے حتیٰ کہ انہیں مسجد سے باہر میدان میں نماز پڑھنی پڑتی ہے۔ حضرت عثمانؓ نے اس بارے میں حضورؐ کے اہل الرائے صحابہؓ سے مشورہ کیا تو سب کا اس پر اتفاق ہوا کہ پرانی مسجد کو گرا کر اس میں اضافہ کر دیا جائے۔ چنانچہ حضرت عثمانؓ نے لوگوں کو ظہر کی نماز پڑھائی پھر منبر پر تشریف فرما ہو کر پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان فرمائی پھر فرمایا اے لوگو! میں نے اس بات کا ارادہ کر لیا ہے کہ میں حضورؐ کی مسجد کو گرا کر اس میں اضافہ کر دوں اور میں گواہی دیتا ہوں کہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ جو ",""],["ٱللَّٰه","a"],[" کے لیے مسجد بنائے گا ",""],["ٱللَّٰه","a"],[" اس کے لیے جنت میں محل بنائیں گے اور یہ کام مجھ سے پہلے ایک بہت بڑی شخصیت بھی کر چکی ہے۔ حضرت عمر بن خطابؓ نے مسجد کو بڑھایا بھی تھا اور اسے نئے سرے سے بنایا بھی تھا اور میں نے اس بارے میں حضورؐ کے اہل الرائے صحابہؓ سے مشورہ بھی کر چکا ہوں۔ ان سب کا اس پر اتفاق ہے کہ مسجد کو گرا کر نئے سرے سے بنایا جائے اور اس میں توسیع بھی کر دی جائے۔ تو لوگوں نے اس کی خوب تحسین کی اور ان کے لیے دعا بھی کی۔ اگلے دن صبح کو حضرت عثمانؓ نے کام کرنے والوں کو بلایا (اور انہیں کام میں لگایا) اور خود بھی اس کام میں لگے، حالانکہ حضرت عثمانؓ ہمیشہ روزہ رکھا کرتے تھے اور رات بھر نماز پڑھا کرتے تھے اور مسجد سے باہر نہیں جایا کرتے تھے۔ اور آپؓ نے حکم دیا کہ بطن نخل میں چھنا ہوا چونا تیار کیا جائے۔ حضرت عثمانؓ نے ربیع الاول ۲۹ھ میں مسجد کی تعمیر کا کام شروع کیا جو محرم ۳۰ھ میں ختم ہوا۔ یوں دس ماہ میں کام پورا ہوا۔",""],[" (15)","s"]]]],"f":[["(15)","Muslim, as quoted in Wafaa'ul Wafaa (Vol.1 Pg.355,356)."]]},{"b":[["n",[["حضرت جابر بن اسامہ جہنیؓ","b"],[" فرماتے ہیں کہ حضورؐ اپنے صحابہؓ کے ساتھ بازار میں تھے، میری آپؐ سے ملاقات ہوئی، میں نے پوچھا حضورؐ! کہاں جانے کا ارادہ فرما رہے ہیں؟ لوگوں نے بتایا کہ حضورؐ تمہاری قوم کے لیے مسجد کی جگہ کی نشاندہی کرنا چاہتے ہیں۔ چنانچہ میں جب وہاں پہنچا تو حضورؐ مسجد کی جگہ کی نشاندہی کر چکے تھے اور آپؐ نے قبلہ کی نشانی کے لیے ایک لکڑی زمین میں گاڑی ہوئی تھی۔",""],[" (16)","s"]]]],"f":[["(16)","Tabraani in his Awsat and Kabeer. Haythami (Vol.2 Pg.15) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration in his Hilya, as quoted in Kanzul Ummaal (Vol.4 Pg.262) and Baawardi as well, as quoted in Kanzul Ummaal (Vol.4 Pg.263)."]]},{"b":[["n",[["حضرت عثمان بن عطاءؒ","b"],[" کہتے ہیں کہ جب حضرت عمر بن خطابؓ نے بہت سے شہر فتح کر لیے تو ان شہروں کے گورنروں کو خط لکھے۔ چنانچہ حضرت ابوموسیٰ اشعریؓ بصرہ کے گورنر تھے، انہیں خط میں یہ لکھا کہ سارے شہر کے لیے جمعہ کی نماز کے لیے ایک جامع مسجد بنائیں اور ہر قبیلہ کے لیے الگ الگ مسجد بنائیں (ہر قبیلہ والے پانچوں نمازیں اپنی مسجد میں پڑھا کریں لیکن) جمعہ کے دن سب جامع مسجد میں آ کر جمعہ پڑھا کریں۔ حضرت سعد بن ابی وقاصؓ کوفہ کے گورنر تھے انہیں بھی حضرت عمرؓ نے یہی لکھا۔ حضرت عمرو بن عاصؓ مصر کے گورنر تھے انہیں بھی یہی لکھا اور لشکروں کے امیروں کو یہ لکھا کہ دیہات میں رہائش نہ رکھیں بلکہ شہروں میں رہیں اور ہر شہر میں ایک ہی مسجد بنائیں اور جیسے کوفہ، بصرہ اور مصر والوں نے مسجدیں بنائی ہیں اس طرح ہر قبیلے والے اپنی اپنی مسجد نہ بنائیں۔ چنانچہ لوگ حضرت عمرؓ کے اس فرمان کے پابند ہو گئے۔",""],[" (17)","s"]]]],"f":[["(17)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.259)."]]}]},"24":{"lead":[],"stories":[{"b":[["n",[["حضرت عروہ بن زبیرؒ","b"],[" حضورؐ کے ایک صحابی سے یہ نقل کرتے ہیں کہ حضورؐ ہمیں اپنے محلوں میں مسجدیں تعمیر کرنے اور انہیں اچھی طرح بنانے اور انہیں پاک رکھنے کا حکم دیتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.11)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضورؐ نے اس بات کا حکم دیا کہ محلوں میں مسجدیں بنائی جائیں اور ان کی صفائی کی جائے اور انہیں معطر کیا جائے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, Tirmidhi and Ibn Maajah, as quoted in Mishkaatul Masaabeeh (Pg.61)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک عورت مسجد میں سے کوڑا وغیرہ اٹھایا کرتی تھی، پھر اس کا انتقال ہو گیا اور اس کے دفن ہونے کی حضورؐ کو خبر نہ ہوئی (جب آپؐ کو پتہ چلا تو) آپؐ نے فرمایا جب تم میں سے کوئی مر جایا کرے تو مجھے اس کی خبر کیا کرو، اور آپؐ نے اس کی نماز جنازہ پڑھی اور فرمایا میں نے اسے جنت میں دیکھا کہ وہ مسجد میں سے کوڑا وغیرہ اٹھا رہی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.2 Pg.10) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ ہر جمعہ کے دن حضورؐ کی مسجد کو خوشبو کی دھونی دیا کرتے تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Ya'la. Haythami (Vol.2 Pg.11) has commented on the chain of narrators."]]}]},"25":{"lead":[],"stories":[{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں کہ ایک صاحب مسجد نبوی سے بہت دور رہتے تھے کہ میرے علم میں اور کوئی ان سے زیادہ دور نہیں رہتا تھا لیکن وہ ہر نماز مسجد نبوی میں پڑھتے تھے، ان کی کوئی نماز نہیں جاتی تھی۔ ان سے کسی نے کہا کیا ہی اچھا ہوتا اگر آپ کوئی گدھا خرید لیں اور اندھیرے میں اور سخت گرمی میں اس پر سوار ہو کر (مسجد نبوی کو) آیا کریں۔ انھوں نے کہا مجھے اس سے بالکل خوشی نہیں ہوگی کہ میرا گھر بالکل مسجد کے پہلو میں ہو، میں تو چاہتا ہوں کہ میرا مسجد کی طرف پیدل چل کر جانا اور اپنے گھر واپس جانا (میرے اعمال نامہ میں) لکھا جائے۔ اس پر حضورؐ نے فرمایا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہارے آنے جانے کا سارا ثواب لکھ دیا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Muslim, Daarmi, Abu Awaana, Ibn Khuzaymah and Ibn Hibbaan."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں کہ ایک انصاری کا گھر مدینہ میں (مسجد نبوی سے) سب سے زیادہ دور تھا لیکن حضورؐ کے ساتھ کی کوئی نماز ان سے فوت نہ ہوتی تھی۔ مجھے ان پر بڑا ترس آیا، اس لیے میں نے ان سے کہا اے فلاں! اگر تم گدھا خرید لو تو سخت گرمی سے بھی اور زمین کے کیڑے مکوڑوں سے بھی حفاظت ہو جائے گی۔ اس انصاری نے کہا ارے میاں! ذرا غور سے سنو! ",""],["ٱللَّٰه","a"],[" کی قسم مجھے تو یہ بھی پسند نہیں کہ میرا گھر حضرت محمدؐ کے گھر کے بالکل ساتھ ہو۔ مجھے ان کی یہ بات بڑی گراں لگی اور میں نے جا کر حضورؐ کو بتا دی۔ حضورؐ نے انہیں بلا کر پوچھا تو انہوں نے حضورؐ کے سامنے بھی وہی بات کہہ دی اور یہ بھی بتایا کہ مجھے دور سے مسجد پیدل آنے جانے میں ثواب کی امید ہے۔ حضورؐ نے ان سے فرمایا تم جس ثواب کی امید لگائے ہو وہ تمہیں ضرور ملے گا۔",""],["(2)","s"],[" حمیدی کی روایت میں یہ بھی ہے کہ حضورؐ نے یہ بھی فرمایا کہ یہ جو قدم بھی مسجد کی طرف اٹھاتے ہیں اس کے بدلے میں انہیں ایک درجہ ملتا ہے۔",""],[" (3)","s"]]]],"f":[["(2)","Tayaalisi, Ibn Maajah and Muslim."],["(3)","Humaydi and Abu Dawood, as quoted in Kanzul Ummaal (Vol.4 Pg.244)."]]},{"b":[["n",[["حضرت زید بن ثابتؓ","b"],[" فرماتے ہیں کہ میں ایک مرتبہ حضورؐ کے ساتھ پیدل چل رہا تھا۔ ہم نماز کے لیے (مسجد) جا رہے تھے۔ حضورؐ چھوٹے چھوٹے قدم رکھ رہے تھے۔ حضورؐ نے فرمایا کیا تم جانتے ہو کہ میں کیوں چھوٹے چھوٹے قدم رکھ رہا ہوں؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ زیادہ جانتے ہیں۔ آپؐ نے فرمایا آدمی جب تک نماز کی کوشش میں لگا رہتا ہے وہ نماز ہی میں شمار ہوتا ہے۔",""],["(4)","s"],[" دوسری روایت میں یہ ہے کہ حضورؐ نے فرمایا میں ایسا اس لیے کر رہا ہوں تا کہ نماز کی کوشش میں میرے قدم زیادہ ہو جائیں۔",""],[" (5)","s"]]]],"f":[["(4)","Tabraani."],["(5)","Tabraani. Haythami (Vol.2 Pg.32) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ثابتؒ","b"],[" کہتے ہیں کہ ایک مرتبہ میں انس بن مالکؓ کے ساتھ (بصرہ کے قریب) زاویہ نامی بستی میں چلا جا رہا تھا کہ اتنے میں انہوں نے اذان کی آواز سنی تو آواز سنتے ہی چھوٹے چھوٹے قدم رکھنے شروع کر دیے یہاں تک کہ میں (ان کے ساتھ) مسجد میں داخل ہو گیا۔ پھر فرمایا اے ثابت! کیا تم جانتے ہو کہ میں اس طرح کیوں چلا؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ زیادہ جانتے ہیں۔ حضرت انسؓ نے فرمایا تا کہ نماز کی تلاش میں میرے قدم زیادہ ہو جائیں۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Kabeer. Haythami (Vol.2 Pg.32) has commented on the chain of narrators."]]},{"b":[["n",[["قبیلہ بنو طے کے ایک صاحب نقل کرتے ہیں کہ ",""],["حضرت ابن مسعودؓ","b"],[" مسجد جانے کے لیے گھر سے نکلے اور تیز تیز چلنے لگے تو کسی نے ان سے کہا آپ تو اس طرح چلنے سے منع کرتے ہیں اور خود اس طرح چل رہے ہیں؟ انہوں نے فرمایا میں چاہتا ہوں کہ مجھے نماز کا ابتدائی کنارہ یعنی تکبیر اولیٰ مل جاوے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani."]]},{"b":[["n",[["حضرت سلمہ بن کہیلؒ","b"],[" کہتے ہیں کہ حضرت ابن مسعودؓ نماز کے لیے تیزی سے چل رہے تھے، کسی نے ان سے اس کی وجہ پوچھی تو فرمایا جن چیزوں کی طرف تم تیزی سے چلتے ہو کیا ان میں نماز اس کی سب سے زیادہ حقدار نہیں ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani. Haythami (Vol.2 Pg.32) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوقتادہؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ ہم لوگ حضورؐ کے ساتھ نماز پڑھ رہے تھے کہ اتنے میں حضورؐ نے اپنے پیچھے کچھ لوگوں کا شور سنا۔ جب آپؐ نماز پوری کر چکے تو فرمایا تمہیں کیا ہوا؟ ان لوگوں نے کہا ہم نماز کے لیے تیزی سے چل کر آ رہے تھے۔ حضورؐ نے فرمایا ایسا نہ کرو بلکہ آرام سے چلو اور جتنی نماز مل جائے اسے پڑھ لو اور جتنی رہ جائے اسے قضا کر لو۔",""],[" (9)","s"]]]],"f":[["(9)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.31)."]]}]},"26":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک دفعہ ہم لوگ حضورؐ کے ساتھ مسجد میں بیٹھے ہوئے تھے کہ اتنے میں ایک دیہاتی آیا اور کھڑے ہو کر مسجد میں پیشاب کرنے لگا تو حضورؐ کے صحابہؓ نے کہا ارے ارے ٹھہرو ٹھہرو۔ حضورؐ نے فرمایا اسے پیشاب سے نہ روکو، اسے چھوڑ دو۔ چنانچہ صحابہؓ نے اسے چھوڑ دیا اور اس نے پیشاب پورا کر لیا۔ پھر حضورؐ نے اسے بلا کر فرمایا ان مسجدوں میں پیشاب یا گندگی والا کوئی کام کرنا کسی طرح ٹھیک نہیں ہے۔ یہ مسجدیں تو ",""],["ٱللَّٰه","a"],[" کے ذکر، نماز اور قرآن پڑھنے کے لیے ہی بنی ہیں۔ یا جیسے حضورؐ نے فرمایا۔ پھر حضورؐ نے لوگوں میں سے ایک آدمی کو حکم دیا، اس نے پانی کا ڈول لا کر اس پیشاب پر بہا دیا۔",""],[" (1)","s"]]]],"f":[["(1)","Muslim (Vol.1 Pg.138) and Tahaawi (Vol.1 Pg.8)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضرت معاویہؓ گھر سے باہر آئے اور مسجد میں گئے تو وہاں ایک حلقہ لگا ہوا تھا۔ حضرت معاویہؓ نے ان سے پوچھا آپ لوگ یہاں کیوں بیٹھے ہوئے ہیں؟ ان لوگوں نے کہا ہم بیٹھے ہوئے ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے ہیں۔ حضرت معاویہؓ نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! کیا آپ لوگ صرف اس وجہ سے بیٹھے ہیں؟ ان لوگوں نے کہا واقعی ہم صرف اسی وجہ سے بیٹھے ہیں۔ حضرت معاویہؓ نے کہا میں نے کسی بدگمانی کی وجہ سے تم لوگوں کو قسم نہیں دی (بلکہ اس وجہ سے قسم دی جو آگے حدیث میں آ رہی ہے) اور کوئی صحابی ایسا نہیں ہے جس کا حضورؐ سے میرے جیسا خاص تعلق ہو اور وہ حضورؐ کی طرف سے حدیثیں مجھ سے کم بیان کرتا ہو (یعنی میرا حضورؐ سے تعلق بھی خاص تھا لیکن میری عادت حضورؐ کی طرف سے حدیثیں بہت کم بیان کرنے کی ہے)۔ پھر بھی اس موقع کی ایک حدیث تم لوگوں کو سنا دیتا ہوں۔ ایک مرتبہ حضورؐ مسجد سے باہر تشریف لائے اور مسجد میں صحابہ کرامؓ حلقہ لگا کر بیٹھے ہوئے تھے۔ حضورؐ نے پوچھا آپ لوگ کیوں بیٹھے ہوئے ہیں؟ انھوں نے عرض کیا کہ ہم بیٹھ کر ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے ہیں اور اس بات پر ",""],["ٱللَّٰه","a"],[" کی تعریف کر رہے ہیں کہ اس نے ہمیں اسلام کی ہدایت دی اور اسلام کی دولت سے ہمیں نوازا۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! کیا آپ لوگ صرف اسی وجہ سے بیٹھے ہو؟ انھوں نے عرض کیا ",""],["ٱللَّٰه","a"],[" کی قسم! ہم صرف اسی وجہ سے بیٹھے ہیں۔ حضورؐ نے فرمایا میں نے کسی بدگمانی کی وجہ سے تمہیں قسم نہیں دی بلکہ ابھی جبرائیلؑ میرے پاس آئے اور یہ خبر سنا گئے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تم لوگوں کی وجہ سے ملائکہ پر فخر فرما رہے ہیں۔",""],[" (2)","s"]]]],"f":[["(2)","Muslim, as quoted in Riyaadhus Saaliheen (Pg.156). Tirmidhi and Nasa'ee have reported a similar narration, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.249)."]]},{"b":[["n",[["حضرت ابو واقد حارث بن عوفؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ مسجد میں تشریف فرما تھے اور لوگ بھی آپؐ کے ساتھ تھے کہ اتنے میں تین آدمی آئے، ان میں سے دو تو آپؐ کی طرف چلے اور ایک چلا گیا۔ وہ دونوں جا کر حضورؐ کے پاس کھڑے ہو گئے۔ ان میں سے ایک کو حلقہ میں خالی جگہ نظر آئی، وہ جا کر اس جگہ بیٹھ گیا اور دوسرا لوگوں کے پیچھے بیٹھ گیا اور تیسرا پیٹھ پھیر کر چلا گیا۔ جب آپؐ حلقہ سے فارغ ہوئے تو آپؐ نے فرمایا کیا میں تمہیں ان تین آدمیوں کے بارے میں نہ بتلاؤں؟ ایک نے ",""],["ٱللَّٰه","a"],[" کے پاس اپنی جگہ بنائی تو ",""],["ٱللَّٰه","a"],[" نے اسے (اپنی رحمت میں) جگہ دے دی اور دوسرا شرما گیا تو ",""],["ٱللَّٰه","a"],[" نے بھی اس کے ساتھ حیا کا معاملہ کیا (اپنی رحمت سے محروم نہ فرمایا) اور تیسرے نے (",""],["ٱللَّٰه","a"],[" سے) اعراض کیا تو ",""],["ٱللَّٰه","a"],[" نے بھی اس سے اعراض فرمایا۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari and Muslim, as quoted in Riyaadhus Saaliheen (Pg.515). Maalik and Tirmidhi have reported a similar narration, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.21)."]]},{"b":[["n",[["حضرت ابوالقمرؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ ہم لوگ مسجد میں مختلف حلقوں میں بیٹھے ہوئے آپس میں حدیثوں کا مذاکرہ کر رہے تھے کہ اتنے میں حضورؐ اپنے ایک حجرے سے باہر مسجد میں تشریف لائے اور تمام حلقوں پر نظر ڈالی اور پھر قرآن والوں کے ساتھ بیٹھ گئے (جو قرآن سیکھ سکھا رہے تھے) اور فرمایا مجھے اس مجلس (میں بیٹھنے) کا حکم دیا گیا ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Mandah, as quoted in Isaabah (Vol.4 Pg.160). Ibn Abdul Birr has also reported the narration in his Istee'aab (Vol.4 Pg.164), as has Abu Amr Daani in his Tabaqaatul Qurraa, as quoted in Kanzul Ummaal (Vol.1 Pg.219)."]]},{"b":[["n",[["حضرت کلیب بن شہابؒ","b"],[" کہتے ہیں کہ ایک مرتبہ حضرت علیؓ نے مسجد میں بہت زیادہ شور کی آوازیں سنیں، لوگ قرآن پڑھ رہے تھے تو حضرت علیؓ نے فرمایا ان لوگوں کو خوشخبری ہو، یہی لوگ حضورؐ کو تمام لوگوں سے زیادہ محبوب تھے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Awsat, as quoted in Majma'uz Zawaa'id (Vol.7 Pg.166). Haythami has however commented on the chain of narrators. Ibn Munee has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.218)."]]},{"b":[["n",[["حضرت کلیبؒ","b"],[" کہتے ہیں کہ حضرت علیؓ کوفہ کی مسجد میں تھے، انھوں نے وہاں بہت زیادہ شور کی آوازیں سنیں تو انھوں نے پوچھا یہ لوگ کون ہیں؟ تو ساتھیوں نے بتایا کہ یہ لوگ قرآن پڑھ رہے ہیں اور ایک دوسرے سے قرآن سیکھ رہے ہیں۔ حضرت علیؓ نے فرمایا غور سے سنو! انہی لوگوں سے حضورؐ کو سب سے زیادہ محبت تھی۔",""],[" (6)","s"]]]],"f":[["(6)","Bazzaar, as quoted in Majma'uz Zawaa'id (Vol.7 Pg.162)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" ایک مرتبہ مدینہ کے بازار سے گزرے تو کھڑے ہو کر بلند آواز سے کہا اے بازار والو! تم لوگ کتنے زیادہ عاجز ہو۔ بازار والوں نے کہا اے ابوہریرہ! کیا بات ہے؟ انھوں نے کہا بات یہ ہے کہ حضورؐ کی میراث تقسیم ہو رہی ہے اور تم لوگ یہاں بیٹھے ہو، تو کیا تم لوگ جا کر اس میں سے اپنا حصہ نہیں لیتے؟ لوگوں نے پوچھا کہاں تقسیم ہو رہی ہے؟ انھوں نے فرمایا مسجد میں۔ چنانچہ وہ بازار والے بہت تیزی سے مسجد گئے اور حضرت ابوہریرہؓ وہاں ٹھہرے رہے۔ تھوڑی دیر میں وہ لوگ واپس آ گئے تو حضرت ابوہریرہؓ نے ان سے پوچھا تمہیں کیا ہوا؟ (کہ جلدی سے واپس آ گئے)۔ انھوں نے کہا اے ابوہریرہ! ہم مسجد گئے تھے، ہم نے اندر جا کر دیکھا تو ہمیں وہاں کوئی چیز تقسیم ہوتی نظر نہیں آئی۔ حضرت ابوہریرہؓ نے ان سے پوچھا کیا تم نے مسجد میں کوئی آدمی نہیں دیکھا؟ انھوں نے کہا ہم نے بہت سے آدمی دیکھے، کچھ لوگ نماز پڑھ رہے تھے اور کچھ لوگ قرآن پڑھ رہے تھے اور کچھ لوگ حلال اور حرام کا مذاکرہ کر رہے تھے۔ تو ان سے حضرت ابوہریرہؓ نے فرمایا تمہارا بھلا ہو، یہی اعمال مسجد تو حضرت محمدؐ کی میراث ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Awsat, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.66)."]]},{"b":[["n",[["حضرت ابن معاویہ کندیؒ","b"],[" کہتے ہیں کہ میں ملک شام سے حضرت عمرؓ کی خدمت میں حاضر ہوا۔ انھوں نے مجھ سے لوگوں کے بارے میں پوچھا کہ شاید ایسا ہوتا ہوگا کہ آدمی بدکے ہوئے اونٹ کی طرح مسجد میں آتا ہوگا، اگر اسے اپنی قوم کی مجلس نظر آتی ہو اور جان پہچان والے لوگ نظر آتے ہوں تو ان کے پاس بیٹھ جاتا ہوگا ورنہ نہیں۔ میں نے کہا نہیں، ایسا نہیں ہے بلکہ مختلف مختلف مجلسیں مسجد میں ہوتی ہیں (اور ہر مجلس میں مختلف قوموں کے لوگ ہوتے ہیں) اور لوگ ان میں بیٹھ کر خیر کے اعمال سیکھتے ہیں اور ان کے بارے میں مذاکرہ کرتے ہیں۔ حضرت عمرؓ نے فرمایا جب تک تم ایسے رہو گے خیر پر رہو گے۔",""],[" (8)","s"]]]],"f":[["(8)","Marwazi and Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک دن ہم لوگ مسجد میں بیٹھے ہوئے تھے کہ اتنے میں حضورؐ ہمارے پاس تشریف لائے اور فرمایا آؤ یہود کے پاس چلیں۔ چنانچہ (آپؐ صحابہؓ کو لے کر ان کے پاس گئے اور) ان سے فرمایا اسلام لے آؤ سلامتی پا لو گے۔ ان یہودیوں نے کہا آپؐ نے (",""],["ٱللَّٰه","a"],[" کا پیغام) پہنچا دیا۔ آپؐ نے فرمایا میں بھی یہی چاہتا ہوں لیکن پھر بھی تم لوگ اسلام لے آؤ سلامتی میں رہو گے۔ انھوں نے پھر کہا آپؐ نے یہ پیغام پہنچا دیا۔ آپؐ نے فرمایا میں بھی یہی چاہتا ہوں لیکن پھر بھی تم لوگ اسلام لے آؤ سلامتی میں رہو گے۔ پھر آپؐ نے فرمایا اچھی طرح سمجھ لو کہ زمین ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی ہے۔ اب میں تمہیں اس سرزمین سے جلا وطن کرنا چاہتا ہوں، لہٰذا تم میں سے جس کی جو چیز بک سکتی ہو وہ اسے بیچ دے ورنہ اچھی طرح سمجھ لو کہ یہ زمین ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Bukhaari, Muslim and Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.44)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ غزوہ خندق کے دن حضرت سعدؓ زخمی ہوئے، ان کو قریش کے حبان بن عرقہ نامی کافر نے تیر مارا تھا جو ان کے بازو کی اکحل نامی رگ میں لگا تھا۔ حضورؐ نے ان کے لیے مسجد میں خیمہ لگوایا تھا تا کہ وہ حضورؐ کے قریب رہیں اور ان کی عیادت کے لیے بار بار جانے میں سہولت رہے۔ جب حضورؐ غزوہ خندق سے واپس آئے تو آپؐ نے ہتھیار رکھ دیے اور غسل فرمایا۔ پھر حضرت جبرائیلؑ اپنے سر سے غبار جھاڑتے ہوئے آپؐ کی خدمت میں حاضر ہوئے اور عرض کیا آپ نے تو ہتھیار رکھ دیے لیکن ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے تو ابھی نہیں رکھے، آپ ان کی طرف تشریف لے چلیں۔ حضورؐ نے پوچھا کہاں؟ تو جواب میں حضرت جبرائیلؑ نے بنو قریظہ کی طرف اشارہ کیا۔ چنانچہ حضورؐ ان کے پاس تشریف لے گئے تو وہ آپؐ کے فیصلہ پر رضا مند ہو گئے۔ حضورؐ نے ان کا فیصلہ حضرت سعدؓ کے ذمہ لگایا تو حضرت سعدؓ نے کہا ان کے بارے میں میرا فیصلہ یہ ہے کہ ان میں سے جو لڑنے کے قابل ہیں ان کو قتل کر دیا جائے اور ان کی عورتوں اور بچوں کو قیدی بنا لیا جائے اور ان کے سارے مال کو (مسلمانوں میں بطور مال غنیمت کے) تقسیم کر دیا جائے۔ حضرت ہشامؒ راوی کہتے ہیں کہ مجھے میرے والد نے حضرت عائشہؓ کی طرف سے نقل کرتے ہوئے یہ بتایا کہ حضرت سعدؓ نے یہ دعا مانگی: اے ",""],["ٱللَّٰه","a"],["! تجھے معلوم ہے کہ مجھے اس قوم سے جہاد کرنے سے زیادہ کسی اور سے جہاد کرنا محبوب نہیں ہے جس قوم نے تیرے رسول کو جھٹلایا اور انھیں (ان کے وطن مکہ سے) نکالا (اس سے مراد قبیلہ قریش ہے)۔ اے ",""],["ٱللَّٰه","a"],["! اب میرا خیال تو یہ ہے کہ تو نے ہمارے اور اس قوم کے درمیان جنگ ختم کر دی ہے یعنی اس غزوہ خندق کے بعد اب ان سے جنگ نہیں ہوگی۔ لیکن اگر قریش سے کوئی جنگ ابھی ہونے والی ہے تو پھر تو مجھے ان کے لیے زندہ رکھ تا کہ تیری رضا کی خاطر میں ان سے لڑوں اور اگر تو نے ان سے لڑائی ختم کر دی ہے تو میری اس رگ کے زخم کو جاری کر اور اسی کی وجہ سے مجھے موت نصیب فرما۔ چنانچہ ان کے سینے کے زخم سے بہت خون بہنے لگا اور مسجد میں بنو غفار کا بھی ایک خیمہ لگا ہوا تھا، اس خیمہ تک ان کا خون بہہ کر پہنچ گیا جس سے وہ لوگ گھبرا گئے تو اس خیمہ والوں نے کہا اے خیمہ والو! یہ خون کیا ہے جو تمہاری طرف سے ہماری طرف آ رہا ہے؟ جا کر دیکھا تو حضرت سعدؓ کے زخم میں سے خون بہہ رہا تھا جس سے ان کا انتقال ہو گیا۔",""],[" (10)","s"]]]],"f":[["(10)","Bukhaari and Muslim, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.52)."]]},{"b":[["n",[["حضرت یزید بن عبد","b"],["ٱللَّٰه","a"],[" بن قسیطؒ","b"],[" فرماتے ہیں کہ اہل صفہ حضورؐ کے وہ صحابی تھے جن کا (مدینہ میں) کوئی گھر نہیں تھا، اس لیے وہ حضورؐ کے زمانے میں مسجد میں سویا کرتے تھے اور دن بھر اسی میں رہتے تھے۔ ان کا مسجد کے علاوہ اور کوئی ٹھکانہ نہ تھا۔ رات کو جب کھانے کا وقت آتا تو حضورؐ انھیں بلا کر اپنے صحابہؓ میں تقسیم فرما دیتے، پھر بھی ان میں سے کچھ لوگ حضورؐ کے ساتھ رات کا کھانا کھاتے۔ یہ سلسلہ یونہی چلتا رہا یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے وسعت عطا فرما دی۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Sa'd (Vol.2 Pg.20)."]]},{"b":[["n",[["حضرت اسماء بنت یزیدؓ","b"],[" فرماتی ہیں کہ حضرت ابوذر غفاریؓ حضورؐ کی خدمت کیا کرتے تھے، وہ جب حضورؐ کی خدمت سے فارغ ہوتے تو جا کر مسجد میں ٹھہر جاتے اور یہ مسجد ہی ان کا گھر تھا، اسی میں لیٹا کرتے تھے۔ ایک رات حضورؐ مسجد میں تشریف لے گئے تو حضرت ابوذرؓ کو مسجد میں زمین پر لیٹے ہوئے پایا۔ آپؐ نے انہیں پاؤں مبارک سے ذرا ہلایا۔ وہ اٹھ کر سیدھے بیٹھ گئے تو حضورؐ نے ان سے فرمایا کیا میں تمہیں (مسجد میں) سوتے ہوئے نہیں دیکھ رہا ہوں؟ حضرت ابوذرؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! پھر میں کہاں سووں؟ کیا میرا مسجد کے علاوہ کوئی گھر ہے؟ آگے حدیث امر خلافت کے بارے میں ذکر کی۔",""],[" (12)","s"]]],["p",[["حضرت ابوذرؓ","b"],[" حضورؐ کی خدمت کیا کرتے تھے اور جب حضورؐ کی خدمت سے فارغ ہو جاتے تو آ کر مسجد میں لیٹ جاتے۔ اور ",""],["ٱللَّٰه","a"],[" کے راستے کے مہمانوں کی ضیافت کے باب میں مسجد میں سونے کے بارے میں حضرت ابوذرؓ اور دیگر صحابہؓ کے قصے گزر چکے ہیں۔",""],[" (13)","s"]]]],"f":[["(12)","Ahmad and Tabraani. Haythami (Vol.2 Pg.22) has commented on the chain of narrators."],["(13)","Tabraani."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" سے مسجد میں دوپہر کو آرام کرنے کے بارے میں پوچھا گیا تو فرمایا میں نے حضرت عثمان بن عفانؓ کو زمانہ خلافت میں مسجد میں دوپہر کو آرام کرتے ہوئے دیکھا ہے۔",""],[" (14)","s"]]]],"f":[["(14)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.261)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ ہم چند نوجوان حضورؐ کے زمانے میں مسجد میں رات کو سویا کرتے تھے۔",""],["(15)","s"],[" ",""],["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ ہم جمعہ کی نماز پڑھ کر واپس آتے اور پھر دوپہر کو آرام کیا کرتے۔",""],[" (16)","s"]]]],"f":[["(15)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.261)."],["(16)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.261)."]]},{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے فرمایا جب کوئی آدمی زیادہ دیر تک مسجد میں بیٹھے تو اس کے لیے کمر سیدھی کرنے کے لیے لیٹنے میں کوئی حرج نہیں ہے کیونکہ اس طرح لیٹنے سے اس کا دل نہیں اکتائے گا۔",""],[" (17)","s"]]]],"f":[["(17)","Ibn Sa'd (Vol.3 Pg.294)."]]},{"b":[["n",[["حضرت خلید ابواسحاقؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابن عباسؓ سے مسجد میں سونے کے بارے میں پوچھا تو انھوں نے فرمایا اگر تم نماز اور طواف کی وجہ سے سونا چاہتے ہو تو پھر کوئی حرج نہیں ہے۔",""],[" (18)","s"]]]],"f":[["(18)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.261)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ جب کسی رات کو تیز ہوا اور آندھی چلا کرتی تو حضورؐ گھبرا کر ایک دم مسجد تشریف لے جاتے اور آندھی ختم ہونے تک وہاں ہی رہا کرتے اور جب آسمان میں سورج گرہن یا چاند گرہن ہوتا تو آپؐ گھبرا کر نماز پڑھنے کی جگہ یا عیدگاہ تشریف لے جاتے۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Abi Dunya, as quoted in Kanzul Ummaal (Vol.4 Pg.289)."]]},{"b":[["n",[["حضرت عطاءؒ","b"],[" کہتے ہیں کہ حضرت یعلیٰ بن امیہؓ کو حضورؐ کی صحبت حاصل تھی، وہ جب تھوڑی دیر کے لیے بھی مسجد میں بیٹھا کرتے تو اعتکاف کی نیت کر لیا کرتے۔",""],[" (20)","s"]]]],"f":[["(20)","Abu Nu'aym in his Hilya (Vol.3 Pg.312)."]]},{"b":[["n",[["حضرت عطیہ بن سفیان بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ قبیلہ ثقیف کا وفد رمضان میں حضورؐ کی خدمت میں آیا تو حضورؐ نے ان کے لیے مسجد میں خیمہ لگوایا۔ پھر جب وہ مسلمان ہو گئے تو انھوں نے حضورؐ کے ساتھ روزے رکھنے شروع کر دیے۔",""],[" (21)","s"]]]],"f":[["(21)","Tabraani. Haythami (Vol.2 Pg.28) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عثمان بن ابی العاصؓ","b"],[" فرماتے ہیں کہ قبیلہ ثقیف کا وفد حضورؐ کی خدمت میں آیا تو حضورؐ نے انہیں مسجد میں ٹھہرایا تا کہ اس سے ان کے دل زیادہ نرم ہوں۔ اس سے آگے اور حدیث ذکر کی جیسے ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی طرف دعوت دینے کے باب میں قبیلہ ثقیف کے اسلام لانے کے قصہ میں گزر چکا ہے۔",""],[" (22)","s"]]]],"f":[["(22)","Under the heading \"The Banu Thaqeef tribe of Taa'if Accept Islaam\" and the subheading \"Thaqeef Tribe Sends Abd Yaaleel bin Amr with a Delegation to Rasulullaah, who is Informed of their Arrival\"."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن زبیرؓ","b"],[" فرماتے ہیں کہ ایک دن ہم نے مسجد میں حضورؐ کے ساتھ بھنا ہوا گوشت کھایا پھر نماز کھڑی ہو گئی تو ہم نے صرف کنکریوں سے ہاتھ پونچھے (اور کچھ نہیں کیا اور نماز میں شامل ہو گئے)۔",""],[" (23)","s"]]]],"f":[["(23)","Tabraani. Haythami (Vol.2 Pg.21) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ مسجد فضیخ میں حضورؐ کی خدمت میں فضیخ لایا گیا جسے آپؐ نے نوش فرمایا، اسی وجہ سے اس مسجد کا نام مسجد فضیخ ہے۔ فضیخ نیم پختہ کھجور کے شربت کو کہا جاتا ہے۔",""],[" (24)","s"]]]],"f":[["(24)","Ahmad."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ مسجد فضیخ میں حضورؐ کی خدمت میں نیم پختہ کھجور کے شربت کے مٹکے لائے گئے، آپؐ نے اس شربت کو نوش فرمایا اور اسی وجہ سے اس کا نام مسجد فضیخ رکھا گیا۔",""],[" (25)","s"]]],["p",[["اور اس سے پہلے مسجد میں مختلف اعمال کے قصے گزر چکے ہیں۔ مال خرچ کرنے کے باب میں کھانا اور مال تقسیم کرنے کے باب میں مسجد میں حضرت عثمانؓ کی بیعت کا قصہ، اور صحابہؓ کے باہمی اتحاد اور اتفاق رائے کے باب میں مسجد میں حضرت ابوبکرؓ کی بیعت کا قصہ، اور ",""],["ٱللَّٰه","a"],[" کی طرف دعوت دینے کے باب میں حضرت ضمامؓ کو مسجد میں دعوت دینے اور ان کے اسلام لانے کا قصہ، اور مسجد میں حضرت کعب بن زہیرؓ کے اسلام لانے اور مشہور قصیدہ پڑھنے کا قصہ، اور صحابہؓ کے باہمی اتحاد اور اتفاق رائے کے باب میں مسجد اہل شوریٰ کے مشورہ کے لیے بیٹھنے کا قصہ، اور مال خرچ کرنے کے باب میں صبح کے وقت مسجد میں صحابہؓ کا حضورؐ کے ساتھ بیٹھنے کا قصہ، اور دنیا کی وسعت اور کثرت سے ڈرنے کے باب میں مسجد میں نمازوں کے بعد لوگوں کی ضرورت کے لیے حضرت عمرؓ کے بیٹھنے کا قصہ، اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اور اس کے رسولؐ کی محبت کو مضبوطی سے پکڑ لینے کے باب میں مسجد میں حضرت ابوبکرؓ اور دوسرے صحابہؓ کے رونے کا قصہ۔",""]]]],"f":[["(25)","Abu Ya'la. Haythami has commented on the chain of narrators."]]}]},"27":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" کے ایک غلام فرماتے ہیں کہ ایک مرتبہ میں (اپنے آقا) حضرت ابوسعیدؓ کے ساتھ تھا، وہ حضورؐ کے ساتھ جا رہے تھے۔ اتنے میں ہم لوگ مسجد میں داخل ہو گئے تو ہم نے دیکھا کہ مسجد کے بیچ میں ایک آدمی پیٹھ اور ٹانگوں کو کپڑے سے باندھ کر بیٹھا ہوا",""],["(1)","s"],[" ہے اور دونوں ہاتھوں کی انگلیاں ایک دوسرے میں ڈال رکھی ہیں۔ حضورؐ نے اسے اشارے سے سمجھانے کی کوشش کی لیکن وہ سمجھ نہ سکا تو حضورؐ نے حضرت ابوسعیدؓ کی طرف متوجہ ہو کر فرمایا کہ جب تم میں سے کوئی مسجد میں ہو تو اپنی انگلیاں ہرگز ایک دوسرے میں نہ ڈالے کیونکہ یہ شیطانی حرکت ہے اور جب تم میں سے کوئی آدمی مسجد میں ہوتا ہے تو وہ مسجد سے باہر جانے تک نماز ہی میں شمار ہوتا ہے۔",""],[" (2)","s"]]]],"f":[["(1)","Where a person sits with his legs folded in an upright position and thighs against the chest, held by the arms or by a cloth tied around them and around the back."],["(2)","Ahmad. Haythami (Vol.2 Pg.25) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" فرماتے ہیں کہ جب حضورؐ خیبر فتح کر چکے تو لوگ لہسن پر ٹوٹ پڑے اور اسے خوب کھانے لگے۔ اس پر حضورؐ نے فرمایا جو یہ بودار سبزی کھائے وہ ہرگز ہماری مسجد کے قریب نہ آئے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.2 Pg.17) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمر بن خطابؓ","b"],[" جمعہ کا خطبہ دے رہے تھے۔ انھوں نے خطبہ میں فرمایا اے لوگو! تم یہ دو بودار چیزیں پیاز اور لہسن کھاتے ہو حالانکہ میں نے حضورؐ کو دیکھا ہے کہ جب حضورؐ کو مسجد میں کسی سے ان دونوں کی بو محسوس ہوتی تو آپؐ کے فرمانے پر اسے بقیع کی طرف نکال دیا جاتا، لہٰذا جو انھیں کھانا چاہتا ہے وہ انہیں پکا کر ان کی بو ختم کر لے۔",""],[" (4)","s"]]]],"f":[["(4)","Muslim, Nasa'ee and Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.88)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ ایک دن حضورؐ بیان فرما رہے تھے، بیان کے دوران آپؐ نے مسجد کی سامنے والی دیوار پر کھنکار پڑا ہوا دیکھا تو آپؐ کو لوگوں پر بڑا غصہ آیا۔ پھر آپؐ نے اسے کھرچا اور زعفران منگا کر اس جگہ مل دیا اور فرمایا جب تم میں سے کوئی آدمی نماز پڑھتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے چہرے کے سامنے ہوتے ہیں، چنانچہ اسے اپنے سامنے تھوکنا نہیں چاہیے۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari, Muslim and Abu Dawood."]]},{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" کی روایت میں ہے کہ پھر حضورؐ غصہ سے لوگوں کی طرف متوجہ ہوئے اور فرمایا کیا تم میں سے کوئی اس بات کو پسند کرتا ہے کہ کوئی آدمی اس کے سامنے آ کر اس کے چہرے پر تھوک دے؟ تم میں سے کوئی آدمی جب نماز میں کھڑا ہوتا ہے تو وہ اپنے رب کے سامنے ہوتا ہے اور فرشتہ اس کے دائیں طرف ہوتا ہے، لہٰذا اسے نہ اپنے سامنے تھوکنا چاہیے اور نہ دائیں طرف۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.163)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ جیسے گوشت کا ٹکڑا یا کھال آگ میں سکڑ جاتی ہے ایسے ہی کھنکار مسجد میں پھینکنے سے مسجد سکڑ جاتی ہے (یعنی یہ کام مسجد کو بہت برا لگتا ہے، یہ مسجد کے ادب کے خلاف ہے)۔",""],[" (7)","s"]]]],"f":[["(7)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.260)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ حضرت بنہ جہنیؓ نے انہیں بتایا کہ مسجد میں چند لوگوں پر حضورؐ کا گزر ہوا۔ آپؐ نے دیکھا کہ ننگی تلوار ایک دوسرے کو دے رہے ہیں تو آپؐ نے فرمایا جو ایسا کرے اس پر ",""],["ٱللَّٰه","a"],[" لعنت فرمائے، کیا میں نے تمہیں اس سے روکا نہیں؟ جب تم میں سے کسی نے ننگی تلوار پکڑی ہوئی ہو اور وہ اپنے ساتھی کو دینا چاہے تو اسے چاہیے کہ وہ تلوار کو نیام میں ڈال کر دے۔",""],[" (8)","s"]]]],"f":[["(8)","Baghawi, Ibnus Sakan, Tabraani and others, as quoted in Kanzul Ummaal (Vol.4 Pg.262)."]]},{"b":[["n",[["حضرت سلیمان بن موسیٰؒ","b"],[" کہتے ہیں کہ کسی آدمی نے حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ سے مسجد میں تلوار ننگی کرنے کے بارے میں پوچھا تو انھوں نے فرمایا ہم اسے اچھا نہیں سمجھتے تھے۔ ایک آدمی مسجد میں تیر صدقہ کیا کرتا تھا۔ حضورؐ نے اسے حکم دیا کہ وہ جب بھی مسجد سے تیر لے کر گزرے تو وہ تیروں کے پھلوں کو اچھی طرح سے پکڑ کر گزرے۔",""],[" (9)","s"]]]],"f":[["(9)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.262)."]]},{"b":[["n",[["حضرت محمد بن عبید","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں کہ ہم لوگ مسجد میں حضرت ابوسعید خدریؓ کے پاس تھے تو ایک آدمی نے اپنا تیر پلٹا تو حضرت ابوسعیدؓ نے کہا کیا اسے معلوم نہیں کہ حضورؐ نے مسجد میں ہتھیار الٹنے پلٹنے سے منع فرمایا ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani. Haythami (Vol.2 Pg.26) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے مسجد میں گمشدہ جانور کا اعلان کیا اور یہ کہا کون ہے وہ (جس نے سرخ اونٹ دیکھا ہو اور وہ اس کے مالک کو) سرخ اونٹ (دینے) کے لیے بلا رہا ہو؟ اس پر حضورؐ نے فرمایا تمہیں تمہارا اونٹ نہ ملے، مسجدیں تو جن کاموں کے لیے بنائی گئی ہیں بس انہی کے لیے استعمال ہونی چاہئیں (اور گمشدہ چیز کا اعلان ان کاموں میں سے نہیں ہے)۔",""],[" (11)","s"]]]],"f":[["(11)","Muslim, Nasa'ee and Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.167)."]]},{"b":[["n",[["حضرت ابن سیرینؒ","b"],[" یا کوئی اور صاحب بیان کرتے ہیں کہ حضرت ابن مسعودؓ نے مسجد میں ایک آدمی کو گمشدہ چیز کا اعلان کرتے ہوئے سنا تو حضرت ابن مسعودؓ نے اسے ڈانٹ کر خاموش کر دیا اور فرمایا ہم کو اس سے روکا گیا ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.167)."]]},{"b":[["n",[["حضرت ابن سیرینؒ","b"],[" کہتے ہیں کہ حضرت ابی بن کعبؓ نے ایک آدمی کو مسجد میں اپنی گمشدہ چیز کا اعلان کرتے ہوئے سنا تو حضرت ابیؓ اس پر ناراض ہوئے۔ تو اس آدمی نے کہا اے ابوالمنذر! آپ تو ایسی سخت بات نہیں کیا کرتے تھے۔ تو فرمایا (مسجد میں گمشدہ چیز کا اعلان کرنے والے پر) ایسے ہی (غصہ) کرنے کا ہمیں حکم دیا گیا ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.260)."]]},{"b":[["n",[["حضرت سائب بن یزیدؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ میں مسجد میں سویا ہوا تھا، کسی نے مجھے کنکری ماری (جس سے میری آنکھ کھل گئی) تو میں نے دیکھا کہ وہ حضرت عمر بن خطابؓ ہیں۔ انھوں نے فرمایا جاؤ اور ان دونوں کو میرے پاس لے آؤ۔ چنانچہ میں ان دونوں کو حضرت عمرؓ کے پاس لے آیا۔ حضرت عمرؓ نے پوچھا تم دونوں کون ہو؟ انھوں نے کہا ہم طائف کے ہیں۔ حضرت عمرؓ نے فرمایا اگر تم دونوں اس شہر کے ہوتے تو میں تم کو دردناک سزا دیتا، تم رسول ",""],["ٱللَّٰه","a"],["ؐ کی مسجد میں آواز بلند کر رہے ہو۔",""],[" (14)","s"]]]],"f":[["(14)","Bukhaari and Bayhaqi."]]},{"b":[["n",[["حضرت ابراہیمؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے ایک آدمی کی (اونچی) آواز مسجد میں سنی تو فرمایا کیا تم جانتے ہو تم کہاں ہو؟ کیا تم جانتے ہو تم کہاں ہو؟ اور اونچی آواز کرنے پر حضرت عمرؓ نے یوں ناگواری کا اظہار فرمایا۔",""],[" (15)","s"]]]],"f":[["(15)","Ibraheem bin Sa'd and Ibn Mubaarak, as quoted in Kanzul Ummaal (Vol.4 Pg.258,260)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ جب بھی مسجد تشریف لے جاتے تو اونچی آواز سے یہ اعلان فرماتے کہ مسجد میں شور کرنے سے بچو۔ دوسری روایت میں یہ ہے کہ حضرت عمرؓ بلند آواز سے فرماتے مسجد میں بیکار باتوں سے بچو۔",""],["(16)","s"],[" ",""],["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ نے مسجد میں شور کرنے سے منع فرمایا اور فرمایا ہماری اس مسجد میں آواز بلند نہ کی جائے۔",""],[" (17)","s"]]]],"f":[["(16)","Abdur Razzaaq, Ibn Abi Shaybah and Bayhaqi."],["(17)","Abdur Razzaaq and Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.259)."]]},{"b":[["n",[["حضرت سالمؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے مسجد کے ساتھ ایک چبوترہ بنایا جس کا نام بطیحا رکھا اور فرماتے تھے کہ جو آدمی شور مچانا چاہے یا شعر پڑھنا چاہے یا آواز بلند کرنا چاہے اسے چاہیے کہ وہ (مسجد سے) باہر اس چبوترے پر چلا جائے۔",""],[" (18)","s"]]]],"f":[["(18)","Maalik and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.259)."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں کہ کسی جرم میں ایک آدمی کو پکڑ کر حضرت عمرؓ کے پاس لایا گیا تو انھوں نے فرمایا تم دونوں اسے مسجد سے باہر لے جاؤ اور وہاں اسے مارو۔",""],[" (19)","s"]]]],"f":[["(19)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.260)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فجر کی اذان اور اقامت کے درمیانی وقفے میں کچھ لوگوں کو مسجد کی قبلہ والی دیوار کے ساتھ کمر لگا کر بیٹھے ہوئے دیکھا تو فرمایا تم لوگ فرشتوں اور ان کی نماز کے درمیان حائل نہ ہو۔",""],[" (20)","s"]]]],"f":[["(20)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.23)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عامر الہانیؒ","b"],[" کہتے ہیں کہ حضرت حابس بن سعد طائیؓ کو حضورؐ کی صحبت کا شرف حاصل تھا، ایک مرتبہ وہ سحری کے وقت مسجد میں گئے تو انھوں نے دیکھا کہ کچھ لوگ مسجد کے اگلے حصے میں نماز پڑھ رہے ہیں تو فرمایا رب کعبہ کی قسم! یہ لوگ تو ریا کار ہیں، انہیں ڈراؤ، جو انہیں ڈرائے گا وہ ",""],["ٱللَّٰه","a"],[" اور رسولؐ کی اطاعت کرنے والا ہوگا۔ چنانچہ کچھ لوگ ان کے پاس گئے اور انہیں باہر نکال دیا تو حضرت حابسؓ نے فرمایا کہ فرشتے سحری کے وقت مسجد کے اگلے حصے میں نماز پڑھتے ہیں۔",""],[" (21)","s"]]]],"f":[["(21)","Ahmad and Tabraani. Haythami (Vol.2 Pg.16) has commented on the chain of narrators. Ibn Asaakir and Abu Nu'aym have also reported the narration, as quoted in Kanzul Ummaal (Vol.4 Pg.262). Ibn Sa'd (Vol.7 Pg.431) has reported a similar narration."]]},{"b":[["n",[["حضرت مرہ ہمدانیؒ","b"],[" کہتے ہیں کہ میں نے اپنے دل میں سوچا کہ میں کوفہ کی مسجد کے ہر ستون کے پیچھے دو رکعت نماز پڑھوں گا۔ میں نماز پڑھ رہا تھا کہ اتنے میں حضرت ابن مسعودؓ مسجد میں آ گئے۔ میں اپنی یہ بات ان کو بتانے گیا تو ایک آدمی مجھ سے پہلے ان کے پاس چلا گیا اور میں جو کچھ کر رہا تھا وہ اس آدمی نے ان کو بتا دیا۔ اس پر حضرت ابن مسعودؓ نے فرمایا اگر اسے یہ معلوم ہوتا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ سب سے قریبی ستون کے پاس بھی ہیں تو نماز پوری کرنے تک اس ستون سے آگے نہ بڑھتا (یعنی مسجد کے ہر ستون کے پاس نماز پڑھنا کوئی خاص ثواب کا کام نہیں ہے، ثواب میں نماز کے سارے ستون برابر ہیں)۔",""],[" (22)","s"]]]],"f":[["(22)","Tabraani. Haythami (Vol.2 Pg.16) has commented on the chain of narrators."]]}]},"28":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوعمیر بن انسؓ","b"],[" اپنے انصاری چچوں سے نقل کرتے ہیں کہ حضورؐ کو نماز کے بارے میں بڑا فکر ہوا کہ اس کے لیے لوگوں کو کیسے جمع کریں۔ کسی نے تجویز پیش کی کہ نماز کا وقت شروع ہونے پر ایک جھنڈا کھڑا کر دیا کریں۔ لوگ جب جھنڈے کو دیکھا کریں گے تو ایک دوسرے کو بتا دیا کریں گے لیکن آپؐ کو یہ رائے پسند نہ آئی۔ پھر کسی نے یہودیوں کے بگل کا تذکرہ کیا، آپؐ کو یہ بھی پسند نہ آیا اور فرمایا یہ تو یہودیوں کا کام ہے۔ پھر کسی نے آپؐ سے گھنٹے کا ذکر کیا تو آپؐ نے فرمایا یہ تو عیسائیوں کا کام ہے۔ حضورؐ کی زیادہ فکر کی وجہ سے حضرت عبد",""],["ٱللَّٰه","a"],[" بن زیدؓ کو بہت زیادہ فکر ہو گیا، وہ گھر گئے تو انہیں خواب میں اذان دکھائی گئی۔ آگے اور حدیث بھی ذکر کی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن زیدؓ","b"],[" فرماتے ہیں کہ حضورؐ کو نماز کی اطلاع دینے کے بارے میں فکر ہوا۔ جب نماز کا وقت آتا تو حضورؐ کسی آدمی کو اوپر چڑھا دیتے جو ہاتھ سے اشارہ کرتا۔ جو اشارہ دیکھ لیتا وہ آ جاتا اور جو نہ دیکھتا اسے نماز کا پتہ نہ چلتا۔ اس کا حضورؐ کو بہت زیادہ فکر تھا۔ بعض صحابہؓ نے آپؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ اگر نماز کے وقت گھنٹہ بجانے کا حکم دے دیں تو اچھا ہے، آپؐ نے فرمایا یہ تو عیسائیوں کا کام ہے۔ پھر انھوں نے عرض کیا اگر آپ بگل بجانے کا حکم دے دیں تو اچھا ہے۔ آپؐ نے فرمایا نہیں، یہ تو یہودیوں کا کام ہے۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کہتے ہیں کہ میں اپنے گھر واپس گیا اور حضورؐ کو اس بارے میں فکر مند دیکھنے کی وجہ سے میں بہت پریشان تھا۔ رات کو فجر سے پہلے مجھے کچھ اونگھ آ گئی، میں نیند اور بیداری کی درمیانی حالت میں تھا۔ میں نے ایک آدمی کو دیکھا جس نے دو سبز کپڑے پہنے ہوئے تھے، وہ مسجد کی چھت پر کھڑا ہوا اور دونوں کانوں میں انگلیاں ڈال کر اذان دینے لگا۔",""],[" (2)","s"]]]],"f":[["(2)","Abush Sheikh, as quoted in Kanzul Ummaal (Vol.4 Pg.263)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ جب حضورؐ کے زمانے میں نماز کا وقت آتا تو ایک آدمی راستے میں تیز تیز چلتا ہوا جاتا اور اعلان کرتا الصلوٰۃ الصلوٰۃ (نماز، نماز)۔ یہ کام لوگوں کو مشکل لگا تو انھوں نے عرض کیا اگر ہم ایک گھنٹہ بنا لیں۔ آگے باقی حدیث ذکر کی۔",""],[" (3)","s"]]]],"f":[["(3)","Abush Sheikh, as quoted in Kanzul Ummaal (Vol.4 Pg.265)."]]},{"b":[["n",[["حضرت نافع بن جبیرؒ، حضرت عروہؒ، حضرت زید بن اسلمؒ","b"],[" اور ",""],["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ حضورؐ کے زمانے میں اذان کا حکم ملنے سے پہلے حضورؐ کا ایک اعلانچی یہ اعلان کرتا الصلوٰۃ جامعۃ (نماز کا وقت ہو گیا ہے، سب جمع ہو جائیں)۔ جب قبلہ (بیت المقدس سے) کعبہ کی طرف تبدیل ہوا تو اذان کا حکم آ گیا۔ اس کی صورت یہ ہوئی کہ حضورؐ کو نماز کے وقت کی اطلاع دینے کا بہت فکر تھا، نماز کے لیے لوگوں کو جمع کرنے کے لیے صحابہؓ نے بہت سی چیزوں کا ذکر کیا، کسی نے بگل کا نام لیا اور کسی نے گھنٹے کا۔ آگے باقی حدیث ذکر کی اور اس کے آخر میں یہ ہے کہ پھر اذان کا حکم مل گیا اور الصلوٰۃ جامعۃ کا اعلان اس مقصد کے لیے رہ گیا کہ لوگوں کو جمع کر کے انہیں کسی خاص واقعہ، کسی فتح وغیرہ کی اطلاع کر دی جاتی یا انہیں کوئی حکم بتا دیا جاتا اور الصلوٰۃ جامعۃ کے ذریعہ اس مقصد کے لیے جمع کرنے کے لیے اعلان کیا جاتا چاہے وہ وقت نماز کا نہ ہوتا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.1 Pg.246)."]]},{"b":[["n",[["حضرت سعد قرظؓ","b"],[" فرماتے ہیں کہ جس وقت بھی حضورؐ قباء تشریف لاتے تو حضرت بلالؓ اذان دیتے تا کہ لوگوں کو پتہ چل جائے کہ حضورؐ تشریف لے آئے ہیں اور لوگ حضورؐ کے پاس جمع ہو جائیں۔ چنانچہ ایک دن حضورؐ تشریف لائے، حضرت بلالؓ آپؐ کے ساتھ نہیں تھے تو حبشی لوگ ایک دوسرے کو دیکھنے لگے۔ میں نے ایک درخت پر چڑھ کر اذان دی۔ حضورؐ نے مجھ سے پوچھا اے سعد! تم نے ایسا کیوں کیا؟ میں نے عرض کیا میرے ماں باپ آپؐ پر قربان ہوں، میں نے دیکھا کہ آپؐ کے ساتھ تھوڑے سے لوگ ہیں اور حضرت بلالؓ ساتھ نہیں ہیں اور میں نے دیکھا کہ یہ حبشی لوگ ایک دوسرے کو دیکھ رہے ہیں اور پھر آپؐ کو بھی دیکھ رہے ہیں، اس لیے مجھے ان کی طرف سے آپؐ پر حملہ کا خطرہ ہوا، اس لیے میں نے اذان دی۔ حضورؐ نے فرمایا تم نے ٹھیک کیا، جب تم میرے ساتھ بلالؓ کو نہ دیکھا کرو تو اذان دے دیا کرو۔ چنانچہ حضرت سعدؓ نے حضورؐ کی زندگی میں تین مرتبہ اذان دی۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.1 Pg.336) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوالوقاصؓ","b"],[" فرماتے ہیں کہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" کے ہاں اذان دینے والوں کا (اجر و ثواب میں سے) حصہ جہاد کرنے والوں کے حصے جیسا ہوگا اور موذن اذان اور اقامت کے درمیان اس شہید کی طرح ہوتا ہے جو ",""],["ٱللَّٰه","a"],[" کے راستے میں اپنے خون میں لت پت ہو۔ ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں اگر میں موذن ہوتا تو حج، عمرہ اور جہاد نہ کرتا۔ ",""],["حضرت عمر بن خطابؓ","b"],[" فرماتے ہیں اگر میں موذن ہوتا تو میرا (دینی) کام پورا ہو جاتا اور میں رات کی عبادت کے لیے نہ اٹھنے کی اور دن کو روزے نہ رکھنے کی پرواہ نہ کرتا۔ میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ اے ",""],["ٱللَّٰه","a"],["! اذان دینے والوں کی مغفرت فرما۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے ہمیں اس حال پر پہنچا دیا کہ ہم تو اب اذان کے لیے ایک دوسرے سے تلواروں سے لڑیں گے۔ حضورؐ نے فرمایا ہرگز نہیں اے عمر! بلکہ عنقریب ایسا زمانہ آئے گا کہ لوگ اذان کمزوروں کے لیے چھوڑ دیں گے، حالانکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے موذنوں کے گوشت کو جہنم کی آگ پر حرام کر دیا ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ یہ قرآن کی آیت ہے:",""]]],["q",[["وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ  (سورۃ حم السجدہ: ۳۳)","a"]]],["p",[["ترجمہ: \"اور اس سے بہتر کس کی بات ہو سکتی ہے جو (لوگوں کو) ",""],["ٱللَّٰه","a"],[" کی طرف بلائے اور (خود بھی) نیک عمل کرے اور کہے کہ میں فرمانبرداروں میں سے ہوں۔\" اور اس سے مراد موذن ہے، جب وہ حی علی الصلوٰۃ کہتا ہے تو اس نے ",""],["ٱللَّٰه","a"],[" کی طرف بلایا اور جب نماز پڑھتا ہے تو اس نے خود نیک عمل کیا اور جب وہ اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہتا ہے تو وہ فرمانبردار مسلمانوں میں شمار ہوتا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi in his Shu'abul Imaan, as quoted in Kanzul Ummaal (Vol.4 Pg.265). Abush Sheikh has reported similar narrations from Rasaafi in his Kitaabul Adhaan, as quoted in Kanzul Ummaal (Vol.4 Pg.266)."]]},{"b":[["n",[["حضرت ابومعشرؒ","b"],[" کہتے ہیں کہ مجھے یہ بات پہنچی ہے کہ حضرت عمر بن خطابؓ نے فرمایا اگر میں موذن ہوتا تو میں فرض حج تو ضرور ادا کرتا، باقی نفلی حج اور عمرہ نہ کرنے کی کوئی پرواہ نہ کرتا اور اگر فرشتے آسمان سے انسانی شکل میں اتر کر آتے تو اذان دینے میں کوئی ان سے آگے نہ نکل سکتا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibnuz Zanjway, as quoted in Kanzul Ummaal (Vol.4 Pg.265)."]]},{"b":[["n",[["حضرت قیس بن ابی حازمؒ","b"],[" کہتے ہیں ہم لوگ حضرت عمر بن خطابؓ کے پاس گئے تو انھوں نے فرمایا تمہارے موذن کون لوگ ہیں؟ ہم نے کہا ہمارے غلام اور آزاد کردہ غلام۔ تو فرمایا یہ تو تمہارا بہت بڑا نقص ہے، اگر میرے بس میں ہوتا تو خلیفہ نہ بنتا بلکہ موذن بنتا۔",""],[" (8)","s"]]]],"f":[["(8)","Abdur Razzaaq, Ibn Abi Shaybah and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.265)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ مجھے اس بات پر بہت افسوس ہے کہ میں نے حضورؐ سے حسنؓ و حسینؓ کے لیے اذان کیوں نہیں مانگ لی، اگر میں مانگتا تو حضورؐ دونوں کو موذن بنا دیتے۔",""],[" (9)","s"]]]],"f":[["(9)","Tabraani. Haythami (Vol.1 Pg.326) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ مجھے یہ پسند نہیں ہے کہ تمہارے موذن نابینا لوگ ہوں (کہ وہ طہارت کا اور نماز کے صحیح وقت کا خیال نہیں رکھ سکیں گے) یا قاری لوگ ہوں (کہ ان کے پڑھانے اور تعلیم کا حرج ہوگا)۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.2)."]]},{"b":[["n",[["حضرت یحییٰ بکاءؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت ابن عمرؓ سے کہا کہ میں آپ سے ",""],["ٱللَّٰه","a"],[" کے لیے محبت کرتا ہوں۔ حضرت ابن عمرؓ نے فرمایا لیکن میں تو تم سے ",""],["ٱللَّٰه","a"],[" کے لیے بغض رکھتا ہوں۔ اس آدمی نے پوچھا کیوں؟ حضرت ابن عمرؓ نے فرمایا کیونکہ تم اذان میں گانے کی آواز بناتے ہو اور پھر اذان پر اجرت بھی لیتے ہو۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani. Haythami (Vol.2 Pg.3) has commented on the chain of narrators."]]},{"b":[["n",[["نبی کریمؐ نے ",""],["حضرت خالد بن سعید بن عاصؓ","b"],[" کو یمن بھیجا اور فرمایا اگر تم کسی بستی کے پاس سے گزرو اور تمہیں وہاں سے اذان کی آواز سنائی نہ دے تو (حملہ کر کے) ان لوگوں کو قیدی بنا لینا۔ چنانچہ قبیلہ بنو زبید کے پاس سے ان کا گزر ہوا تو انھوں نے وہاں سے اذان کی آواز نہ سنی، اس پر انھوں نے اس قبیلہ کو قیدی بنا لیا۔ پھر حضرت عمرو بن معد یکربؓ حضرت خالد بن سعیدؓ کے پاس آئے اور انھوں نے ان سے اس قبیلہ کے بارے میں بات کی تو حضرت خالدؓ نے وہ قیدی ان کو ہبہ کر دیے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.2 Pg.298)."]]},{"b":[["n",[["حضرت طلحہ بن عبد","b"],["ٱللَّٰه","a"],[" بن عبدالرحمن بن ابی بکرؒ","b"],[" کہتے ہیں کہ حضرت ابوبکرؓ جب اپنے امیروں کو مرتدین کے لیے بھیج رہے تھے تو ان کو یہ حکم دے رہے تھے کہ جب تم کسی علاقے کا گھیراؤ کرو تو اگر تمہیں وہاں اذان سنائی دے تو (لڑائی سے) ہاتھ روک لو اور ان سے پوچھ لو کہ تمہیں ہماری کن باتوں پر اعتراض ہے؟ اور اگر اذان سنائی نہ دے تو ان پر چاروں طرف سے چھاپہ مارو اور انہیں قتل کرو اور (ان کی کھیتیاں) جلاؤ اور انہیں خوب اچھی طرح قتل کرو اور زخمی کرو اور تمہارے نبیؐ کے انتقال کی وجہ سے تم میں کسی قسم کی کمزوری نظر نہ آئے۔",""],[" (13)","s"]]]],"f":[["(13)","Bayhaqi."]]},{"b":[["n",[["حضرت زہریؒ","b"],[" کہتے ہیں کہ جب حضرت ابوبکر صدیقؓ نے مرتدین سے لڑنے کے لیے صحابہؓ کو بھیجا تو ان سے فرمایا رات کو شب خون مارو لیکن جہاں اذان سنو وہاں حملہ کرنے سے رک جاؤ کیونکہ اذان ایمانی شعار ہے۔",""],[" (14)","s"]]]],"f":[["(14)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.3 Pg.141)."]]}]},"29":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ جب مسجد میں نماز کھڑی ہوتی تو حضورؐ دیکھتے اگر لوگ تھوڑے ہوتے تو آپؐ بیٹھ جاتے اور نماز نہ پڑھاتے اور جب دیکھتے کہ لوگ زیادہ جمع ہو گئے ہیں تو نماز پڑھا دیتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood, as quoted in Kanzul Ummaal (Vol.4 Pg.246)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی اوفیؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ جب تک جوتوں کی آہٹ سنتے اس وقت تک انتظار فرماتے رہتے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.247)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں کہ حضورؐ نے ایک مرتبہ ایک لشکر تیار کیا، اس میں آدھی رات ہو گئی۔ پھر آپؐ نماز کے لیے باہر تشریف لائے اور فرمایا اور لوگ تو نماز پڑھ کر گھروں کو واپس جا چکے ہیں لیکن تم نماز کا انتظار کر رہے ہو، غور سے سنو! جب تک تم نماز کا انتظار کرو گے اس وقت تک نماز ہی میں شمار ہو گے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah and Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.193)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ نے مغرب کی نماز پڑھائی، اس کے بعد کچھ لوگ واپس چلے گئے اور کچھ وہاں مسجد میں ٹھہرے رہے۔ پھر حضورؐ ان کے پاس باہر تشریف لائے اور فرمایا یہ تمہارے رب نے آسمان کے دروازوں میں سے ایک دروازہ کھولا ہوا ہے اور تمہاری وجہ سے فرشتوں پر فخر فرما رہے ہیں اور کہہ رہے ہیں کہ میرے بندوں نے ایک فریضہ ادا کر لیا اور دوسرے کا انتظار کر رہے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.245). Ibn Maajah has also reported the narration from Hadhrat Abdullaah bin Umar, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.246)."]]},{"b":[["n",[["حضرت ابوامامہ ثقفیؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ ظہر کی نماز پڑھانے کے بعد حضرت معاویہؓ دوبارہ مسجد میں آئے (ہم لوگ مسجد میں بیٹھے ہوئے تھے) اور لوگوں سے کہا آپ لوگ اپنی جگہ بیٹھے رہیں، میں ابھی آتا ہوں۔ چنانچہ تھوڑی دیر بعد وہ پھر ہمارے پاس آئے، اس وقت انھوں نے چادر اوڑھ رکھی تھی۔ جب وہ عصر کی نماز پڑھا چکے تو انھوں نے کہا کیا میں آپ لوگوں کو وہ کام نہ بتاؤں جو خود حضورؐ نے کیا ہے؟ ہم نے کہا جی ضرور بتائیں۔ حضرت معاویہؓ نے کہا ایک مرتبہ صحابہ کرامؓ نے حضورؐ کے ساتھ ظہر کی نماز پڑھی پھر مسجد میں بیٹھے رہے، پھر حضورؐ ان کے پاس سے باہر تشریف لائے اور فرمایا ابھی تک تم لوگ مسجد سے گئے نہیں؟ انھوں نے عرض کیا جی نہیں۔ آپؐ نے فرمایا چونکہ تم نماز کا انتظار کر رہے ہو، اس لیے کاش تم دیکھ لیتے کہ تمہارے رب نے آسمان کا ایک دروازہ کھولا اور پھر تمہاری وجہ سے فخر فرماتے ہوئے اپنے فرشتوں کو تمہیں بیٹھے ہوئے دکھایا۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.38)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک رات حضورؐ نے عشاء کی نماز آدھی رات تک مؤخر فرمائی، پھر نماز پڑھانے کے بعد آپؐ صحابہؓ کی طرف متوجہ ہوئے اور فرمایا اور لوگ تو نماز پڑھ کر سو چکے ہیں لیکن تم جب سے نماز کا انتظار کر رہے ہو اس وقت سے تم نماز ہی میں شمار ہو رہے ہو۔",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" کی روایت میں یہ ہے کہ حضورؐ نے فرمایا تم میں سے آدمی جب تک نماز کی وجہ سے مسجد میں رکا رہتا ہے اس وقت تک وہ نماز ہی میں شمار ہوتا ہے اور فرشتے اس کے لیے یہ دعا کرتے رہتے ہیں اے ",""],["ٱللَّٰه","a"],["! اس کی مغفرت فرما! اس پر رحم فرما! اور یہ سلسلہ اس وقت تک جاری رہتا ہے جب تک وہ اپنی نماز کی جگہ سے کھڑا نہ ہو جائے یا اس کا وضو نہ ٹوٹ جائے۔",""],["(7)","s"],[" مسلم اور ابوداؤد کی ایک روایت میں یہ ہے کہ حضورؐ نے فرمایا جب تک بندہ اپنی نماز کی جگہ میں بیٹھ کر اگلی نماز کا انتظار کرتا رہتا ہے اس وقت تک وہ نماز ہی میں شمار ہوتا ہے اور فرشتے اس کے لیے یہ دعا کرتے رہتے ہیں اے ",""],["ٱللَّٰه","a"],["! اس کی مغفرت فرما! اس پر رحم فرما! اور یہ سلسلہ اس وقت تک جاری رہتا ہے جب تک وہ واپس نہ چلا جائے یا اس کا وضو ٹوٹ نہ جائے۔ کسی نے پوچھا کہ وضو ٹوٹ جانے کی کیا صورت ہے؟ آپؐ نے فرمایا اس کی ہوا آواز کے ساتھ یا بغیر آواز کے خارج ہو جائے۔",""],[" (8)","s"]]]],"f":[["(7)","Bukhaari."],["(8)","Muslim and Abu Dawood, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.245)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا کیا میں تمہیں وہ عمل نہ بتاؤں جن کی وجہ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ غلطیوں کو مٹا دیتے ہیں اور گناہوں کو ختم کر دیتے ہیں؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور بتائیں۔ آپؐ نے فرمایا ناگواریوں کے باوجود وضو پورا کرنا اور مسجدوں کی طرف قدم زیادہ اٹھانا اور ایک نماز کے بعد دوسری نماز کا انتظار کرنا، یہی ہے دشمن کی سرحد پر پہرہ دینا (یہاں دشمن سے مراد شیطان ہے)۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.247)."]]},{"b":[["n",[["حضرت داؤد بن صالحؒ","b"],[" کہتے ہیں کہ مجھ سے حضرت ابوسلمہؒ نے فرمایا اے میرے بھتیجے! کیا تم جانتے ہو کہ یہ آیت کس بارے میں نازل ہوئی ہے؟",""]]],["q",[["ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟  (سورۃ آل عمران: ۲۰۰)","a"]]],["p",[["ترجمہ: \"خود صبر کرو اور مقابلہ میں صبر کرو اور مقابلہ کے لیے مستعد رہو۔\" میں نے کہا نہیں۔ انھوں نے فرمایا کہ میں نے حضرت ابوہریرہؓ کو فرماتے ہوئے سنا ہے کہ حضورؐ کے زمانے میں دشمن کی سرحد پر پہرہ دینے کے لیے کوئی غزوہ نہیں ہوتا تھا (جس میں ہر وقت پہرہ دینے اور مقابلہ کے لیے مستعد رہنا پڑے) بلکہ دشمن سے مقابلہ کے لیے ہر وقت مستعد رہنے کی صورت یہ تھی کہ ایک نماز کے بعد (مسجد میں بیٹھ کر) دوسری نماز کا انتظار کیا جائے۔",""],[" (10)","s"]]]],"f":[["(10)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.251)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ یہ آیت:",""]]],["q",[["تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ  (سورۃ السجدہ: ۱۶)","a"]]],["p",[["اس نماز کے انتظار کے بارے میں نازل ہوئی ہے جسے عتمہ کہا جاتا ہے، یعنی نماز عشاء۔ ترجمہ: \"ان کے پہلو خوابگاہوں سے علیحدہ ہوتے ہیں۔\"",""],[" (11)","s"]]]],"f":[["(11)","Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.246)."]]}]},"30":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرو بن ام مکتومؓ","b"],[" فرماتے ہیں کہ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نابینا ہوں، میرا گھر دور ہے اور میرا ہاتھ پکڑ کر لے جانے والا تو ایک آدمی ہے لیکن اس کا مجھ سے جوڑ نہیں، وہ میری بات نہیں مانتا، تو کیا آپؐ مجھے اس بات کی اجازت دیتے ہیں کہ میں گھر میں نماز پڑھ لیا کروں؟ حضورؐ نے فرمایا کیا تم اذان کی آواز سنتے ہو؟ میں نے کہا جی ہاں۔ حضورؐ نے فرمایا پھر اجازت دینے کی گنجائش نہیں ہے۔",""],["(1)","s"],[" امام احمد کی ایک روایت میں یہ ہے کہ حضرت ابن ام مکتومؓ فرماتے ہیں کہ ایک مرتبہ حضورؐ مسجد تشریف لائے۔ آپؐ کو نمازیوں کی تعداد میں کچھ کمی نظر آئی تو آپؐ نے فرمایا میرا ارادہ ہو رہا ہے کہ میں مسجد میں نماز باجماعت کے لیے لوگوں کا کسی کو امام بناؤں اور خود مسجد سے باہر جاؤں اور جو آدمی نماز باجماعت چھوڑ کر گھر بیٹھا ہوا ملے اس کا گھر جلا دوں۔ اس پر میں نے عرض کیا میرے اور مسجد کے درمیان کھجور کے درخت ہیں اور کچھ اور قسم کے درخت ہیں اور ہر وقت مجھے لے کر آنے والا ملتا نہیں، کیا میرے لیے اس بات کی گنجائش ہے کہ میں گھر میں نماز پڑھ لیا کروں؟ حضورؐ نے پوچھا کیا تم اقامت کی آواز سنتے ہو؟ میں نے عرض کیا جی ہاں۔ آپؐ نے فرمایا تو پھر نماز کے لیے مسجد میں آیا کرو۔",""],[" (2)","s"]]]],"f":[["(1)","Ahmad, Abu Dawood, Ibn Maajah, Ibn Khuzaymah and Haakim."],["(2)","Ahmad, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.238)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ جس کو اس بات سے خوشی ہو کہ وہ کل قیامت کے دن ",""],["ٱللَّٰه","a"],[" کی بارگاہ میں مسلمان بن کر حاضر ہو، اسے چاہیے کہ وہ ان نمازوں کو اس جگہ ادا کرنے کا اہتمام کرے جہاں اذان ہوتی ہے یعنی مسجد میں۔ اس لیے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہارے نبی علیہ الصلوٰۃ والسلام کے لیے ایسی سنتیں جاری فرمائی ہیں جو سراسر ہدایت ہیں، انہیں میں سے یہ جماعت کی نمازیں بھی ہیں۔ اگر تم اپنے گھروں میں نماز پڑھنے لگو گے جیسا کہ فلاں شخص پڑھتا ہے تو تم اپنے نبی کی سنت چھوڑنے والے بن جاؤ گے اور اگر تم اپنے نبی کی سنت کو چھوڑ دو گے تو گمراہ ہو جاؤ گے۔ جو آدمی اچھی طرح وضو کرے اور پھر کسی مسجد کے ارادے سے چلے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ہر قدم پر اس کے لیے ایک نیکی لکھیں گے اور ایک درجہ بلند کریں گے اور ایک گناہ معاف کر دیں گے۔ اور ہم تو اپنا یہ حال دیکھتے تھے کہ جو شخص کھلا منافق ہوتا وہ جماعت سے رہ جاتا تھا (ورنہ حضورؐ کے زمانے میں عام منافق بھی جماعت چھوڑنے کی ہمت نہیں ہوتی تھی)، ورنہ جو شخص دو آدمیوں کے سہارے سے گھسٹتا ہوا جا سکتا تھا وہ بھی لا کر صف میں کھڑا کر دیا جاتا تھا۔ دوسری روایت میں یہ ہے کہ ہم اپنا یہ حال دیکھتے تھے کہ جو شخص کھلا منافق ہوتا یا بیمار ہوتا وہ جماعت سے رہ جاتا ورنہ جو شخص دو آدمیوں کے سہارے سے چل سکتا تھا وہ بھی نماز میں آ جاتا تھا۔ پھر حضرت ابن مسعودؓ نے فرمایا کہ حضورؐ نے ہمیں ایسی سنتیں سکھائی ہیں جو سراسر ہدایت ہیں۔ ان سنتوں میں سے ایک سنت اس مسجد میں نماز پڑھنا بھی ہے جہاں اذان ہوتی ہو۔",""],["(3)","s"],[" طیالسی کی روایت میں مزید یہ بھی ہے کہ حضرت ابن مسعودؓ نے فرمایا کہ میں دیکھ رہا ہوں کہ تم میں سے ہر ایک نے اپنے گھر میں نماز کی ایک جگہ بنا رکھی ہے جس میں وہ نماز پڑھ رہا ہے۔ اگر تم لوگ مسجدوں کو چھوڑ کر گھروں میں نماز پڑھنے لگ جاؤ گے تو تم اپنے نبی کی سنت کو چھوڑنے والے ہو جاؤ گے۔",""],[" (4)","s"]]]],"f":[["(3)","Muslim. Abu Dawood, Nasa'ee and Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.224). Abdur Razzaaq and Diyaa in his Mukhtaarah have reported a similar narration, as quoted in Kanzul Ummaal (Vol.4 Pg.181)."],["(4)","Tayaalisi (Pg.40)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں کہ جو شخص یہ چاہے کہ وہ کل ",""],["ٱللَّٰه","a"],[" کی بارگاہ میں امن کے ساتھ حاضر ہو وہ ان پانچوں نمازوں کو ایسی جگہ ادا کرے جہاں اذان ہوتی ہے، اس لیے کہ یہ کام ایسی سنتوں میں سے ہے جو سراسر ہدایت ہیں اور اسے تمہارے نبی کریمؐ نے سنت قرار دیا ہے اور کوئی یہ نہ کہے کہ میرے گھر میں نماز کی جگہ ہے میں اس میں نماز پڑھا کروں گا، کیونکہ اگر تم ایسا کرو گے تو تم اپنے نبی کی سنت چھوڑنے والے ہو جاؤ گے اور اگر تم اپنے نبی کریمؐ کی سنت کو چھوڑ دو گے تو گمراہ ہو جاؤ گے۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.235)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ ہم اگر کسی کو فجر اور عشاء میں مسجد میں نہ پاتے تو اس کے بارے میں ہمیں بدگمانی ہو جاتی۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani and Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.232). Sa'eed bin Mansoor has also reported the narration from Hadhrat Abdullaah bin Umar, as quoted in Kanzul Ummaal (Vol.4 Pg.244), as has Bazzaar, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.40)."]]},{"b":[["n",[["حضرت ابوبکر بن سلیمان بن ابی حثمہؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے ایک دن حضرت سلیمان بن ابی حثمہؓ کو فجر کی نماز میں نہ پایا، پھر حضرت عمرؓ بازار گئے۔ حضرت سلیمانؓ کا گھر مسجد اور بازار کے درمیان تھا۔ حضرت عمرؓ حضرت سلیمانؓ کی والدہ حضرت شفاءؓ کے پاس سے گزرے تو ان سے فرمایا آج صبح کی نماز میں میں نے سلیمان کو نہیں دیکھا۔ حضرت شفاءؓ نے کہا کہ وہ رات کو تہجد کی نماز پڑھتے رہے، اس لیے صبح ان کی آنکھ لگ گئی۔ حضرت عمرؓ نے فرمایا فجر کی جماعت میں شریک ہونا مجھے ساری رات عبادت کرنے سے زیادہ محبوب ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Maalik, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.235)."]]},{"b":[["n",[["حضرت ابن ابی ملیکہؓ","b"],[" فرماتے ہیں کہ قبیلہ بنو عدی بن کعب کی حضرت شفاءؓ رمضان میں حضرت عمرؓ کے پاس آئیں تو حضرت عمرؓ نے ان سے پوچھا کہ کیا بات ہے، آج میں نے صبح کی نماز میں (تمہارے خاوند) ابوحثمہ کو نہیں دیکھا؟ حضرت شفاءؓ نے کہا آج رات انھوں نے ",""],["ٱللَّٰه","a"],[" کی عبادت میں بہت زور لگایا جس کی وجہ سے وہ تھک گئے اور سستی کی وجہ سے فجر کی نماز کے لیے مسجد نہ گئے، گھر میں نماز پڑھ کر سو گئے۔ حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! ان کا صبح کی نماز میں شریک ہونا مجھے ساری رات عبادت میں زور لگانے سے زیادہ محبوب ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت شفاء بنت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتی ہیں کہ ایک دفعہ رمضان کے مہینے میں حضرت عمر بن خطابؓ میرے پاس میرے گھر آئے اور انھوں نے میرے قریب دو مردوں کو سوتے ہوئے دیکھا تو انھوں نے فرمایا ان دونوں کو کیا ہوا؟ انھوں نے ہمارے ساتھ نماز نہیں پڑھی۔ میں نے کہا اے امیر المومنین! ان دونوں نے لوگوں کے ساتھ عشاء اور تراویح کی نماز پڑھی اور صبح تک نماز پڑھتے رہے اور پھر صبح کی نماز پڑھ کر سو گئے۔ حضرت عمرؓ نے فرمایا صبح کی نماز جماعت کے ساتھ پڑھنا مجھے ساری رات عبادت کرنے سے زیادہ محبوب ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.243)."]]},{"b":[["n",[["حضرت ام دردائؓ","b"],[" فرماتی ہیں کہ ایک دن حضرت ابودرداءؓ میرے پاس آئے، وہ غصہ میں بھرے ہوئے تھے۔ میں نے پوچھا آپ کو غصہ کیوں آ رہا ہے؟ انھوں نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے حضرت محمدؐ کے دین میں سے صرف اسی عمل کا پتہ ہے کہ مسلمان اکٹھے ہو کر جماعت سے نماز پڑھتے ہیں (اور اب اس میں سستی شروع ہو گئی ہے)۔",""],[" (9)","s"]]]],"f":[["(9)","Bukhaari."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ جب حضرت ابن عمرؓ کی عشاء کی نماز باجماعت فوت ہو جاتی تو پھر وہ باقی ساری رات عبادت کرتے رہتے۔",""],["(10)","s"],[" ایک روایت میں یہ ہے کہ جب حضرت ابن عمرؓ کی کوئی نماز باجماعت فوت ہو جاتی تو اگلی نماز تک مسلسل نماز پڑھتے رہتے۔",""],[" (11)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.303)."],["(11)","Bayhaqi, as quoted in Isaabah (Vol.2 Pg.349)."]]},{"b":[["n",[["حضرت عتبہ بن ازہرؒ","b"],[" کہتے ہیں کہ بعض لوگوں کا دستور تھا کہ جب ان میں سے کسی کی شادی ہوتی تو وہ چند دن چھپا رہتا اور فجر کی نماز کے لیے باہر نہ آتا۔ تو حضورؐ کی صحبت یافتہ صحابی حضرت حارث بن حسانؓ کی شادی ہوئی، وہ فجر کی نماز کے لیے گھر سے باہر آئے تو کسی نے ان سے کہا کہ آج رات ہی تو آپ کی رخصتی ہوئی ہے اور آپ نماز باجماعت کے لیے گھر سے باہر آ رہے ہیں؟ انھوں نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! جو عورت مجھے صبح کی نماز جماعت کے ساتھ پڑھنے سے روکے وہ بری عورت ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.41)."]]}]},"31":{"lead":[],"stories":[{"b":[["n",[["حضرت براء بن عازبؓ","b"],[" فرماتے ہیں کہ حضورؐ صف کے کنارے تشریف لے جاتے اور لوگوں کے سینے اور کندھوں کو سیدھا کراتے اور فرماتے صفیں ٹیڑھی نہ بناؤ ورنہ تمہارے دل ٹیڑھے ہو جائیں گے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ پہلی صف والوں پر رحمت بھیجتے ہیں اور اس کے فرشتے ان کے لیے دعائے رحمت کرتے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.282)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں کہ حضورؐ صف میں ایک کنارے سے دوسرے کنارے تک تشریف لے جاتے اور ہاتھ لگا کر ہمارے سینوں اور کندھوں کو سیدھا کرتے اور فرماتے صفیں ٹیڑھی نہ بناؤ۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.289)."]]},{"b":[["n",[["حضرت جابر بن سمرہؓ","b"],[" فرماتے ہیں کہ حضورؐ ایک دن ہمارے پاس باہر تشریف لائے اور فرمایا کیا تم لوگ ایسے صفیں نہیں بناتے جیسے فرشتے اپنے رب کے پاس صفیں بناتے ہیں؟ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! فرشتے اپنے رب کے پاس صفیں کیسے بناتے ہیں؟ آپؐ نے فرمایا کہ وہ پہلی صفوں کو پورا کرتے ہیں (پھر دوسری صفیں بناتے ہیں) اور صفوں میں مل مل کر کھڑے ہوتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Muslim, Abu Dawood, Nasa'ee and Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.283)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ ایک دن ہم نے حضورؐ کے ساتھ نماز پڑھی پھر آپؐ نے ہمیں اشارے سے بیٹھنے کو فرمایا تو ہم بیٹھ گئے۔ پھر آپؐ نے فرمایا تم لوگ صفیں ایسے کیوں نہیں بناتے جیسے فرشتے بناتے ہیں۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Dawood and Ibn Maajah, as quoted in Kanzul Ummaal (Vol.4 Pg.255)."]]},{"b":[["n",[["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں کہ حضورؐ ہماری صفوں کو ایسا سیدھا کرتے تھے کہ گویا ان کے ذریعے تیر سیدھے کیے جائیں گے۔ کرتے کرتے آپؐ کو اندازہ ہوا کہ ہم صفیں سیدھی کرنے کی بات اچھی طرح سمجھ گئے ہیں (اور ہم خود ہی صفیں سیدھی بنانے لگ گئے ہیں) تو آپؐ نے صفیں سیدھی کرانا چھوڑ دیں۔ پھر ایک دن آپؐ باہر تشریف لائے اور نماز پڑھانے کے لیے کھڑے ہو گئے اور آپؐ تکبیر کہنے ہی والے تھے کہ آپؐ نے دیکھا کہ ایک آدمی کا سینہ صف سے باہر نکلا ہوا ہے تو آپؐ نے فرمایا اے ",""],["ٱللَّٰه","a"],[" کے بندو! اپنی صفیں سیدھی کرو ورنہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہارے چہرے بدل دیں گے (یا تم میں آپس کی مخالفت پیدا کر دیں گے)۔",""],["(5)","s"],[" ایک روایت میں یہ ہے کہ حضرت نعمانؓ فرماتے ہیں کہ اس کے بعد میں نے دیکھا کہ وہ آدمی اپنا کندھا اپنے ساتھی کے کندھے کے ساتھ اور اپنا گھٹنا اس کے گھٹنے کے ساتھ اور اپنا ٹخنہ اس کے ٹخنے کے ساتھ ملا رہا ہے۔",""],[" (6)","s"]]]],"f":[["(5)","Maalik, Muslim, Abu Dawood, Tirmidhi, Ibn Maajah and Nasa'ee."],["(6)","Abu Dawood, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.289)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ صفیں سیدھی کرنے کا حکم دیتے (اور اس کے لیے کچھ آدمی بھیجتے جو صفیں سیدھی کراتے) جب وہ لوگ واپس آ کر بتاتے کہ صفیں سیدھی ہو گئی ہیں تو پھر حضرت عمرؓ تکبیر کہتے۔",""],["(7)","s"],[" ",""],["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ صفیں سیدھی کرنے کا حکم دیتے اور فرماتے اے فلانے! آگے بڑھ جا، اے فلانے! ذرا آگے ہو جا۔ اور غالباً یہ بھی فرماتے تھے کہ کچھ لوگ پیچھے ہٹتے رہیں گے، یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں پیچھے کر دیں گے۔",""],["(8)","s"],[" ",""],["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں کہ میں نے حضرت عمرؓ کو دیکھا کہ وہ جب نماز پڑھانے کے لیے آگے بڑھتے تو لوگوں کے کندھے اور پاؤں دیکھا کرتے۔",""],[" (9)","s"]]]],"f":[["(7)","Maalik, Abdur Razzaaq and Bayhaqi."],["(8)","Abdur Razzaaq."],["(9)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.254-255)."]]},{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں کہ جب نماز کھڑی ہونے لگتی تو حضرت عمر بن خطابؓ فرماتے سیدھے ہو جاؤ، اے فلانے! آگے ہو جا، اے فلانے! پیچھے ہو جا! تم لوگ اپنی صفیں سیدھی کرو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ چاہتے ہیں کہ تم لوگ صفیں بنانے میں فرشتوں والا طریقہ اختیار کرو، پھر یہ آیت پڑھتے:",""]]],["q",[["وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ ۝ وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ  (سورۃ الصافات: ۱۶۵-۱۶۶)","a"]]],["p",[["ترجمہ: \"اور (",""],["ٱللَّٰه","a"],[" کے حضور میں حکم سننے کے وقت یا عبادت کے وقت) ہم صف بستہ کھڑے ہوتے ہیں اور ہم (",""],["ٱللَّٰه","a"],[" کی) پاکی بیان کرنے میں بھی لگے رہتے ہیں۔\"",""],[" (10)","s"]]]],"f":[["(10)","Abd bin Humayd, Ibn Jareer and Ibn Abi Haatim, as quoted in Kanzul Ummaal (Vol.4 Pg.255)."]]},{"b":[["n",[["حضرت مالکؒ","b"],[" کہتے ہیں کہ میں حضرت عثمان بن عفانؓ کے ساتھ تھا اور ان سے بات کر رہا تھا کہ وہ میرے لیے کچھ وظیفہ مقرر کر دیں کہ اتنے میں نماز کی اقامت ہو گئی۔ میں ان سے بات کرتا رہا اور وہ اپنی جوتیوں سے کنکریاں برابر کرتے رہے یہاں تک کہ وہ لوگ آ گئے جن کے ذمہ حضرت عثمانؓ نے صفیں سیدھی کرانا لگایا ہوا تھا اور انھوں نے بتایا کہ صفیں سیدھی ہو گئیں تو حضرت عثمانؓ نے مجھ سے فرمایا تم بھی صف میں سیدھے کھڑے ہو جاؤ۔ اس کے بعد حضرت عثمانؓ نے تکبیر کہی۔",""],[" (11)","s"]]]],"f":[["(11)","Abdur Razzaaq and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.255)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں سیدھے ہو جاؤ تمہارے دل سیدھے ہو جائیں گے اور مل کر کھڑے ہو تو تم پر رحم کیا جائے گا۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.255)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ ہم نے اپنا حال تو یہ دیکھا تھا کہ جب تک صفیں مکمل نہ ہو جاتیں نماز کھڑی نہ ہوتی۔",""],[" (13)","s"]]]],"f":[["(13)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.90)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ان لوگوں پر رحمت بھیجتے ہیں جو صفوں میں نماز کی پہلی صف کی طرف آگے بڑھتے ہیں اور اس کے فرشتے ان کے لیے دعائے رحمت کرتے ہیں۔",""],[" (14)","s"]]]],"f":[["(14)","Tabraani. Haythami (Vol.2 Pg.92) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبدالعزیز بن رفیعؒ","b"],[" کہتے ہیں حضرت ابن زبیرؓ کے زمانہ خلافت میں مکہ میں مقام ابراہیم کے پاس حضرت عامر بن مسعود قرشیؓ نے پہلی صف میں مجھ سے آگے بڑھنے کی کوشش کی تو میں نے ان سے پوچھا کیا یہ کہا جاتا تھا کہ پہلی صف میں خیر ہے؟ انھوں نے فرمایا ہاں ",""],["ٱللَّٰه","a"],[" کی قسم! حضورؐ نے فرمایا اگر لوگوں کو صف اول کے اجر و ثواب کا پتہ چل جائے تو قرعہ ہی سے وہ صف اول میں کھڑے ہو سکیں۔",""],[" (15)","s"]]]],"f":[["(15)","Tabraani. Haythami (Vol.2 Pg.92) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں تم لوگ پہلی صف کو لازم پکڑو اور پہلی صف میں بھی دائیں طرف کو لازم پکڑو اور ستونوں کے درمیان صف بنانے سے بچو (کیونکہ وہاں صف کی جگہ نہیں ہوتی)۔",""],[" (16)","s"]]]],"f":[["(16)","Tabraani. Haythami (Vol.2 Pg.92) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت قیس بن عبادؒ","b"],[" کہتے ہیں کہ میں ایک دفعہ مدینہ منورہ گیا۔ جب نماز کھڑی ہوئی تو میں آگے بڑھ کر پہلی صف میں کھڑا ہو گیا۔ پھر حضرت عمر بن خطابؓ باہر تشریف لائے اور صفوں کو چیرتے ہوئے آگے بڑھے، ان کے ساتھ ایک آدمی بھی آیا تھا جس کا رنگ گندمی اور داڑھی ہلکی تھی۔ اس نے لوگوں کے چہرے پر ایک نظر ڈالی اور جب اس نے مجھے دیکھا تو مجھے ہٹا دیا اور میری جگہ خود کھڑا ہو گیا۔ یہ بات مجھ پر بہت گراں گزری۔ نماز سے فارغ ہو کر وہ میری طرف متوجہ ہوئے اور کہا تم میرے اس رویے کا برا نہ مناؤ اور اس کا غم نہ کرو، کیا یہ بات تم پر گراں گزری ہے؟ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ پہلی صف میں صرف مہاجر اور انصار ہی کھڑے ہوں۔ میں نے پوچھا کہ یہ صاحب کون ہیں؟ لوگوں نے بتایا کہ یہ حضرت ابی بن کعبؓ ہیں۔",""],[" (17)","s"]]]],"f":[["(17)","Haakim in his Mustadrak (Vol.3 Pg.303), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت قیسؒ","b"],[" کہتے ہیں کہ ایک دن میں مدینہ منورہ کی مسجد نبوی میں اگلی صف میں نماز پڑھ رہا تھا کہ اتنے میں ایک آدمی میرے پیچھے سے آیا اور اس نے مجھے زور سے کھینچ کر پیچھے کر دیا اور خود میری جگہ کھڑا ہو گیا۔ سلام پھیر کر وہ میری طرف متوجہ ہوئے تو وہ حضرت ابی بن کعبؓ تھے، انھوں نے فرمایا اے نوجوان! ",""],["ٱللَّٰه","a"],[" تمہیں غمزدہ نہ کرے، یہ حضورؐ کی طرف سے ہمیں حکم تھا۔ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (18)","s"]]]],"f":[["(18)","Abu Nu'aym in his Hilya (Vol.1 Pg.352)."]]}]},"32":{"lead":[],"stories":[{"b":[["n",[["حضرت اسامہ بن عمیرؓ","b"],[" فرماتے ہیں کہ بعض دفعہ نماز کھڑی ہو جاتی تھی اور کوئی آدمی حضورؐ سے اپنی ضرورت کی بات کرنے لگ جاتا اور حضورؐ کے اور قبلہ کے درمیان کھڑا ہو جاتا اور کھڑے ہو کر حضورؐ سے باتیں کرتا رہتا۔ میں بعض دفعہ دیکھتا کہ حضورؐ کے زیادہ دیر کھڑے رہنے کی وجہ سے کچھ لوگ اونگھنے لگتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.234). Abdur Razzaaq and Abush Sheikh have reported a similar narration from Hadhrat Anas, as quoted in Kanzul Ummaal (Vol.4 Pg.273)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ بعض دفعہ عشاء کی نماز کھڑی ہو جاتی تو حضورؐ کسی آدمی کے ساتھ کھڑے ہو کر بات کرنے لگ جاتے (زیادہ دیر ہو جانے کی وجہ سے) بہت سے صحابہؓ سو جاتے پھر وہ نماز کے لیے اٹھتے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.273)."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" فرماتے ہیں کہ موذن جب اقامت کہہ دیتا اور لوگ چپ ہو جاتے تو اس کے بعد حضورؐ سے کوئی آدمی ضرورت کی بات کرنے لگتا۔ حضورؐ اس کی ضرورت پوری کرتے۔ اور حضرت انس بن مالکؓ نے بتایا کہ حضورؐ کی ایک چھڑی تھی جس پر آپؐ ٹیک لگا لیا کرتے۔",""],[" (3)","s"]]]],"f":[["(3)","Abush Sheikh in his Adhaan, as quoted in Kanzul Ummaal (Vol.4 Pg.234)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ بہت رحمدل تھے، جو بھی آپؐ کے پاس آتا (اور سوال کرتا اور آپؐ کے پاس کچھ نہ ہوتا) تو اس سے آپؐ وعدہ کر لیتے (کہ جب کچھ آئے گا تو تمہیں ضرور دوں گا) اور اگر کچھ پاس ہوتا تو اسی وقت اسے دے دیتے۔ ایک مرتبہ نماز کی اقامت ہو گئی، ایک دیہاتی نے آ کر آپؐ کے کپڑے کو پکڑ لیا اور کہا کہ میری تھوڑی سی ضرورت باقی رہ گئی ہے اور مجھے ڈر ہے کہ میں اسے بھول جاؤں گا۔ چنانچہ حضورؐ اس کے ساتھ کھڑے ہو گئے۔ جب اس کی ضرورت سے فارغ ہوئے تو پھر آگے بڑھ کر نماز پڑھائی۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari in his Adab (Pg.43)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں کہ بعض دفعہ نماز کھڑی ہو جاتی تھی، پھر حضرت عمرؓ کے سامنے آ کر کوئی آدمی ان سے بات شروع کر دیتا تو بعض دفعہ حضرت عمرؓ کے زیادہ کھڑے رہنے کی وجہ سے ہم میں سے کچھ آدمی بیٹھ جاتے۔",""],[" (5)","s"]]]],"f":[["(5)","Abur Rabee Zahraani, as quoted in Kanzul Ummaal (Vol.4 Pg.230)."]]},{"b":[["n",[["حضرت موسیٰ بن طلحہؒ","b"],[" کہتے ہیں کہ حضرت عثمان بن عفانؓ منبر پر تھے اور موذن نماز کے لیے اقامت کہہ رہا تھا، اس وقت میں نے سنا وہ لوگوں سے حالات اور چیزوں کے بھاؤ پوچھ رہے تھے۔ صفیں سیدھی کرنے کے عنوان میں یہ قصہ گزر چکا ہے کہ حضرت مالکؒ کہتے ہیں کہ میں حضرت عثمانؓ کے ساتھ تھا اور ان سے بات کر رہا تھا کہ اتنے میں نماز کھڑی ہو گئی۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Hibbaan, as quoted in Kanzul Ummaal (Vol.4 Pg.234). Ibn Sa'd (Vol.3 Pg.59) has reported a similar narration."]]}]},"33":{"lead":[],"stories":[{"b":[["n",[["صلح حدیبیہ اور فتح مکہ کے بارے میں ",""],["حضرت عکرمہؒ","b"],[" کی ایک لمبی حدیث ہے۔ اس میں یہ ہے کہ حضرت عباسؓ نے حضرت ابوسفیانؓ سے کہا اے ابوسفیان! مسلمان ہو جاؤ سلامتی پاؤ گے، اس پر حضرت ابوسفیانؓ مسلمان ہو گئے پھر حضرت عباسؓ انہیں اپنی قیام گاہ پر لے گئے۔ جب صبح ہوئی تو لوگ وضو کے لیے بھاگنے دوڑنے لگے۔ حضرت ابوسفیانؓ نے یہ منظر دیکھ کر کہا اے ابوالفضل! ان لوگوں کو کیا ہوا؟ کیا انہیں کوئی حکم ملا ہے؟ حضرت عباسؓ نے کہا نہیں۔ یہ تو نماز کی تیاری کر رہے ہیں۔ حضرت عباسؓ نے انہیں حکم دیا تو انھوں نے بھی وضو کر لیا پھر حضرت عباسؓ انہیں حضورؐ کے پاس لے گئے۔ حضورؐ جب نماز شروع کرنے لگے تو آپؐ نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ اس پر لوگوں نے بھی ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر حضورؐ رکوع میں گئے تو لوگ بھی رکوع میں چلے گئے، پھر حضورؐ نے سر مبارک اٹھایا تو لوگوں نے بھی سر اٹھا لیا۔ تو حضرت ابوسفیانؓ نے کہا کہ آج جیسا دن میں نے بھی نہیں دیکھا کہ یہ مسلمان یہاں سے لے کر وہاں تک سارے حضورؐ کی جتنی اطاعت کر رہے ہیں ان سے زیادہ اطاعت نہ تو شرفاء فارس میں دیکھی اور نہ صدیوں سے حکمرانی کرنے والے رومیوں میں۔ حضرت ابوسفیانؓ نے کہا اے ابوالفضل! تمہارا بھتیجا تو بڑے ملک والا ہو گیا۔ تو حضرت عباسؓ نے ان سے کہا نہیں، یہ ملک اور بادشاہت نہیں بلکہ نبوت ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.5 Pg.300)."]]},{"b":[["n",[["حضرت میمونہؓ","b"],[" فتح مکہ کا غزوہ بیان کرتی ہیں تو اس میں یہ بھی فرماتی ہیں کہ حضورؐ کھڑے ہو کر وضو کرنے لگے تو صحابہؓ وضو کے پانی پر جھپٹنے لگے اور پانی لے کر اپنے چہروں سے ملنے لگے۔ حضرت ابوسفیانؓ نے کہا اے ابوالفضل! تمہارے بھتیجے کی بادشاہت تو بڑی ہو گئی۔ حضرت عباسؓ نے کہا نہیں، یہ بادشاہت نہیں ہے بلکہ نبوت ہے، اسی وجہ سے ان لوگوں میں اتنا شوق ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.6 Pg.164) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" بیان کرتے ہیں کہ یہ رات حضرت ابوسفیانؓ نے حضرت عباسؓ کے پاس گزاری۔ صبح کو حضرت ابوسفیانؓ نے دیکھا کہ لوگ نماز کی تیاری کر رہے ہیں، استنجاء اور طہارت کے لیے کھڑے ادھر ادھر آ جا رہے ہیں تو وہ ڈر گئے (کہ مسلمان شاید حملہ کرنے لگے ہیں) اور انھوں نے حضرت عباسؓ سے پوچھا ان لوگوں کو کیا ہوا؟ حضرت عباسؓ نے کہا ان لوگوں نے اذان سن لی ہے، اس لیے نماز کی تیاری کے لیے یہ لوگ ادھر ادھر آ جا رہے ہیں۔ پھر جب نماز ہوئی اور حضرت ابوسفیانؓ نے دیکھا کہ حضورؐ کے رکوع کرنے پر تمام صحابہؓ رکوع میں چلے گئے اور حضورؐ کے سجدہ کرنے پر سب نے سجدہ کیا تو انھوں نے کہا اے عباس! حضورؐ انہیں جس بات کا حکم دیتے ہیں یہ اسے فوراً کر لیا کرتے ہیں۔ حضرت عباسؓ نے کہا جی ہاں۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اگر حضورؐ انہیں کھانا پینا چھوڑنے کا حکم دے دیں تو یہ اسے بھی پورا کر دیں گے۔",""],[" (3)","s"]]]],"f":[["(3)","Al Bidaayah wan Nihaayah (Vol.4 Pg.291)."]]},{"b":[["n",[["نبی کریمؐ کے نماز کے شوق کے باب میں ",""],["حضرت عائشہؓ","b"],[" کی حدیث گزر چکی ہے۔ اس میں یہ ہے کہ اس کے بعد حضورؐ نے حضرت ابوبکرؓ کے پاس یہ پیغام بھیجا کہ وہ لوگوں کو نماز پڑھائیں۔ حضرت ابوبکرؓ بہت نرم دل آدمی تھے، اس لیے انھوں نے کہا اے عمرؓ! آپ لوگوں کو نماز پڑھائیں۔ حضرت عمرؓ نے کہا نہیں، اس کے آپ زیادہ حقدار ہیں، چنانچہ ان دنوں حضرت ابوبکرؓ نے لوگوں کو نماز پڑھائی۔ بخاری میں حضرت عائشہؓ کی حدیث میں یہ ہے کہ حضورؐ نے فرمایا ابوبکرؓ سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔ کسی نے حضورؐ کی خدمت میں عرض کیا کہ ابوبکرؓ تو بہت رقیق القلب ہیں، جلد رو پڑتے ہیں۔ جب آپؐ کی جگہ کھڑے ہوں گے تو لوگوں کو نماز نہیں پڑھا سکیں گے۔ اس نے دوبارہ وہی بات کہی تو حضورؐ نے دوبارہ یہی جواب دیا بلکہ تیسری بار بھی یہی جواب دیا اور فرمایا تم تو حضرت یوسفؑ کی ساتھن (زلیخا) کی طرح ہو (کہ اندر سے کچھ اور اوپر سے کچھ۔ اوپر سے کہہ رہی ہو کہ ابوبکرؓ روتے بہت ہیں اور اندر دل میں یہ ہے کہ حضورؐ کی جگہ کھڑے ہونے سے لوگ بدفالی لیں گے، جیسے کہ زلیخا نے اوپر سے تو عورتوں کا اکرام کیا اور اندر سے مقصود انہیں حضرت یوسفؑ کو دکھانا تھا)۔ ابوبکرؓ سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔",""]]]],"f":[]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن زمعہؓ","b"],[" فرماتے ہیں کہ حضورؐ کی بیماری بڑھ چکی تھی، میں آپؐ کے پاس بیٹھا ہوا تھا اور مسلمان بھی تھے، حضرت بلالؓ نے حضورؐ کو نماز کی اطلاع دی۔ حضورؐ نے فرمایا کسی سے کہو کہ وہ لوگوں کو نماز پڑھا دے۔ چنانچہ میں وہاں سے باہر گیا تو دیکھا کہ لوگوں میں حضرت عمرؓ تو ہیں اور حضرت ابوبکرؓ نہیں ہیں۔ میں نے کہا اے عمر! آپ کھڑے ہوں اور لوگوں کو نماز پڑھائیں۔ چنانچہ حضرت عمرؓ کھڑے ہو گئے۔ حضرت عمرؓ کی آواز اونچی تھی۔ جب انھوں نے ",""],["ٱللَّٰه","a"],[" اکبر کہا تو حضورؐ نے ان کی آواز سن کر فرمایا ",""],["ٱللَّٰه","a"],[" اور مسلمان اس کا انکار کر رہے ہیں؟ ",""],["ٱللَّٰه","a"],[" اور مسلمان اس کا انکار کر رہے ہیں۔ حضورؐ نے حضرت ابوبکرؓ کے پاس آدمی بھیج کر بلایا۔ حضرت عمرؓ نے یہ نماز پڑھائی، اس کے بعد حضرت ابوبکرؓ آئے اور پھر انھوں نے لوگوں کو نماز پڑھانی شروع کی۔ حضرت عبد",""],["ٱللَّٰه","a"],[" بن زمعہؓ فرماتے ہیں کہ حضرت عمرؓ نے مجھ سے کہا تیرا بھلا ہو! اے ابن زمعہ! تم نے یہ کیا کیا؟ ",""],["ٱللَّٰه","a"],[" کی قسم! جب تم نے مجھے نماز پڑھانے کو کہا تو میں یہی سمجھا کہ حضورؐ نے مجھے اس کا حکم دیا ہے۔ اگر یہ بات نہ ہوتی تو میں بھی نماز نہ پڑھاتا۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! حضورؐ نے مجھے اس کا حکم نہیں دیا لیکن جب مجھے حضرت ابوبکرؓ نظر نہ آئے تو حاضرین میں آپ ہی مجھے نماز پڑھانے کے سب سے زیادہ حقدار نظر آئے۔ دوسری روایت",""],["(4)","s"],[" میں یہ ہے کہ جب نبی کریمؐ نے حضرت عمرؓ کی آواز سنی تو حضورؐ نے حجرہ سے سر مبارک باہر نکال کر فرمایا نہیں نہیں، لوگوں کو صرف (ابوبکر) ابن ابی قحافہ ہی نماز پڑھائیں۔ یہ بات آپؐ نے بہت غصہ میں فرمائی۔",""],[" (5)","s"]]],["p",[["حضرات صحابہ کرامؓ کا امر خلافت میں حضرت ابوبکرؓ کو مقدم سمجھنے کے باب میں یہ گزر چکا ہے کہ حضرت ابوعبیدہؓ نے فرمایا میں اس آدمی سے آگے نہیں بڑھ سکتا جسے حضورؐ نے (نماز میں) ہمارا امام بننے کا حکم دیا ہو اور انھوں نے ہماری امامت کی ہو",""],["(6)","s"],["، اور حضرت علیؓ اور حضرت زبیرؓ نے فرمایا ہم اچھی طرح سے سمجھتے ہیں کہ حضورؐ کے بعد لوگوں میں خلافت کے سب سے زیادہ حقدار حضرت ابوبکرؓ ہیں۔ یہ حضورؐ کے غار کے ساتھی ہیں اور (قرآن کے الفاظ کے مطابق) ثانی اثنین دو میں سے دوسرے ہیں۔ ہم ان کی شرافت اور بزرگی کو خوب پہچانتے ہیں اور حضورؐ نے اپنی زندگی میں انھیں لوگوں کو نماز پڑھانے کا حکم دیا تھا۔",""],[" (7)","s"]]]],"f":[["(4)","Ahmad and Abu Dawood, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.232). Haakim (Vol.3 Pg.641) has reported a similar narration."],["(5)","Abu Dawood, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.232)."],["(6)","Under the heading \"The Sahabah Place Hadhrat Abu Bakr Ahead for Khilaafah, Are Pleased to Select him and Condemn Anyone who desires to Divide their Unity\" and the subheading \"A Hadith of Ahmad and the statements of Hadhrat Abu Ubaydah bin Jarraah and Hadhrat Uthmaan Concerning the Khilaafah of Hadhrat Abu Bakr\"."],["(7)","Under the subheading \"Hadhrat Abu Bakr declines to Accept the post of Khalifah and the statements of Hadhrat Ali and Hadhrat Zubayr that he is most Worthy of the Position\"."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں جب حضورؐ کا انتقال ہو گیا تو انصار نے کہا ایک امیر ہم میں سے ہو اور ایک امیر تم مہاجرین میں سے ہو۔ حضرت عمرؓ انصار کے پاس گئے اور ان سے کہا کیا آپ لوگوں کو معلوم نہیں ہے کہ حضورؐ نے حضرت ابوبکرؓ کو حکم دیا تھا کہ وہ لوگوں کو نماز پڑھائیں؟ لہٰذا تم میں سے کس کا دل اس بات سے خوش ہو سکتا ہے کہ وہ آگے ہو کر حضرت ابوبکرؓ کا امام بنے؟ تمام انصار نے کہا ہم حضرت ابوبکرؓ سے آگے بڑھ کر امام بننے سے ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتے ہیں۔",""],[" (8)","s"]]]],"f":[["(8)","Nasa'ee, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.206)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ حضورؐ نے حضرت ابوبکرؓ کو حکم دیا تھا کہ وہ لوگوں کو نماز پڑھائیں اور میں وہاں موجود تھا، غائب نہیں تھا اور بیمار بھی نہیں تھا۔ چنانچہ حضورؐ نے جس آدمی کو ہمارے دین یعنی نماز کی امامت کے لیے پسند فرمایا اسی کو ہم نے اپنی دنیا کے لیے بھی پسند کر لیا۔",""],[" (9)","s"]]]],"f":[["(9)","Muntakhab Kanzul Ummaal (Vol.4 Pg.354)."]]},{"b":[["n",[["حضرت ابولیلیٰ کندیؒ","b"],[" کہتے ہیں کہ حضرت سلمانؓ بارہ تیرہ سواروں کے ساتھ آئے۔ یہ تمام سوار حضرت محمدؐ کے صحابہؓ میں سے تھے۔ جب نماز کا وقت آیا تو لوگوں نے کہا اے ابو عبد",""],["ٱللَّٰه","a"],["! (نماز پڑھانے کے لیے) آگے بڑھیں۔ حضرت سلمانؓ نے فرمایا ہم آپ لوگوں کے امام نہیں بنتے اور آپ لوگوں کی عورتوں سے نکاح نہیں کرتے کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہمیں آپ کے ذریعہ ہدایت عطا فرمائی ہے۔ چنانچہ ان لوگوں میں سے ایک آدمی آگے بڑھا اور اس نے چار رکعت نماز پڑھائی۔ جب اس نے سلام پھیرا تو حضرت سلمانؓ نے فرمایا ہمیں چار رکعت کی ضرورت نہیں تھی، ہمیں چار کی آدھی یعنی دو رکعت نماز کافی تھی۔ ہم تو سفر میں ہیں، اس لیے ہمیں رخصت پر عمل کرنے کی زیادہ ضرورت ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.189). Tabraani and Abu Ya'la have reported a similar narration. Haythami (Vol.2 Pg.156) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوقتادہؓ","b"],[" فرماتے ہیں کہ حضرت اسیدؓ کے بیٹوں کے غلام حضرت ابوسعیدؓ نے کھانا تیار کیا پھر انھوں نے حضرت ابوذرؓ، حضرت حذیفہؓ اور حضرت ابن مسعودؓ کو کھانے کے لیے بلایا۔ یہ حضرات تشریف لے آئے، اتنے میں نماز کا وقت ہو گیا تو حضرت ابوذرؓ نماز پڑھانے کے لیے آگے بڑھے تو ان سے حضرت حذیفہؓ نے کہا گھر کا مالک آپ کے پیچھے کھڑا ہے، وہ امامت کا زیادہ حقدار ہے۔ حضرت ابوذرؓ نے کہا اے ابن مسعود! کیا یہ بات اسی طرح ہے؟ انھوں نے کہا جی ہاں۔ اس پر حضرت ابوذرؓ پیچھے آ گئے۔ حضرت ابوسعیدؓ کہتے ہیں حالانکہ میں غلام تھا لیکن انھوں نے مجھے آگے کیا، آخر میں نے ان سب کی امامت کرائی۔",""],[" (11)","s"]]]],"f":[["(11)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.246)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کی زمین میں وہاں ایک مسجد تھی، اس میں نماز کھڑی ہونے لگی۔ مسجد کے امام ایک غلام تھے۔ حضرت ابن عمرؓ نماز میں شریک ہونے کے لیے اس مسجد میں داخل ہوئے تو اس غلام نے ان سے کہا آپ آگے تشریف لے چلیں اور نماز پڑھائیں۔ حضرت ابن عمرؓ نے فرمایا تم اپنی مسجد میں نماز پڑھانے کے زیادہ حقدار ہو، چنانچہ اس غلام نے نماز پڑھائی۔",""],[" (12)","s"]]]],"f":[["(12)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.4 Pg.247)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن حنظلہؓ","b"],[" فرماتے ہیں کہ ہم لوگ حضرت قیس بن سعد بن عبادہؓ کے گھر میں تھے، ہمارے ساتھ نبی کریمؐ کے چند صحابہؓ بھی تھے۔ ہم نے حضرت قیسؓ سے کہا آپ (نماز پڑھانے کے لیے) آگے بڑھیں۔ انھوں نے کہا میں ایسا کرنے کے لیے تیار نہیں ہوں۔ میں نے کہا حضورؐ نے فرمایا ہے کہ آدمی اپنی سواری کے اگلے حصہ کا اور اپنے گھر میں امام بننے کا زیادہ حقدار ہے۔ چنانچہ انھوں نے اپنے ایک غلام کو حکم دیا، اس نے آگے بڑھ کر نماز پڑھائی۔",""],[" (13)","s"]]]],"f":[["(13)","Bazzaar and Tabraani. Haythami (Vol.2 Pg.65) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علقمہؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ حضرت ابوموسیٰ اشعریؓ کو ملنے ان کے گھر گئے، وہاں نماز کا وقت آ گیا۔ حضرت ابوموسیٰؓ نے کہا اے ابو عبدالرحمن! آپ (نماز پڑھانے کے لیے) آگے بڑھیں کیونکہ آپ کی عمر بھی زیادہ ہے اور علم بھی۔ حضرت ابن مسعودؓ نے کہا نہیں، آپ آگے بڑھیں کیونکہ ہم آپ کے پاس آپ کے گھر میں اور آپ کی مسجد میں آئے ہیں، اس لیے آپ زیادہ حقدار ہیں۔ چنانچہ حضرت ابوموسیٰؓ آگے بڑھے اور انھوں نے اپنی جوتی اتاری اور نماز پڑھائی۔ جب انھوں نے سلام پھیرا تو حضرت ابن مسعودؓ نے ان سے فرمایا کہ آپ نے جوتے کیوں اتارے؟ کیا آپ (حضرت موسیٰ علیہ السلام کی طرح) مقدس وادی میں ہیں؟",""],["(14)","s"],[" اور طبرانی کی ایک روایت میں یہ ہے کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے ان سے کہا اے ابوموسیٰ! آپ جانتے ہی ہیں کہ یہ بات سنت میں سے ہے کہ گھر والا (نماز پڑھانے کے لیے) آگے بڑھے لیکن حضرت ابوموسیٰؓ نے آگے بڑھنے سے انکار کر دیا اور ان دونوں حضرات میں سے کسی ایک کے غلام نے آگے بڑھ کر نماز پڑھائی۔",""],[" (15)","s"]]]],"f":[["(14)","Ahmad. Haythami (Vol.2 Pg.66) has commented on the chain of narrators."],["(15)","Tabraani, reporting from reliable sources as confirmed by Haythami."]]},{"b":[["n",[["حضرت قیس بن زہیرؒ","b"],[" فرماتے ہیں میں حضرت حنظلہ بن ربیعؓ کے ساتھ حضرت فرات بن حیانؓ کی مسجد میں گیا، وہاں نماز کا وقت آ گیا۔ حضرت فراتؓ نے حضرت حنظلہؓ سے کہا آپ (نماز پڑھانے کے لیے) آگے بڑھیں۔ حضرت حنظلہؓ نے کہا میں آپ کے آگے کھڑا نہیں ہو سکتا کیونکہ آپ عمر میں مجھ سے بڑے ہیں اور آپ نے ہجرت بھی مجھ سے پہلے کی تھی اور پھر مسجد بھی آپ کی اپنی ہے۔ حضرت فراتؓ نے کہا میں نے حضورؐ کو آپ کے بارے میں ایک بات فرماتے ہوئے سنا تھا (اس کے سننے کے بعد) میں کبھی آپ کے آگے نہیں ہوں گا۔ حضرت حنظلہؓ نے کہا غزوہ طائف میں جس دن میں حضورؐ کی خدمت میں گیا تھا اور آپؐ نے مجھے جاسوس بنا کر بھیجا تھا کیا آپ اس دن وہاں موجود تھے؟ حضرت فراتؓ نے کہا جی ہاں۔ پھر حضرت حنظلہؓ آگے بڑھے اور لوگوں کو نماز پڑھائی، اس کے بعد حضرت فراتؓ نے کہا اے قبیلہ بنو عجل والو! میں نے ان کو (امامت کے لیے) اس لیے آگے بڑھایا کیونکہ حضورؐ نے غزوہ طائف کے دن ان کو جاسوس بنا کر طائف بھیجا تھا۔ واپس آ کر انھوں نے حضورؐ کو حالات بتائے تھے۔ حضورؐ نے فرمایا تھا کہ تم سچ کہتے ہو، اب پڑاؤ پر واپس چلے جاؤ کیونکہ آج رات تم جاگتے رہے ہو۔ جب حضرت حنظلہؓ وہاں سے چلے تو حضورؐ نے ہم سے فرمایا ان کی اور ان جیسے لوگوں کی اقتداء کیا کرو۔",""],[" (16)","s"]]]],"f":[["(16)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.65). Abu Ya'la, Baghawi and Ibn Asaakir have reported a similar narration, as quoted in Kanzul Ummaal (Vol.7 Pg.28)."]]},{"b":[["n",[["حضرت عبدالرحمن بن ابی لیلیٰؒ","b"],[" فرماتے ہیں میں حضرت عمر بن خطابؓ کے ساتھ مکہ مکرمہ گیا تو امیر مکہ حضرت نافع بن علقمہؓ نے باہر آ کر ہمارا استقبال کیا۔ حضرت عمرؓ نے پوچھا کہ آپ اپنے پیچھے مکہ والوں کا امیر کس کو بنا کر آئے ہیں؟ حضرت نافعؒ نے کہا حضرت عبدالرحمن بن ابزیؓ کو۔ حضرت عمرؓ نے کہا آپ نے تو مکہ میں ایک غلام کو ایسے لوگوں کا امیر بنا دیا ہے جو قریش میں سے ہیں اور حضورؐ کے صحابی ہیں۔ حضرت نافعؒ نے کہا جی ہاں، میں نے حضرت عبدالرحمنؓ کو سب سے زیادہ اور سب سے اچھا قرآن پڑھنے والا پایا اور مکہ ایسی سرزمین ہے جہاں ساری دنیا کے لوگ آتے ہیں تو میں نے چاہا کہ لوگ (نماز میں) ایسے آدمی سے قرآن سنیں جو اچھا قرآن پڑھتا ہے۔ حضرت عمرؓ نے فرمایا تم نے بہت اچھا کیا، واقعی عبدالرحمن بن ابزیؓ ان لوگوں میں سے ہیں جن کو ",""],["ٱللَّٰه","a"],[" تعالیٰ قرآن کی وجہ سے بلند کرتے ہیں۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Ya'la, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.216)."]]},{"b":[["n",[["حضرت عبید بن عمیرؒ","b"],[" فرماتے ہیں حج کے موسم میں مکہ کے پاس ایک چشمہ پر ایک جماعت جمع ہو گئی، جب نماز کا وقت آیا تو ابوالسائب کے خاندان کا ایک آدمی نماز پڑھانے کے لیے آگے بڑھا۔ اس کی زبان فصیح اور صاف نہیں تھی تو حضرت مسور بن مخرمہؓ نے اسے پیچھے کر دیا اور دوسرے آدمی کو آگے کر دیا۔ یہ بات حضرت عمر بن خطابؓ تک پہنچ گئی۔ وہاں تو حضرت عمرؓ نے انھیں کچھ نہ کہا، جب مدینہ منورہ پہنچے تو حضرت عمرؓ نے حضرت مسورؓ سے باز پرس کی۔ حضرت مسورؓ نے کہا اے امیر المومنین! آپ ذرا مجھے مہلت دیں۔ بات یہ ہے کہ اس کی زبان فصیح اور صاف نہیں تھی اور موسم حج کا تھا تو مجھے یہ خطرہ ہوا کہ حجاج کرام اس کی قراءت سن کر اسے ہی اختیار کر لیں گے۔ حضرت عمرؓ نے فرمایا پھر تم نے ٹھیک کیا۔",""],[" (18)","s"]]]],"f":[["(18)","Abdur Razzaaq and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.246)."]]},{"b":[["n",[["حضرت طلحہ بن عبید","b"],["ٱللَّٰه","a"],["ؓ","b"],[" نے کچھ لوگوں کو نماز پڑھائی اور نماز کے بعد ان سے کہا میں امامت کے لیے آگے بڑھنے سے پہلے آپ سے پوچھنا بھول گیا، کیا آپ میرے نماز پڑھانے پر راضی ہیں؟ ان لوگوں نے کہا جی ہاں اور اے حضورؐ کے خاص صحابی! آپ کے نماز پڑھانے کو کون ناپسند کر سکتا ہے؟ حضرت طلحہؓ نے فرمایا میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو لوگوں کو نماز پڑھائے اور لوگ اس کے نماز پڑھانے پر راضی نہ ہوں تو اس کی نماز کانوں سے بھی اوپر نہیں جاتی، یعنی ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے قبول نہیں فرماتے۔",""],[" (19)","s"]]]],"f":[["(19)","Tabraani. Haythami (Vol.2 Pg.68) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" بعض دفعہ حضرت عمر بن عبدالعزیزؒ کے پیچھے نماز نہ پڑھا کرتے تھے (کیونکہ شروع میں یہ بھی بنو امیہ کے خلفاء کی طرح بعض دفعہ نماز کو اتنی دیر سے پڑھتے تھے کہ نماز کا وقت ختم ہو جاتا تھا، بعد میں جب یہ خود خلیفہ بنے تو پھر صحیح وقت پر پڑھنے لگ گئے تھے) تو حضرت عمرؒ نے ان سے پوچھا کہ آپ ایسا کیوں کرتے ہیں؟ حضرت انسؓ نے فرمایا میں نے حضورؐ کو نماز پڑھتے ہوئے دیکھا ہے، جب تم ان جیسی نماز پڑھتے ہو تو میں تمہارے ساتھ نماز پڑھتا ہوں اور جب تم ان جیسی نماز نہیں پڑھتے ہو تو میں اپنی نماز پڑھ کر گھر چلا جاتا ہوں۔",""],[" (20)","s"],[" (21)","s"]]]],"f":[["(20)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.68)."],["(21)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.68)."]]},{"b":[["n",[["حضرت ابوایوبؓ","b"],[" بعض دفعہ مروان بن حکم کے ساتھ نماز نہیں پڑھتے تھے تو ان سے مروان نے پوچھا کہ آپ ایسا کیوں کرتے ہیں؟ حضرت ابوایوبؓ نے فرمایا میں نے نبی کریمؐ کو نماز پڑھتے ہوئے دیکھا ہے، اگر تم ان جیسی نماز پڑھتے ہو تو میں تمہارے ساتھ پڑھتا ہوں اور اگر تم ان جیسی نہیں پڑھتے ہو تو میں اپنی نماز پڑھ کر گھر چلا جاتا ہوں۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوخالد بجلیؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابوہریرہؓ سے پوچھا کیا حضورؐ آپ لوگوں کو اسی طرح نماز پڑھایا کرتے تھے؟ حضرت ابوہریرہؓ نے فرمایا کیا تمہیں میری نماز میں کوئی اشکال ہے؟ میں نے کہا میں اسی کے بارے میں پوچھنا چاہتا ہوں۔ حضرت ابوہریرہؓ نے کہا ہاں، حضورؐ مختصر نماز پڑھاتے تھے اور حضورؐ کا قیام اتنی دیر ہوتا تھا جتنی دیر میں موذن مینار سے اتر کر صف میں پہنچ جائے۔ ایک روایت میں یہ ہے کہ حضرت ابوخالدؒ کہتے ہیں میں نے حضرت ابوہریرہؓ کو مختصر نماز پڑھاتے ہوئے دیکھا۔",""],[" (22)","s"]]]],"f":[["(22)","Ahmad and Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.71)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے ساتھ (اتنی مختصر) نماز پڑھا کرتے تھے کہ آج تم میں سے کوئی اتنی مختصر نماز پڑھا دے تو تم اسے بہت بڑا عیب سمجھو۔",""],[" (23)","s"]]]],"f":[["(23)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.71)."]]},{"b":[["n",[["حضرت عدی بن حاتمؓ","b"],[" ایک مجلس میں تشریف لے گئے، اتنے میں نماز کھڑی ہو گئی، ان لوگوں کے امام نے آگے بڑھ کر نماز پڑھائی۔ وہ امام صاحب نماز میں کافی دیر بیٹھے رہے۔ وہ جب نماز سے فارغ ہوئے تو حضرت عدیؓ نے فرمایا تم میں سے جو ہمارا امام بنے اسے چاہیے کہ وہ رکوع سجدہ تو پورا کرے (لیکن قیام اور قعدہ کو لمبا نہ کرے) کیونکہ اس کے پیچھے چھوٹے، بڑے، بیمار، مسافر اور ضرورت مند ہر طرح کے لوگ ہوتے ہیں۔ اس کے بعد جب اگلی نماز کا وقت آیا تو حضرت عدیؓ نے آگے بڑھ کر نماز پڑھائی، رکوع سجدہ پورا کیا اور باقی نماز یعنی (قیام اور قعدہ) کو مختصر کیا اور نماز سے فارغ ہو کر فرمایا ہم لوگ حضورؐ کے پیچھے اسی طرح نماز پڑھا کرتے تھے۔",""],[" (24)","s"]]]],"f":[["(24)","Tabraani and Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.73)."]]}]},"34":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضورؐ رات گزارا کرتے تھے، پھر حضرت بلالؓ اذان دے کر حضورؐ کو بلایا کرتے، پھر حضورؐ کھڑے ہو کر غسل کرتے۔ اب بھی مجھے حضورؐ کے رخسار اور بالوں پر پانی گرتا ہوا نظر آ رہا ہے۔ پھر حضورؐ باہر تشریف لے جاتے اور نماز پڑھاتے۔ میں حضورؐ کے رونے کی آواز سنا کرتی۔ آگے اور حدیث بھی ذکر کی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.89)."]]},{"b":[["n",[["حضرت عبید بن عمیرؒ","b"],[" فرماتے ہیں کہ میں نے حضرت عائشہؓ سے پوچھا کہ آپ نے حضورؐ کی سب سے زیادہ عجیب بات جو دیکھی ہو وہ ہمیں بتائیں۔ پہلے تو وہ خاموش ہو گئیں پھر فرمایا ایک رات حضورؐ نے فرمایا اے عائشہ! مجھے چھوڑو، آج رات میں اپنے رب کی عبادت کروں۔ میں نے عرض کیا ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے آپؐ کا قرب بھی پسند ہے اور جس کام سے آپؐ کو خوشی ہو وہ بھی پسند ہے۔ چنانچہ حضورؐ اٹھے اور وضو کیا پھر کھڑے ہو کر نماز پڑھنے لگے اور نماز میں روتے رہے اور اتنا روئے کہ آپؐ کی گود گیلی ہو گئی اور بیٹھ کر اتنا روئے کہ آپؐ کی داڑھی آنسوؤں سے تر ہو گئی، پھر (سجدہ میں) اتنا روئے کہ زمین تر ہو گئی۔ پھر حضرت بلالؓ حضورؐ کو نماز کی اطلاع دینے آئے، جب انہوں نے حضورؐ کو روتے ہوئے دیکھا تو عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ رو رہے ہیں حالانکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپ کے اگلے پچھلے تمام گناہ معاف کر دیے ہیں۔ حضورؐ نے فرمایا تو کیا میں شکر گزار بندہ نہ بنوں؟ آج رات مجھ پر ایسی آیت نازل ہوئی ہے کہ جو آدمی اسے پڑھے اور اس میں غور و فکر نہ کرے اس کے لیے ہلاکت ہے، وہ آیت یہ ہے:",""]]],["q",[["إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ  (سورۃ آل عمران: ۱۹۰، آخر تک)","a"]]],["p",[["ترجمہ: \"بلاشبہ آسمانوں کے اور زمین کے بنانے میں اور ایک کے بعد دیگرے رات اور دن کے آنے جانے میں دلائل ہیں اہل عقل کے لیے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.32)."]]},{"b":[["n",[["حضرت مطرفؓ","b"],[" کے والد بیان کرتے ہیں کہ میں نے حضورؐ کو نماز پڑھتے ہوئے دیکھا اور آپؐ کے سینے سے رونے کی ایسی آواز آ رہی تھی جیسے چکی کے چلنے کی ہوتی ہے۔",""],["(3)","s"],[" نسائی کی روایت میں یہ ہے کہ سینے سے رونے کی ایسی آواز آ رہی تھی جیسے ہنڈیا کے ابلنے کی ہوتی ہے۔",""],[" (4)","s"]]]],"f":[["(3)","Abu Dawood."],["(4)","Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.32)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن شداد بن الہادؒ","b"],[" کہتے ہیں کہ میں صبح کی نماز میں آخری صف میں تھا، میں نے حضرت عمرؓ کے رونے کی آواز سنی، وہ سورت یوسف پڑھ رہے تھے۔ پڑھتے پڑھتے اس آیت تک پہنچے:",""]]],["q",[["إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ  (سورۃ یوسف: ۸۶)","a"]]],["p",[["ترجمہ: \"میں تو اپنے رنج و غم کی صرف ",""],["ٱللَّٰه","a"],[" سے شکایت کرتا ہوں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Abdur Razzaaq, Sa'eed bin Mansoor, Ibn Abi Shaybah, Ibn Sa'd and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.387)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں میں نے حضرت عمرؓ کے پیچھے نماز پڑھی تو میں نے تین صف پیچھے سے ان کے رونے کی آواز سنی۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.52)."]]}]},"35":{"lead":[],"stories":[{"b":[["n",[["حضرت سہل بن سعدؓ","b"],[" فرماتے ہیں کہ حضرت ابوبکرؓ نماز میں ادھر ادھر متوجہ نہیں ہوا کرتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad in his Zuhd, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.347)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ نماز میں اس طرح کھڑے ہوتے جیسے کہ وہ لکڑی ہوں اور حضرت ابوبکرؓ بھی ایسے ہی کیا کرتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Muntakhab Kanzul Ummaal (Vol.4 Pg.360)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں یہ ہے نماز میں خشوع۔ ",""],["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ جب نماز میں کھڑے ہوتے تو ایسا معلوم ہوتا کہ جیسے وہ کوئی لکڑی ہوں (بالکل حرکت نہ کرتے) اور یہ کہا جاتا تھا کہ یہ بات نماز کے خشوع میں سے ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.335), as quoted in Isaabah (Vol.2 Pg.310)."]]},{"b":[["n",[["حضرت ابن منکدرؒ","b"],[" کہتے ہیں اگر تم حضرت ابن زبیرؓ کو نماز پڑھتے ہوئے دیکھ لو تو تم کہو گے یہ کسی درخت کی ٹہنی ہے جسے ہوا ہلا رہی ہے اور منجنیق کے پتھر ادھر ادھر گرا کرتے تھے لیکن وہ نماز میں ان پتھروں کی بالکل پرواہ نہ کرتے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.335). Tabraani has also reported the narration, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.136)."]]},{"b":[["n",[["حضرت زید بن عبد","b"],["ٱللَّٰه","a"],[" شیبانیؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابن عمرؓ کو دیکھا کہ جب وہ نماز کے لیے جاتے تو بہت ہی آہستہ چلتے، اگر کوئی چیونٹی ان کے ساتھ چلتی تو وہ اس چیونٹی سے بھی آگے نہ نکل سکتے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.4 Pg.154)."]]},{"b":[["n",[["حضرت واسع بن حبانؒ","b"],[" کہتے ہیں کہ حضرت ابن عمرؓ نماز میں یہ چاہتے تھے کہ ان کے جسم کی ہر چیز قبلہ رخ رہے یہاں تک کہ وہ اپنے انگوٹھے کو بھی قبلہ رخ رکھتے تھے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Sa'd (Vol.4 Pg.157)."]]},{"b":[["n",[["حضرت عطاءؒ","b"],[" کہتے ہیں کہ حضرت ابن زبیرؓ جب نماز پڑھا کرتے تو (بالکل حرکت نہ کرتے اور) ایسا معلوم ہوتا کہ وہ کوئی ابھری ہوئی چیز ہیں جسے زمین میں گاڑا ہوا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilya (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت اعمشؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ جب نماز پڑھتے تو ایسا لگتا کہ جیسے وہ پڑا ہوا کپڑا ہوں۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani. Haythami (Vol.2 Pg.136) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت طاؤسؒ","b"],[" کہتے ہیں میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کی طرح نماز میں قبلہ رخ رہنے میں بہت زیادہ اہتمام کرتے ہوئے کسی کو نہیں دیکھا، وہ نماز میں اپنا چہرہ، ہاتھ اور پاؤں قبلہ رخ رکھنے کا سختی سے اہتمام کرتے تھے۔",""],["(9)","s"],[" ",""],["حضرت ابوبردہؒ","b"],[" فرماتے ہیں کہ میں نے حضرت ابن عمرؓ کے پہلو میں کھڑے ہو کر نماز پڑھی۔ میں نے انہیں سجدہ میں یہ کہتے ہوئے سنا اے ",""],["ٱللَّٰه","a"],["! تو میرا سب سے زیادہ محبوب بن جا اور مجھے ہر چیز سے زیادہ اپنے سے ڈرنے والا بنا دے اور انھیں سجدہ میں یہ بھی کہتے ہوئے سنا اے میرے رب! چونکہ آپ نے مجھ پر بڑے بڑے انعامات فرمائے ہیں، اس لیے میں کبھی بھی مجرموں کی مدد نہیں کروں گا۔",""],[" (10)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.304)."],["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت ام رومانؓ","b"],[" (حضرت عائشہؓ کی والدہ) فرماتی ہیں کہ میں ایک مرتبہ نماز پڑھ رہی تھی، نماز میں ادھر ادھر جھکنے لگی۔ حضرت ابوبکرؓ نے دیکھ لیا تو مجھے اس زور سے ڈانٹا کہ میں (ڈر کی وجہ سے) نماز توڑنے کے قریب ہو گئی۔ پھر ارشاد فرمایا کہ میں نے حضورؐ سے سنا ہے کہ جب کوئی شخص نماز میں کھڑا ہو تو اپنے تمام بدن کو بالکل سکون سے رکھے، یہود کی طرح ہلے نہیں۔ بدن کے تمام اعضاء کا نماز میں بالکل سکون سے رہنا نماز کے پورا ہونے کا جزو ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Adi and Abu Nu'aym in his Hilya (Vol.9 Pg.304), as quoted in Kanzul Ummaal (Vol.4 Pg.230)."]]}]},"36":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن شقیقؒ","b"],[" کہتے ہیں کہ میں نے حضرت عائشہؓ سے حضورؐ کی سنت نمازوں کے بارے میں پوچھا تو انھوں نے فرمایا کہ حضورؐ ظہر سے پہلے میرے گھر میں چار رکعت نماز پڑھتے، پھر باہر تشریف لے جا کر لوگوں کو نماز پڑھاتے، پھر میرے گھر واپس آ کر دو رکعت نماز پڑھتے۔ آپؐ لوگوں کو مغرب کی نماز پڑھاتے پھر میرے گھر واپس آ کر دو رکعت نماز پڑھتے، پھر آپؐ لوگوں کو عشاء کی نماز پڑھاتے پھر میرے گھر واپس آ کر دو رکعت نماز پڑھتے، پھر رات کو نو رکعت نماز پڑھتے جن میں وتر کی نماز بھی شامل ہوتی اور رات کو کبھی بہت دیر تک کھڑے ہو کر نماز پڑھتے اور کبھی بہت دیر تک بیٹھ کر نماز پڑھتے۔ جب کھڑے ہو کر قراءت فرماتے تو کھڑے ہو کر ہی رکوع سجدہ فرماتے اور جب بیٹھ کر قراءت فرماتے تو بیٹھ کر ہی رکوع سجدہ فرماتے اور جب صبح صادق ہو جاتی اور فجر کا وقت ہو جاتا تو آپؐ دو رکعت نماز پڑھتے پھر باہر تشریف لے جاتے اور لوگوں کو فجر کی نماز پڑھاتے۔",""],[" (1)","s"]]]],"f":[["(1)","Muslim, as quoted in Safwatus Safwah (Vol.1 Pg.75). Abu Dawood and Tirmidhi have also reported the narration, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.110)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ نبی کریمؐ فجر کی دو سنتوں سے زیادہ اور کسی سنت کا اہتمام نہیں فرماتے تھے۔",""],["(2)","s"],[" ",""],["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ میں نے حضورؐ کو فجر سے پہلے کی دو رکعتوں کے لیے جتنی جلدی کرتے ہوئے دیکھا ہے خیر کے کسی کام میں اور مال غنیمت میں اتنی جلدی کرتے ہوئے نہیں دیکھا۔",""],[" (3)","s"]]]],"f":[["(2)","Bukhaari, Muslim and others."],["(3)","Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.361)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ نبی کریمؐ ظہر سے پہلے چار رکعت اور صبح سے پہلے دو رکعت کبھی نہیں چھوڑتے تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari."]]},{"b":[["n",[["حضرت بلالؓ","b"],[" صبح کی نماز کی اطلاع دینے کے لیے حضورؐ کے پاس حضرت عائشہؓ کے پاس آئے، حضرت عائشہؓ ان سے کچھ بات پوچھنے لگ گئیں جس میں دیر ہو گئی اور صبح کا چاندنا (اجالا) زیادہ ہو گیا تو حضرت بلالؓ نے کھڑے ہو کر حضورؐ کو خبر کی اور مسلسل خبر کرتے رہے لیکن حضورؐ فوری طور پر باہر تشریف نہ لائے بلکہ تھوڑی دیر کے بعد باہر آئے اور لوگوں کو نماز پڑھائی۔ پھر حضرت بلالؓ نے حضورؐ کو بتایا کہ حضرت عائشہؓ مجھ سے کچھ پوچھنے لگ گئی تھیں جس کی وجہ سے مجھے دیر ہو گئی تھی، پھر میں نے آپؐ کو بار بار اطلاع کی لیکن آپؐ فوراً باہر تشریف نہ لائے بلکہ کچھ دیر میں آئے، اس کی کیا وجہ ہے؟ حضورؐ نے فرمایا میں نے فجر کی دو رکعت سنت پڑھی تھیں، اس وجہ سے مجھے باہر آنے میں دیر ہو گئی۔ حضرت بلالؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! (آپؐ سنت نہ پڑھتے کیونکہ) صبح تو بہت زیادہ روشن ہو گئی تھی۔ حضورؐ نے فرمایا اگر صبح اس سے بھی زیادہ روشن ہو جاتی تو بھی میں یہ دو رکعت نماز ضرور پڑھتا اور بہت اچھے اور عمدہ طریقہ سے پڑھتا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Dawood (Vol.2 Pg.259), reporting from reliable sources as confirmed by Nawawi by Nawawi in Riyaadhus Saaliheen (Pg.416)."]]},{"b":[["n",[["حضرت قابوسؒ","b"],[" نقل کرتے ہیں کہ میرے والد نے حضرت عائشہؓ کے پاس یہ پیغام بھیجا کہ کس نماز کو پابندی سے پڑھنا حضورؐ کو زیادہ پسند تھا؟ حضرت عائشہؓ نے فرمایا ظہر سے پہلے چار رکعت نماز پڑھتے تھے اور ان میں لمبا قیام فرماتے اور رکوع سجدہ اچھی طرح کرتے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.364)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سائبؓ","b"],[" فرماتے ہیں کہ حضورؐ ظہر سے پہلے اور زوال کے بعد چار رکعت نماز پڑھتے تھے اور فرمایا کرتے تھے کہ یہ ایسی گھڑی ہے جس میں آسمان کے دروازے کھلتے ہیں، میں یہ چاہتا ہوں کہ اس گھڑی میں میرا کوئی نیک عمل اوپر چلا جائے۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad and Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.364)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ ظہر سے پہلے چار اور ظہر کے بعد دو رکعت پڑھا کرتے تھے۔ ",""],["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ نبی کریمؐ جب ظہر سے پہلے چار رکعت نماز نہ پڑھ سکتے تو انہیں ظہر کے بعد پڑھا کرتے تھے۔",""],[" (8)","s"],[" (9)","s"]]]],"f":[["(8)","Tirmidhi (Pg.57)."],["(9)","Tirmidhi (Pg.57)."]]},{"b":[["n",[["حضرت ابوایوبؓ","b"],[" فرماتے ہیں جب حضورؐ میرے مہمان بنے تو میں نے دیکھا کہ آپؐ ہمیشہ ظہر سے پہلے چار رکعت نماز پڑھا کرتے تھے کہ جب سورج ڈھل جاتا ہے تو آسمان کے دروازے کھول دیے جاتے ہیں اور ظہر تک ان میں سے کوئی دروازہ بند نہیں ہوتا، اس لیے میں چاہتا ہوں کہ اس گھڑی میں میرے لیے خیر کا کوئی عمل اوپر چلا جائے۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.364) and Kanzul Ummaal (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ حضورؐ عصر سے پہلے چار رکعت نماز پڑھتے تھے۔ چار رکعت کے درمیان بیٹھ کر التحیات پڑھتے اور اس میں (ٱلسَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ ٱللَّهِ ٱلصَّٰلِحِينَ کہہ کر) مقرب فرشتوں اور مسلمانوں اور مومنوں پر سلام بھیجتے۔",""],[" (11)","s"]]]],"f":[["(11)","Tirmidhi (Pg.58)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں نبی کریمؐ عصر سے پہلے دو رکعت نماز پڑھا کرتے تھے۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Dawood, as quoted in Riyaadhus Saaliheen (Pg.419). Abu Ya'la and Tabraani have reported similar narrations from Hadhrat Maymoona, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.221)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضورؐ مغرب کے بعد دو رکعت نماز پڑھتے تھے اور ان میں اتنی لمبی قراءت فرماتے تھے کہ مسجد والے صحابہؓ (اپنی اپنی نماز پوری کر کے) ادھر ادھر بکھر جاتے تھے۔",""],[" (13)","s"]]]],"f":[["(13)","Tabraani. Haythami (Vol.2 Pg.230) has commented on the chain of narrators."]]}]},"37":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ","b"],[" نے فجر سے پہلے کی سنتوں کے بارے میں فرمایا کہ یہ دو رکعتیں مجھے سرخ اونٹوں سے زیادہ پسند ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.201)."]]},{"b":[["n",[["حضرت عبدالرحمن بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" فرماتے ہیں کہ میں حضرت عمر بن خطابؓ کی خدمت میں حاضر ہوا۔ وہ ظہر سے پہلے نماز پڑھ رہے تھے۔ میں نے پوچھا یہ کونسی نماز ہے؟ حضرت عمرؓ نے فرمایا یہ نماز تہجد کی نماز کی طرح شمار ہوتی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عتبہؒ","b"],[" کہتے ہیں کہ میں نے ظہر سے پہلے حضرت عمرؓ کے ساتھ ان کے گھر میں چار رکعت نماز پڑھی۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت حذیفہ بن اسیدؓ","b"],[" کہتے ہیں کہ میں نے دیکھا کہ جب زوال کا وقت ہو جاتا تو حضرت علی بن ابی طالبؓ چار رکعت نماز بہت لمبی پڑھتے۔ میں نے ان سے ان رکعتوں کے بارے میں پوچھا تو فرمایا کہ میں نے حضورؐ کو یہ رکعتیں پڑھتے ہوئے دیکھا ہے۔ آگے حضرت ابوایوبؓ جیسی حدیث ذکر کی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن یزیدؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ سے سب سے زیادہ تعلق رکھنے والے ایک آدمی نے مجھے بتایا کہ جب سورج ڈھل جاتا تو حضرت ابن مسعودؓ کھڑے ہو کر چار رکعت نماز پڑھتے اور ان میں (سو سے زیادہ آیتوں والی) مئین سورتوں میں سے دو سورتیں پڑھتے۔ پھر جب موذن اذان دیتے تو پورے کپڑے پہنتے اور نماز کے لیے چلے جاتے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.2 Pg.221) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت اسود، حضرت مرہ","b"],[" اور ",""],["حضرت مسروقؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا دن کی نمازوں میں سے صرف ظہر کی نماز سے پہلے کی چار رکعتیں رات کی تہجد کے برابر ہیں اور دن کی تمام نمازوں پر ان چار رکعتوں کو ایسی فضیلت ہے جیسے نماز باجماعت کو اکیلے کی نماز پر۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.2 Pg.221) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ صحابہ کرامؓ دن کی نمازوں میں سے صرف ظہر سے پہلے کی چار رکعتوں کو رات کی تہجد کے برابر سمجھتے تھے اور یہ کہتے تھے کہ یہ چار رکعت رات کی چار رکعت کے برابر ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" ظہر سے پہلے چار رکعت نماز پڑھا کرتے تھے اور حضرت ابن عمرؓ سے بھی یہی روایت ہے۔",""],["(8)","s"],[" جب سورج ڈھل جاتا تو حضرت ابن عمرؓ مسجد میں جا کر ظہر سے پہلے بارہ رکعت نماز پڑھتے پھر بیٹھ جاتے۔",""],["(9)","s"],[" ",""],["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت ابن عمرؓ ظہر سے پہلے آٹھ رکعت اور ظہر کے بعد چار رکعت پڑھتے۔",""],[" (10)","s"]]]],"f":[["(8)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."],["(9)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."],["(10)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے تین کاموں کا حکم دیا۔ میں جب تک زندہ رہوں گا انھیں کبھی نہیں چھوڑوں گا، ان میں سے ایک کام یہ ہے کہ میں عصر سے پہلے چار رکعت پڑھا کروں، لہٰذا میں جب تک زندہ رہوں گا یہ رکعتیں ضرور پڑھا کروں گا۔",""],["(11)","s"],[" ",""],["حضرت علیؓ","b"],[" فرماتے ہیں ",""],["ٱللَّٰه","a"],[" تعالیٰ اس آدمی پر رحم فرمائے جو عصر سے پہلے چار رکعت نماز پڑھے۔",""],[" (12)","s"]]]],"f":[["(11)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.4 Pg.191)."],["(12)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.191)."]]},{"b":[["n",[["حضرت ابوفاختہؒ","b"],[" کہتے ہیں کہ حضرت علیؓ نے فرمایا مغرب اور عشاء کے درمیان والی نماز کا نام صلوٰۃ الغفلۃ ہے، پھر حضرت علیؓ نے فرمایا لیکن اب تم اس نماز کے بارے میں غفلت میں پڑ چکے ہو (کہ پڑھتے نہیں ہو)۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.192)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" نے فرمایا جو مغرب کے بعد چار رکعت نماز پڑھے وہ غزوے کے بعد غزوہ کرنے والے کی طرح شمار ہوگا۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.4 Pg.193)."]]}]},"38":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی قیسؒ","b"],[" کہتے ہیں کہ حضرت عائشہؓ نے فرمایا تہجد کی نماز نہ چھوڑنا کیونکہ حضورؐ کبھی تہجد کی نماز نہیں چھوڑا کرتے تھے اور حضورؐ جب بیمار ہوتے یا تھکے ہوئے ہوتے تو بیٹھ کر تہجد پڑھ لیتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood and Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.401)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ ۝ قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا  (سورۃ مزمل: ۱-۲)","a"]]],["p",[["ترجمہ: \"اے کپڑوں میں لپٹنے والے! رات میں (نماز میں) کھڑے رہا کرو مگر تھوڑی سی رات۔\" تو تہجد کی نماز ہم پر فرض ہو گئی اور ہم رات کو اتنی تہجد پڑھتے کہ ہمارے پاؤں سوج جاتے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرما کر رخصت عنایت فرما دی:",""]]],["q",[["عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ  (سورۃ مزمل: ۲۰، آخر تک)","a"]]],["p",[["ترجمہ: \"اس کو (یہ بھی) معلوم ہے کہ بعضے آدمی تم میں بیمار ہوں گے۔۔۔\" اس آیت کے نازل ہونے پر تہجد کی فرضیت ختم ہو گئی لیکن نفل نمازوں میں سب سے افضل ہونا باقی رہا۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar. Haythami (Vol.2 Pg.251) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت سعد بن ہشامؒ","b"],[" نے اپنی بیوی کو طلاق دے دی اور پھر مدینہ منورہ گئے تا کہ وہاں کی اپنی ساری جائیداد بیچ کر گھوڑے اور اسلحہ خرید لیں اور مرتے دم تک روم والوں سے جہاد کرتے رہیں۔ راستہ میں ان کی اپنی قوم کے کچھ لوگوں سے ملاقات ہوئی جنہوں نے انہیں بتایا کہ حضورؐ کے زمانہ میں ان کی قوم کے کچھ آدمیوں نے بھی ایسا کرنے کا ارادہ کیا تھا لیکن حضورؐ نے ان سے فرمایا تھا کیا آپ لوگ میرے طریقے پر نہیں چلتے؟ اور انہیں ایسا کرنے سے منع فرما دیا تھا۔ اس پر حضرت سعدؒ نے اپنی بیوی سے رجوع کر لیا اور ان لوگوں کو اپنے اس رجوع پر گواہ بنایا، پھر ہمارے پاس واپس آئے اور حضرت سعدؒ نے ہمیں بتایا کہ میں حضرت ابن عباسؓ کے پاس گیا تھا اور ان سے وتر کے بارے میں پوچھا تو حضرت ابن عباسؓ نے فرمایا کیا میں تمہیں ایسا آدمی نہ بتاؤں جو تمام روئے زمین والوں میں حضورؐ کے وتر کو سب سے زیادہ جاننے والا ہے؟ میں نے کہا ضرور بتائیں۔ حضرت ابن عباسؓ نے کہا حضرت عائشہؓ کے پاس جاؤ اور ان سے پوچھو اور وہ جو جواب دیں وہ واپس آ کر مجھے بھی بتانا۔ چنانچہ میں حضرت حکیم بن افلحؓ کے پاس گیا اور میں نے ان سے عرض کیا کہ وہ میرے ساتھ حضرت عائشہؓ کے پاس چلیں۔ حضرت حکیمؓ نے کہا نہیں، میں تو ان کے قریب بھی نہیں جاؤں گا کیونکہ میں نے انھیں (حضرت علیؓ اور حضرت معاویہؓ کی) ان دو جماعتوں کے بارے میں کچھ فرمانے سے منع کیا تھا لیکن وہ نہ مانیں اور اس بارے میں بہت کچھ کر گزریں۔ حضرت سعدؒ کہتے ہیں کہ میں نے حضرت حکیمؓ کو قسم دی تو وہ میرے ساتھ چل پڑے۔ چنانچہ ہم دونوں حضرت عائشہؓ کی خدمت میں حاضر ہوئے۔ حضرت عائشہؓ نے حضرت حکیمؓ کو پہچان لیا اور فرمایا کیا تم حکیم ہو؟ حضرت حکیمؓ نے کہا جی ہاں۔ حضرت عائشہؓ نے پوچھا یہ تمہارے ساتھ کون ہے؟ حضرت حکیمؓ نے کہا سعد بن ہشام ہیں۔ حضرت عائشہؓ نے پوچھا ان کے والد کونسے ہشام ہیں؟ حضرت حکیمؓ نے کہا وہ ابن عامر ہیں۔ اس پر حضرت عائشہؓ نے حضرت عامرؓ کے لیے دعائے رحمت کی اور فرمایا عامر تو بہت اچھے آدمی تھے۔ پھر میں نے کہا اے ام المومنین! حضورؐ کے اخلاق کے بارے میں آپ مجھے بتائیں۔ حضرت عائشہؓ نے فرمایا کیا تم قرآن نہیں پڑھتے ہو؟ میں نے کہا جی ہاں پڑھتا ہوں۔ حضرت عائشہؓ نے فرمایا حضورؐ کے اخلاق قرآن کے مطابق تھے۔ یہ جواب سن کر میں نے مجلس سے اٹھنے کا ارادہ کیا لیکن پھر خیال آیا کہ حضورؐ کے رات کے قیام کے بارے میں بھی پوچھ لوں تو میں نے عرض کیا اے ام المومنین! آپ مجھے حضورؐ کے رات کے قیام کے بارے میں بھی بتائیں۔ حضرت عائشہؓ نے فرمایا کیا تم سورت مزمل نہیں پڑھتے ہو؟ میں نے کہا جی ہاں پڑھتا ہوں۔ حضرت عائشہؓ نے فرمایا اس سورت کے شروع میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے رات کا قیام فرض کیا تھا۔ چنانچہ حضورؐ اور آپؐ کے صحابہؓ سال بھر مسلسل رات کو اتنا لمبا قیام کرتے رہے کہ ان کے پاؤں سوج گئے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بارہ مہینے تک اس سورت کی آخری آیت کو آسمان میں روکے رکھا، پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آخری حصہ کو نازل فرما کر رات کے قیام میں تخفیف کر دی، چنانچہ رات کا قیام پہلے فرض تھا پھر بعد میں نفل ہو گیا۔ یہ جواب سن کر میں نے اٹھنے کا ارادہ کیا لیکن پھر خیال آیا کہ حضورؐ کے وتر کے بارے میں بھی پوچھ لوں تو میں نے کہا اے ام المومنین! آپ مجھے حضورؐ کے وتر کے بارے میں بھی بتائیں۔ حضرت عائشہؓ نے فرمایا ہم حضورؐ کے لیے مسواک اور وضو کا پانی تیار کر کے رکھ دیتے تھے تو پھر رات کو جب ",""],["ٱللَّٰه","a"],[" آپؐ کو اٹھاتے تو آپؐ مسواک کر کے وضو کرتے تو پھر آٹھ رکعت پڑھتے اور ان میں صرف آٹھویں رکعت کے بعد بیٹھتے اور سلام پھیرے بغیر کھڑے ہو جاتے اور نویں رکعت پڑھتے، اس کے بعد بیٹھ کر (التحیات میں) ذکر و دعا کرتے اور پھر اتنی آواز سے سلام پھیرتے جو ہمیں سنائی دیتا، پھر سلام کے بعد بیٹھ کر دو رکعت نماز پڑھتے، اس طرح اے میرے بیٹے! حضورؐ کی گیارہ رکعت ہو جاتیں۔ پھر جب حضورؐ کی عمر ذرا زیادہ ہو گئی اور آپؐ کا جسم بھاری ہو گیا تو آپؐ سات رکعت پڑھ کر سلام پھیرتے اور پھر بیٹھ کر دو رکعت پڑھتے، اے میرے بیٹے! اس طرح یہ کل نو رکعت ہو جاتیں۔ حضورؐ جب کوئی نماز شروع فرماتے تو آپؐ کو پسند تھا کہ اسے پابندی سے پڑھیں، اس لیے اگر نیند کی زیادتی یا درد یا کسی بیماری کی وجہ سے آپؐ کا رات کا قیام رہ جاتا تو آپؐ دن میں بارہ رکعت پڑھتے۔ اور مجھے یہ معلوم نہیں ہے کہ حضورؐ نے کبھی ساری رات فجر تک قرآن پڑھا ہو یا رمضان کے علاوہ کسی سارے مہینے کے روزے رکھے ہوں۔ حضرت سعدؒ کہتے ہیں کہ میں پھر حضرت ابن عباسؓ کی خدمت میں گیا اور انہیں حضرت عائشہؓ کی ساری حدیث سنائی تو انھوں نے فرمایا کہ حضرت عائشہؓ نے ٹھیک فرمایا۔ اگر میرا ان کے ہاں آنا جانا ہوتا تو میں خود جا کر ان سے براہ راست یہ حدیث سنتا۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad and Muslim, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.435)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب سورت مزمل کا شروع کا حصہ نازل ہوا تو صحابہ کرامؓ رات کو اتنی نماز پڑھتے جتنی رمضان کے مہینے میں رات کو پڑھا کرتے تھے اور اس سورت کے شروع کے حصے کے اور آخری حصہ کے نازل ہونے میں ایک سال کا وقفہ تھا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.281)."]]},{"b":[["n",[["حضرت یحییٰ بن سعیدؒ","b"],[" کہتے ہیں کہ حضرت ابوبکرؓ رات کے شروع میں وتر پڑھ لیتے تھے اور پھر جب رات کو تہجد کے لیے اٹھتے تو دو دو رکعت نماز پڑھتے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.4 Pg.278)."]]},{"b":[["n",[["حضرت اسلمؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ جتنی دیر ",""],["ٱللَّٰه","a"],[" تعالیٰ چاہتے رات کو نماز پڑھتے رہتے۔ جب آدھی رات ہو جاتی تو اپنے گھر والوں کو نماز کے لیے اٹھاتے اور فرماتے نماز، اور یہ آیت پڑھتے:",""]]],["q",[["وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا ۖ لَا نَسْـَٔلُكَ رِزْقًا ۖ نَّحْنُ نَرْزُقُكَ ۗ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ  (سورۃ طہ: ۱۳۲)","a"]]],["p",[["ترجمہ: \"اور اپنے متعلقین کو (یعنی اہل خاندان کو یا مومنین کو) بھی نماز کا حکم کرتے رہیے اور خود بھی اس کے پابند رہیے۔ ہم آپ سے (اور دوسروں سے) معاش (کمانا) نہیں چاہتے۔ معاش تو آپ کو ہم دیں گے اور بہتر انجام تو پرہیزگاری ہی کا ہے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Maalik and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.380)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت عثمان بن ابی العاصؓ نے حضرت عمر بن خطابؓ کے (انتقال کے بعد ان) کی ایک بیوی سے شادی کی اور شادی کے موقع پر انھوں نے کہا میں نے ان سے شادی مال اور اولاد کے شوق میں نہیں کی بلکہ اس وجہ سے کی ہے کہ وہ مجھے حضرت عمرؓ کی رات (کے معمولات) کے بارے میں بتائیں۔ چنانچہ شادی کے بعد ان سے پوچھا کہ حضرت عمرؓ کی رات کی نماز کس طرح ہوتی تھی؟ انھوں نے کہا وہ عشاء کی نماز پڑھا کرتے اور ہمیں اس بات کا حکم دیتے کہ ان کے سر کے پاس پانی کا برتن رکھ کر ڈھک دیں (چنانچہ ہم ایسا کیا کرتے)۔ وہ رات کو اٹھتے اور پانی میں ہاتھ ڈال کر اسے اپنے چہرے اور ہاتھوں پر پھیرتے پھر ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے (پھر سو جاتے) اس طرح بار بار اٹھتے اور ",""],["ٱللَّٰه","a"],[" کا کچھ ذکر کرتے یہاں تک کہ ان کی تہجد کی نماز کا وقت ہو جاتا۔ حضرت ابن بریدہؒ (راوی) نے (حضرت حسنؒ سے) پوچھا آپ کو یہ واقعہ کس نے سنایا؟ انھوں نے کہا حضرت عثمان بن ابی العاصؓ کی صاحبزادی نے۔ حضرت ابن بریدہؒ نے کہا وہ تو قابل اعتماد ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.4 Pg.380)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ آدھی رات کو نماز پڑھنا پسند کرتے تھے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.4 Pg.289)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ رات کو کافی دیر تک نماز پڑھتے پھر پوچھتے اے نافع! کیا رات کا آخری حصہ آ گیا؟ میں کہتا نہیں۔ تو پھر نماز پڑھنے لگتے، پھر کہتے اے نافع! کیا رات کا آخری حصہ آ گیا؟ میں کہتا جی ہاں۔ تو بیٹھ کر صبح صادق تک دعا استغفار میں لگے رہتے۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.303), as quoted in Isaabah (Vol.1 Pg.349). Tabraani has reported a similar narration."]]},{"b":[["n",[["حضرت محمدؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ جب بھی رات کو اٹھتے تو نماز شروع کر دیتے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوغالبؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ مکہ میں ہمارے ہاں ٹھہرا کرتے اور رات کو تہجد پڑھا کرتے۔ ایک رات صبح صادق سے کچھ دیر پہلے مجھ سے فرمایا اے ابوغالب! کیا تم کھڑے ہو کر نماز نہیں پڑھتے؟ کیا ہی اچھا ہو اگر تم تہائی قرآن پڑھ لو! میں نے کہا صبح ہونے والی ہے، میں اتنی دیر میں تہائی قرآن کیسے پڑھ سکتا ہوں؟ انھوں نے فرمایا سورت اخلاص قُلْ هُوَ ٱللَّهُ أَحَدٌ تہائی قرآن کے برابر ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت علقمہ بن قیسؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابن مسعودؓ کے ساتھ ایک رات گزاری۔ شروع رات میں وہ سو گئے پھر کھڑے ہو کر نماز پڑھنے لگے اور قرآن ترتیل سے ایسے ٹھہر ٹھہر کر پڑھ رہے تھے جیسے کہ محلہ کی مسجد میں امام پڑھتا ہے اور گانے جیسی آواز نہ تھی اور اتنی اونچی آواز سے پڑھ رہے تھے کہ آس پاس والے سن لیں اور آواز کو گلے میں گھما نہیں رہے تھے۔ جب صبح صادق میں اتنا وقت رہ گیا جتنا مغرب کی اذان سے لے کر نماز مغرب کے ختم ہونے تک کا ہوتا ہے تو پھر انھوں نے وتر پڑھے۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.266)."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں کہ میں نے حضرت سلمانؓ کے ہاں ایک رات یہ دیکھنے کے لیے گزاری کہ وہ رات کو عبادت میں کتنی محنت کرتے ہیں تو یہی دیکھا کہ انھوں نے رات کے آخری حصے میں تہجد کی نماز پڑھی اور جیسا ان کے بارے میں گمان تھا ویسا نظر نہ آیا۔ آخر میں نے یہ بات خود ان سے ذکر کی تو فرمانے لگے کہ ان پانچ نمازوں کی پابندی کرو کیونکہ یہ پانچ نمازیں ان چھوٹے موٹے زخموں (یعنی صغیرہ گناہوں) کو مٹا دیتی ہیں بشرطیکہ کوئی جان لیوا زخم (یعنی گناہ کبیرہ) نہ ہو۔ جب لوگ عشاء کی نماز پڑھ لیتے ہیں تو تین حصوں میں تقسیم ہو جاتے ہیں۔ کچھ لوگ تو وہ ہیں جن کے لیے یہ رات رحمت ہے وبال نہیں، اور کچھ لوگ وہ ہیں جن کے لیے یہ رات وبال ہے رحمت نہیں، اور کچھ لوگ وہ ہیں جن کے لیے نہ رحمت ہے نہ وبال۔ جو لوگ رات کی تاریکی اور لوگوں کی غفلت کو غنیمت سمجھ کر بے دھڑک گناہوں میں لگ جاتے ہیں ان کے لیے یہ رات وبال ہے رحمت نہیں، اور جو لوگ رات کی تاریکی اور لوگوں کی غفلت کو غنیمت سمجھ کر کھڑے ہو کر نماز پڑھنے لگ جاتے ہیں ان کے لیے یہ رات رحمت ہے وبال نہیں، اور جو عشاء پڑھ کر سو جاتے ہیں ان کے لیے نہ رحمت ہے اور نہ وبال۔ تم تیز رفتاری سے بچو اور میانہ روی اختیار کرو اور جتنا کرو اسے پابندی سے کرو۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.401)."]]}]},"39":{"lead":[],"stories":[{"b":[["n",[["حضرت ام ہانی فاختہ بنت ابی طالبؓ","b"],[" فرماتی ہیں کہ فتح مکہ کے موقع پر میں حضورؐ کی خدمت میں گئی، حضورؐ اس وقت غسل فرما رہے تھے۔ جب آپؐ غسل سے فارغ ہوئے تو آپؐ نے آٹھ رکعت نماز پڑھی اور یہ چاشت کا وقت تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim, as quoted in Riyaadh (Pg.424)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ چاشت کے وقت چار رکعت پڑھا کرتے تھے اور کبھی اس سے زیادہ بھی پڑھتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Muslim, as quoted in Riyaadh."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ کو چاشت کی چھ رکعت نماز پڑھتے ہوئے دیکھا۔ اس کے بعد میں نے یہ رکعتیں کبھی نہیں چھوڑیں۔ ",""],["حضرت ام ہانیؓ","b"],[" فرماتی ہیں حضورؐ فتح مکہ کے دن میرے پاس تشریف لائے اور چاشت کی چھ رکعت نماز پڑھی۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.2 Pg.237) has commented on the chain of narrators."],["(4)","Tabraani in his Awsat and Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.238)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی اوفیؓ","b"],[" نے چاشت کی دو رکعت نماز پڑھی تو ان کی بیوی نے ان سے کہا آپ نے تو دو رکعت نماز پڑھی ہے۔ انھوں نے فرمایا جب حضورؐ کو فتح کی بشارت ملی تھی اس وقت بھی آپؐ نے چاشت کی دو رکعت نماز پڑھی تھی اور جب آپؐ کو ابوجہل کے سر کی بشارت ملی تھی اس وقت بھی دو رکعت نماز پڑھی تھی۔",""],[" (5)","s"]]]],"f":[["(5)","Bazzaar and Tabraani. Haythami (Vol.2 Pg.238) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب پڑھتے پڑھتے میں اس آیت پر گزرتا:",""]]],["q",[["يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ  (سورۃ ص: ۱۸)","a"]]],["p",[["ترجمہ: \"شام اور صبح تسبیح کیا کریں\" تو مجھے یہ نہیں پتہ تھا کہ اس کا کیا مطلب ہے؟ یہاں تک کہ حضرت ام ہانی بنت ابی طالبؓ نے مجھے بتایا کہ حضورؐ میرے پاس آئے اور ایک پیالہ میں وضو کا پانی منگوایا۔ میں دیکھ رہی تھی کہ اس پیالے میں آٹے کا اثر تھا۔ حضورؐ نے وضو کیا اور پھر چاشت کی نماز پڑھی، پھر فرمایا اے ام ہانی! یہ اشراق کی نماز ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.2 Pg.238) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ حضورؐ نے ایک لشکر بھیجا، وہ بہت سا مال غنیمت لے کر بہت ہی جلدی واپس آ گیا۔ ایک آدمی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم نے ایسا لشکر کبھی نہیں دیکھا جو اس سے زیادہ جلدی واپس آ گیا ہو اور اس سے زیادہ مال غنیمت لے کر آیا ہو۔ حضورؐ نے فرمایا کیا میں تمہیں اس سے جلدی واپس آنے والا اور اس سے زیادہ مال غنیمت حاصل کرنے والا آدمی نہ بتاؤں؟ یہ وہ آدمی ہے جو اچھی طرح سے وضو کرے پھر مسجد میں جا کر صبح کی نماز پڑھے پھر اس کے بعد چاشت کی نماز پڑھے تو یہ آدمی بہت زیادہ مال غنیمت لے کر بہت جلد واپس آ گیا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Ya'la, Bazzaar, Ibn Hibbaan and Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.428)."]]},{"b":[["n",[["حضرت عطاء ابومحمدؒ","b"],[" کہتے ہیں میں نے حضرت علیؓ کو مسجد میں چاشت کی نماز پڑھتے ہوئے دیکھا۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani, as quoted in Kanzul Ummaal (Vol.4 Pg.281)."]]},{"b":[["n",[["حضرت عکرمہؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ ایک دن چاشت کی نماز پڑھتے اور دس دن چھوڑ دیتے۔",""],["(9)","s"],[" ",""],["حضرت عائشہ بنت سعدؒ","b"],[" کہتی ہیں حضرت سعدؓ چاشت کی آٹھ رکعت نماز پڑھا کرتے تھے۔",""],[" (10)","s"]]]],"f":[["(9)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.2 Pg.282)."],["(10)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.2 Pg.283)."]]}]},"40":{"lead":[],"stories":[{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ چاشت کی نماز نہیں پڑھتے تھے بلکہ ظہر اور عصر کے درمیان نفل پڑھتے تھے اور رات کو بڑی لمبی تہجد پڑھتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Kabeer. Haythami (Vol.2 Pg.258) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ ظہر سے عصر تک نماز پڑھتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.304)."]]}]},"41":{"lead":[],"stories":[{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں میں حضورؐ کے پاس گیا اور حضورؐ کے ساتھ مغرب کی نماز پڑھی پھر حضورؐ عشاء تک نماز پڑھتے رہے۔",""],[" (1)","s"]]]],"f":[["(1)","Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.369)."]]},{"b":[["n",[["حضرت محمد بن عمار بن یاسرؓ","b"],[" کہتے ہیں کہ میں نے حضرت عمار بن یاسرؓ کو مغرب کے بعد چھ رکعت نماز پڑھتے ہوئے دیکھا اور حضرت عمارؓ نے فرمایا میں نے اپنے محبوب حضورؐ کو مغرب کے بعد چھ رکعت نماز پڑھتے ہوئے دیکھا اور حضورؐ نے فرمایا کہ جو مغرب کے بعد چھ رکعت نماز پڑھے گا اس کے تمام گناہ معاف کر دیے جائیں گے چاہے وہ سمندر کی جھاگ کے برابر ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani in his Thalaatha. Tabraani and Mundhiri (Vol.1 Pg.368) have commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبدالرحمن بن یزیدؒ","b"],[" کہتے ہیں کہ ایک وقت ایسا ہے جس میں جب بھی میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کے پاس گیا انہیں نماز پڑھتے ہوئے ہی پایا اور وہ مغرب اور عشاء کے درمیان کا وقت ہے۔ میں نے حضرت عبد",""],["ٱللَّٰه","a"],["ؓ سے پوچھا ایک وقت ایسا ہے جس میں جب بھی میں آپ کے پاس آتا ہوں تو آپ کو نماز پڑھتے ہوئے پاتا ہوں۔ انھوں نے فرمایا کہ یہ فرصت کا وقت ہے (یا غفلت کی گھڑی ہے)، اس وقت لوگ اپنے کھانے پینے وغیرہ میں لگ جاتے ہیں اور ",""],["ٱللَّٰه","a"],[" سے غافل ہو جاتے ہیں، اس لیے میں غفلت کی اس گھڑی میں عبادت کرتا ہوں۔",""],["(3)","s"],[" ",""],["حضرت اسود بن یزیدؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ نے فرمایا غفلت کی گھڑی یعنی مغرب اور عشاء کے درمیان نفل نماز پڑھنا بہترین عمل ہے۔",""],[" (4)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.2 Pg.230) has commented on the chain of narrators."],["(4)","Tabraani. Haythami (Vol.2 Pg.230) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں فرشتے ان لوگوں کو گھیر لیتے ہیں جو مغرب اور عشاء کے درمیان نفل پڑھتے ہیں اور یہ اوابین کی نماز ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.4 Pg.193)."]]}]},"42":{"lead":[],"stories":[{"b":[["n",[["حضرت عبدالرحمن بن ابی لیلیٰؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ (کے بعد ان) کی بیوی سے شادی کی۔ اس نے ان کی بیوی سے ان کے کسی خاص عمل کے بارے میں پوچھا۔ اس نے کہا وہ جب بھی گھر سے باہر جانے کا ارادہ کرتے تو دو رکعت نماز پڑھتے اور جب بھی گھر میں داخل ہوتے تو بھی دو رکعت نماز پڑھتے۔ اپنے اس معمول کو کبھی نہیں چھوڑتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Mubaarak, as quoted in Isaabah (Vol.2 Pg.306)."]]}]},"43":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ رمضان میں رات کو تراویح پڑھنے کی ترغیب دیتے تھے لیکن اس کے واجب ہونے کا حکم نہیں دیتے تھے۔ چنانچہ فرماتے تھے جو رمضان کی راتوں میں تراویح ایمان و یقین کے ساتھ ثواب حاصل کرنے کے شوق میں پڑھے گا اس کے گزشتہ تمام گناہ معاف کر دیے جائیں گے۔ ایک",""],["(1)","s"],[" روایت میں یہ ہے کہ پھر حضورؐ کا انتقال ہو گیا اور یہ سلسلہ یونہی چلتا رہا اور پھر حضرت ابوبکرؓ کے زمانے میں اور حضرت عمرؓ کے شروع زمانے میں یہ سلسلہ اسی طرح چلتا رہا۔",""],[" (2)","s"]]]],"f":[["(1)","Muslim, as quoted in Riyaadh."],["(2)","Bukhaari, Muslim, Abu Dawood, Tirmidhi, Nasa'ee and Ibn Maajah, as quoted in Jam'ul Fawaa'id."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ حضورؐ ایک مرتبہ رمضان میں باہر تشریف لائے تو آپؐ نے دیکھا کہ کچھ لوگ مسجد کے ایک کونے میں نماز پڑھ رہے ہیں۔ حضورؐ نے پوچھا یہ لوگ کون ہیں؟ صحابہؓ نے عرض کیا ان میں قرآن کا حافظ کوئی نہیں ہے اس لیے حضرت ابی بن کعبؓ انہیں نماز پڑھا رہے ہیں اور یہ ان کے پیچھے پڑھ رہے ہیں۔ حضورؐ نے فرمایا انہوں نے ٹھیک کیا اور ان کا یہ کام بہت اچھا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Dawood, as quoted in Jam'ul Fawaa'id."]]},{"b":[["n",[["حضرت عبدالرحمن بن عبدالقاریؒ","b"],[" کہتے ہیں رمضان کی ایک رات میں حضرت عمر بن خطابؓ کے ساتھ مسجد میں گیا۔ لوگ مختلف ٹولیوں میں بٹے ہوئے تھے، کوئی اپنی نماز پڑھ رہا تھا اور ایک جماعت اس کے ساتھ پڑھ رہی تھی۔ حضرت عمرؓ نے کہا میرا خیال یہ ہو رہا ہے کہ اگر میں ان سب کو ایک حافظ قرآن کے پیچھے کھڑا کر دوں تو یہ زیادہ بہتر رہے گا۔ پھر حضرت عمرؓ نے اس کا پختہ ارادہ کر لیا اور ان سب کو حضرت ابی بن کعبؓ کے پیچھے جمع کر دیا۔ پھر میں حضرت عمرؓ کے ساتھ دوسری رات پھر گیا اور لوگ اپنے قاری (حضرت ابی بن کعبؓ) کے پیچھے نماز پڑھ رہے تھے۔ حضرت عمرؓ نے فرمایا یہ بہت اچھی بدعت ہے لیکن تم شروع رات میں تو تراویح پڑھتے ہو اور آخر راتوں میں تہجد چھوڑ کر سو جاتے ہو۔ میرے نزدیک تہجد تراویح سے افضل ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Maalik, Bukhaari, Ibn Khuzaymah and others, as quoted in Kanzul Ummaal and Jam'ul Fawaa'id."]]},{"b":[["n",[["حضرت نوفل بن ایاس ہذلیؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت عمر بن خطابؓ کے زمانے میں رمضان میں مختلف جماعتوں میں تراویح پڑھا کرتے تھے۔ ایک جماعت یہاں تراویح پڑھ رہی ہے اور ایک وہاں۔ جس امام کی آواز زیادہ اچھی ہوتی لوگ اس کی طرف زیادہ چلے جاتے۔ اس پر حضرت عمرؓ نے فرمایا میرے خیال میں لوگوں نے قرآن کو گانے کی چیز بنا لیا ہے۔ غور سے سنو ",""],["ٱللَّٰه","a"],[" کی قسم! میرا بس چلا تو اس صورت حال کو ضرور بدل دوں گا۔ چنانچہ تین ہی دن کے بعد حضرت عمرؓ نے حضرت ابی بن کعبؓ کو حکم دیا اور انہوں نے تمام لوگوں کو اکٹھا کر کے تراویح کی نماز پڑھائی۔ پھر حضرت عمرؓ نے آخری صف میں کھڑے ہو کر فرمایا ہے تو یہ (تراویح کا ایک جماعت بن کر پڑھنا) بدعت لیکن بہت عمدہ۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.5 Pg.59)."]]},{"b":[["n",[["حضرت ابواسحاق ہمدانیؒ","b"],[" کہتے ہیں حضرت علی بن ابی طالبؓ رمضان کی پہلی رات میں باہر تشریف لائے تو دیکھا کہ قندیلیں روشن ہیں اور ",""],["ٱللَّٰه","a"],[" کی کتاب پڑھی جا رہی ہے۔ حضرت علیؓ نے فرمایا اے ابن خطاب! جیسے تم نے ",""],["ٱللَّٰه","a"],[" کی مسجدوں کو قرآن سے منور کیا ہے ایسے ہی ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری قبر کو منور فرمائے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Shaaheen, as quoted in Kanzul Ummaal (Vol.4 Pg.284). Khateeb in his Amaali and Ibn Asaakir have reported a similar narration, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.387)."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ نے رمضان میں تراویح کو ایک بڑی جماعت میں پڑھنے کا سلسلہ شروع کیا اور مردوں کے لیے حضرت ابی بن کعبؓ کو امام مقرر کیا اور عورتوں کے لیے حضرت سلیمان بن ابی حثمہؓ کو۔",""],[" (7)","s"]]]],"f":[["(7)","Firyaabi and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.283)."]]},{"b":[["n",[["حضرت عمر بن عبد","b"],["ٱللَّٰه","a"],[" عنسیؒ","b"],[" کہتے ہیں حضرت ابی بن کعبؓ اور حضرت تمیم داریؓ نبی کریمؐ کی جگہ کھڑے ہو کر مردوں کو تراویح کی نماز باری باری پڑھایا کرتے تھے اور حضرت سلیمان بن ابی حثمہؓ مسجد کے صحن میں عورتوں کو تراویح پڑھایا کرتے تھے۔ جب حضرت عثمان بن عفانؓ خلیفہ بنے تو انہوں نے مردوں، عورتوں سب کے لیے ایک ہی امام مقرر کر دیا یعنی حضرت سلیمان بن ابی حثمہؓ کو۔ اور حضرت عثمانؓ کے فرمانے پر تراویح کے بعد عورتوں کو روک لیا جاتا۔ جب مرد چلے جاتے پھر انہیں چھوڑا جاتا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.5 Pg.26)."]]},{"b":[["n",[["حضرت عرفجہؒ","b"],[" کہتے ہیں حضرت علی بن ابی طالبؓ لوگوں کو رمضان میں تراویح پڑھنے کا حکم دیتے اور مردوں کے لیے ایک امام مقرر کرتے اور عورتوں کے لیے دوسرا۔ چنانچہ میں عورتوں کا امام ہوا کرتا۔",""],[" (9)","s"]]]],"f":[["(9)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.284)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ حضرت ابی بن کعبؓ نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آج رات مجھ سے ایک کام ہو گیا اور یہ واقعہ رمضان کا ہے۔ حضورؐ نے فرمایا اے ابی! کیا ہوا؟ انہوں نے عرض کیا میرے گھر میں چند عورتیں تھیں، ان عورتوں نے کہا ہم نے قرآن نہیں پڑھا، ہم آپ کے پیچھے تراویح کی نماز پڑھیں گی۔ چنانچہ میں نے انہیں آٹھ رکعت نماز پڑھائی اور وتر بھی پڑھائے۔ حضورؐ نے اس پر کچھ نہ فرمایا، اس طرح آپؐ کی رضامندی کی بناء پر یہ سنت ہو گئی۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Ya'la and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.2 Pg.74)."]]}]},"44":{"lead":[],"stories":[{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں ایک دن صبح کے وقت حضورؐ نے حضرت بلالؓ کو بلا کر فرمایا اے بلال! تم کس عمل کی وجہ سے مجھ سے پہلے جنت میں چلے گئے؟ آج رات میں جنت میں داخل ہوا تو میں نے اپنے آگے تمہارے چلنے کی آہٹ سنی۔ انھوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب بھی مجھ سے گناہ ہو جاتا ہے تو میں فوراً دو رکعت صلوٰۃ التوبہ پڑھتا ہوں اور جب بھی میرا وضو ٹوٹتا ہے تو میں اسی وقت فوراً وضو کر کے دو رکعت نفل (تحیۃ الوضو) پڑھتا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.437)."]]}]},"45":{"lead":[],"stories":[{"b":[["n",[["حضرت ثمامہ بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں حضرت انس بن مالکؓ کے باغ کا مالی سخت گرمی کے زمانے میں ان کے پاس آیا اور ان سے موسم کی خشکی اور بارش نہ ہونے کی شکایت کی۔ حضرت انسؓ نے پانی منگا کر وضو کیا اور نماز پڑھی، پھر مالی سے کہا کیا تمہیں کوئی بادل آسمان میں نظر آ رہا ہے؟ اس نے کہا کوئی نظر نہیں آ رہا ہے۔ حضرت انسؓ نے اندر جا کر پھر نماز پڑھی، پھر اس سے (یہی) کہا۔ اس طرح تین چار مرتبہ ہوا۔ تیسری یا چوتھی مرتبہ اس مالی کو دیکھنے کو کہا تو اس نے کہا پرندے کے پر جتنا بادل آ رہا ہے۔ حضرت انسؓ نماز پڑھتے رہے اور دعا مانگتے رہے یہاں تک کہ باغ کے ذمہ دار نے اندر جا کر ان کو بتایا کہ آسمان پر بادل چھا گئے اور بارش ہو چکی ہے تو اس نے فرمایا وہ گھوڑا جو حضرت بشر بن شغاف نے بھیجا ہے اس پر سوار ہو کر جاؤ اور دیکھو بارش کہاں تک ہوئی ہے؟ چنانچہ وہ دیکھ کر آیا اور اس نے بتایا کہ بارش مسیرین کے محلات اور غضبان کے محل سے آگے نہیں ہوئی (یعنی حضرت انسؓ کے باغات میں ہی ہوئی ہے، اس سے آگے نہیں ہوئی)۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.7 Pg.21)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں مجھے ایک دفعہ بہت زیادہ درد ہوا۔ حضورؐ کی خدمت میں گیا (اور اپنی تکلیف حضورؐ کو بتائی) حضورؐ نے مجھے اپنی جگہ بٹھایا اور خود کھڑے ہو کر نماز پڑھنے لگے اور اپنے کپڑے کا ایک کنارہ میرے اوپر ڈال دیا۔ پھر فرمایا اے ابن ابی طالب! کوئی بات نہیں، تم ٹھیک ہو جاؤ گے۔ میں نے ",""],["ٱللَّٰه","a"],[" سے اپنے لیے جو چیز بھی مانگی وہی میں نے تمہارے لیے بھی مانگی اور ",""],["ٱللَّٰه","a"],[" سے میں نے جو چیز بھی مانگی وہ ",""],["ٱللَّٰه","a"],[" نے مجھے ضرور عطا فرمائی، البتہ مجھے یہ کہا گیا کہ تمہارے بعد کوئی نبی نہیں ہوگا۔ حضرت علیؓ نے فرمایا میں وہاں سے کھڑا ہوا تو سارا درد ختم ہو چکا تھا اور ایسے لگ رہا تھا کہ جیسے مجھے کوئی تکلیف ہی نہ ہوئی ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Aasim, Ibn Jareer, Tabraani in his Awsat and Ibn Shaaheen in his Sunnah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.43)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضورؐ کے ایک صحابی کی کنیت ابومعلق تھی اور وہ تاجر تھے۔ اپنے اور دوسروں کے مال سے تجارت کیا کرتے تھے اور وہ بہت زیادہ عبادت گزار اور پرہیز گار تھے۔ ایک مرتبہ وہ سفر میں گئے، انہیں راستہ میں ایک ہتھیاروں سے مسلح ڈاکو ملا۔ اس نے کہا اپنا سارا سامان یہاں رکھ دو، میں تمہیں قتل کروں گا۔ اس صحابی نے کہا تم نے مال لینا ہے وہ لے لو۔ ڈاکو نے کہا نہیں، میں تو تمہارا خون بہانا چاہتا ہوں۔ اس صحابی نے کہا مجھے ذرا مہلت دو میں نماز پڑھ لوں۔ اس نے کہا جتنی پڑھنی ہے پڑھ لو۔ چنانچہ انھوں نے وضو کر کے نماز پڑھی اور یہ دعا تین مرتبہ مانگی:",""]]],["q",[["يَا ذَا ٱلْعَرْشِ ٱلْمَجِيدِ، يَا وَدُودُ، يَا فَعَّالُ لِمَا يُرِيدُ، أَسْأَلُكَ بِعِزَّتِكَ ٱلَّتِي لَا تُرَامُ، وَمُلْكِكَ ٱلَّذِي لَا يُضَامُ، وَبِنُورِكَ ٱلَّذِي مَلَأَ أَرْكَانَ عَرْشِكَ، أَن تَكْفِيَنِي شَرَّ هَٰذَا ٱللِّصِّ، يَا مُغِيثُ أَغِثْنِي","a"]]],["p",[["ترجمہ: \"اے عرش مجید والے! اے محبت کرنے والے! اے جو چاہے کر گزرنے والے! میں تیری اس عزت کے واسطے سے جس تک کوئی پہنچ نہیں سکتا، اور تیری اس بادشاہت کے واسطے سے جو کبھی مغلوب نہیں ہوتی، اور تیرے اس نور کے واسطے سے جس نے تیرے عرش کے ارکان کو بھر رکھا ہے، تجھ سے سوال کرتا ہوں کہ اس ڈاکو کے شر سے مجھے کافی ہو جا۔ اے فریاد رس! میری فریاد رسی فرما۔\"",""]]],["p",[["تو اچانک ایک گھوڑے سوار نمودار ہوا جس کے ہاتھ میں ایک نیزہ تھا جسے اٹھا کر اس نے اپنے گھوڑے کے کانوں کے درمیان بلند کیا ہوا تھا۔ اس نے اس ڈاکو کو نیزہ مار کر قتل کر دیا۔ پھر وہ اس تاجر کی طرف متوجہ ہوا۔ تاجر نے پوچھا تم کون ہو؟ ",""],["ٱللَّٰه","a"],[" نے تمہارے ذریعہ سے میری مدد فرمائی ہے۔ اس نے کہا میں چوتھے آسمان کا فرشتہ ہوں۔ جب آپ نے (پہلی مرتبہ) دعا کی تو میں نے آسمان کے دروازوں کی کھڑکھڑاہٹ سنی۔ جب آپ نے دوبارہ دعا کی تو میں نے آسمان والوں کی چیخ و پکار سنی، پھر آپ نے تیسری مرتبہ دعا کی تو کسی نے کہا یہ ایک مصیبت زدہ کی دعا ہے۔ میں نے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی بارگاہ میں عرض کیا کہ اس ڈاکو کو قتل کرنے کا کام میرے ذمہ کر دیں۔ پھر اس فرشتے نے کہا آپ کو خوشخبری ہو کہ جو آدمی بھی وضو کر کے چار رکعت نماز پڑھے اور پھر یہ دعا مانگے اس کی دعا حاضر اور قبول ہوگی چاہے وہ مصیبت زدہ ہو یا نہ ہو۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Dunya in his Mujaabud Da'wah, as quoted in Isaabah (Vol.4 Pg.182)."]]}]}}});
